local Services = {}
local Knit

local S = {}

function S.getKnit()
    if Knit then
        return Knit
    end

    local packages = ReplicatedStorage:WaitForChild("Packages", 30)
    if not packages then
        return nil
    end

    local knitModule = packages:WaitForChild("Knit", 30)
    if not knitModule then
        return nil
    end

    local ok, lib = pcall(require, knitModule)
    if ok then
        Knit = lib
    end

    return Knit
end

-- ========== MiyuGUI OBSIDIAN (Rayfield-shaped adapter) ==========
local Rayfield

function S.getExecutorName()
    if typeof(identifyexecutor) == "function" then
        local ok, name = pcall(identifyexecutor)
        if ok and type(name) == "string" and name ~= "" then
            return name
        end
    end
    return "Unknown"
end

function S.copyToClipboard(text)
    text = tostring(text or "")
    if text == "" then
        return false
    end
    if typeof(setclipboard) == "function" then
        setclipboard(text)
        return true
    end
    if typeof(toclipboard) == "function" then
        toclipboard(text)
        return true
    end
    if syn and typeof(syn.write_clipboard) == "function" then
        syn.write_clipboard(text)
        return true
    end
    return false
end

function S.httpGetText(url)
    local ok, body = pcall(function()
        return game:HttpGet(url, true)
    end)
    if ok and type(body) == "string" and body ~= "" then
        return stripBom(body)
    end
    return nil
end

function S.httpPostJson(url, payload)
    local headers = { ["Content-Type"] = "application/json", Accept = "application/json" }
    local req = { Url = url, Method = "POST", Headers = headers, Body = payload }
    local reqAlt = { url = url, method = "POST", headers = headers, body = payload }
    local fns = {}
    local seen = {}
    local function add(fn)
        if type(fn) == "function" and not seen[fn] then
            seen[fn] = true
            table.insert(fns, fn)
        end
    end
    pcall(function()
        if syn then
            add(syn.request)
            add(syn.http_request)
        end
    end)
    pcall(function()
        add(http_request)
    end)
    pcall(function()
        add(request)
    end)
    pcall(function()
        if http then
            add(http.request)
        end
    end)
    pcall(function()
        if fluxus then
            add(fluxus.request)
        end
    end)
    if typeof(getgenv) == "function" then
        local g = getgenv()
        add(g.http_request)
        add(g.request)
    end
    for i = 1, #fns do
        if pcall(fns[i], req) or pcall(fns[i], reqAlt) then
            return true
        end
    end
    if type(game.HttpPost) == "function" then
        if pcall(function()
            return game:HttpPost(url, payload, "application/json")
        end) then
            return true
        end
    end
    if type(game.HttpPostAsync) == "function" then
        if pcall(function()
            return game:HttpPostAsync(url, payload, "application/json")
        end) then
            return true
        end
    end
    return false
end

function S.runSourceSafe(source, chunkName)
    local ok, result = pcall(runSource, source, chunkName)
    if ok then
        return result
    end
    return nil
end

function S.validHub(mod)
    return type(mod) == "table" and type(mod.create) == "function"
end

function S.buildMiyuGUIHub()
    local Hub = {}
    Hub._afkConn = nil
    Hub._presenceRunning = false

    function Hub.setAntiAfk(enabled)
        if Hub._afkConn then
            Hub._afkConn:Disconnect()
            Hub._afkConn = nil
        end
        if not enabled then
            return
        end
        local player = LocalPlayer or Players.LocalPlayer
        if not player then
            return
        end
        local vu = game:GetService("VirtualUser")
        Hub._afkConn = player.Idled:Connect(function()
            pcall(function()
                vu:CaptureController()
                vu:ClickButton2(Vector2.new(0, 0))
            end)
        end)
    end

    function Hub.notify(Library, text, duration)
        if Library and Library.Notify then
            pcall(function()
                Library:Notify(tostring(text), duration or 4)
            end)
        end
    end

    function Hub.startPresence()
        -- Removed: no data is sent to any external server.
    end

    local function httpGetObsidian(path)
        local body = S.httpGetText(MiyuGUI.obsidian .. path)
        if not body then
            error("[MiyuGUI] Obsidian download failed: " .. path)
        end
        local lib = S.runSourceSafe(body, path)
        if not lib then
            error("[MiyuGUI] Obsidian load failed: " .. path)
        end
        return lib
    end

    -- Theme from the reference picture: soft mint background, fresh green accent.
    local MIYU_THEME = {
        FontColor = "1f4a26",
        MainColor = "f1fbed",
        AccentColor = "43b04a",
        BackgroundColor = "dcf2d4",
        OutlineColor = "86cf84",
    }

    function Hub.loadObsidian()
        local g = typeof(getgenv) == "function" and getgenv() or nil
        local existing = g and g.MiyuGUI_OBSIDIAN_LIBRARY
        if existing and existing.Unloaded ~= true then
            pcall(function()
                if type(existing.UnloadSignals) == "table" then
                    table.clear(existing.UnloadSignals)
                end
                if type(existing.Unload) == "function" then
                    existing:Unload()
                end
            end)
        end
        if g then
            g.MiyuGUI_OBSIDIAN_READY = nil
            g.MiyuGUI_OBSIDIAN_LIBRARY = nil
            g.MiyuGUI_OBSIDIAN_SAVE = nil
            g.MiyuGUI_OBSIDIAN_THEME = nil
        end
        local Library = httpGetObsidian("Library.lua")
        local ThemeManager = httpGetObsidian("addons/ThemeManager.lua")
        local SaveManager = httpGetObsidian("addons/SaveManager.lua")
        ThemeManager:SetLibrary(Library)
        SaveManager:SetLibrary(Library)
        pcall(function()
            ThemeManager:SetDefaultTheme({
                FontColor = MIYU_THEME.FontColor,
                MainColor = MIYU_THEME.MainColor,
                AccentColor = MIYU_THEME.AccentColor,
                BackgroundColor = MIYU_THEME.BackgroundColor,
                OutlineColor = MIYU_THEME.OutlineColor,
                BackgroundImage = "",
                FontFace = "Gotham",
            })
        end)
        SaveManager:IgnoreThemeSettings()
        SaveManager:SetIgnoreIndexes({
            "MenuKeybind",
            "terra_autofarm",
            "terra_shop_depth_hud",
            "terra_shop_hud_alerts",
            "terra_shop_check_all",
            "terra_shop_auto_buy",
            "terra_shop_watch_tools",
            "terra_shop_watch_armors",
            "terra_shop_watch_ammos",
            "terra_shop_watch_consumables",
            "terra_shop_watch_medicals",
            "terra_af_ore_worms",
            "miyugui_manual_save_gear_pick",
            "miyugui_dtec_drill_depth_m",
            "miyugui_dtec_player_depth_m",
            "miyugui_farm_drill_depth_m",
            "miyugui_farm_player_depth_m",
        })
        Library.ShowToggleFrameInKeybinds = true
        Library.ShowCustomCursor = false
        Library.NotifySide = "Right"
        if typeof(getgenv) == "function" then
            getgenv().MiyuGUI_OBSIDIAN_LIBRARY = Library
            getgenv().MiyuGUI_OBSIDIAN_SAVE = SaveManager
            getgenv().MiyuGUI_OBSIDIAN_THEME = ThemeManager
            getgenv().MiyuGUI_OBSIDIAN_READY = true
            getgenv().MiyuGUI_HUB_WINDOW = Hub
        end
        return Library, SaveManager, ThemeManager
    end

    -- ---------- Remove the "Lock" button (shown when the GUI is closed) ----------
    function Hub.removeLockButton(Library)
        local function isLock(obj)
            return (obj:IsA("TextButton") or obj:IsA("TextLabel"))
                and (obj.Text == "Lock" or obj.Text == "Unlock")
        end
        local function kill(obj)
            local target = obj
            for _ = 1, 3 do
                local par = target.Parent
                if par and par:IsA("GuiObject") and par.AbsoluteSize.X < 170 and par.AbsoluteSize.Y < 70 then
                    target = par
                else
                    break
                end
            end
            pcall(function()
                target:Destroy()
            end)
        end
        local root = Library.ScreenGui
        if not root then
            return
        end
        pcall(function()
            Library.CantDragForced = false
        end)
        for _, d in ipairs(root:GetDescendants()) do
            if isLock(d) then
                kill(d)
            end
        end
        root.DescendantAdded:Connect(function(d)
            task.defer(function()
                if d.Parent and isLock(d) then
                    kill(d)
                end
            end)
        end)
    end

