    local function b64decode(data)
        data = data:gsub("%s", "")
        local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local lookup = {}
        for i = 1, #chars do
            lookup[chars:byte(i)] = i - 1
        end
        local out, n = {}, 0
        for i = 1, #data - 3, 4 do
            local a, b, c, d = data:byte(i, i + 3)
            local va, vb = lookup[a], lookup[b]
            local vc, vd = lookup[c], lookup[d]
            if va and vb then
                local v = va * 262144 + vb * 4096 + (vc or 0) * 64 + (vd or 0)
                n += 1
                out[n] = string.char(math.floor(v / 65536) % 256)
                if vc then
                    n += 1
                    out[n] = string.char(math.floor(v / 256) % 256)
                end
                if vd then
                    n += 1
                    out[n] = string.char(v % 256)
                end
            end
        end
        return table.concat(out)
    end

    function Hub.getBackgroundAsset()
        local getAsset = (typeof(getcustomasset) == "function" and getcustomasset)
            or (typeof(getsynasset) == "function" and getsynasset)
        if not getAsset or typeof(writefile) ~= "function" then
            return nil
        end
        local folder = "miyugui_hub"
        pcall(function()
            if typeof(isfolder) == "function" and not isfolder(folder) then
                makefolder(folder)
            end
        end)
        local path = folder .. "/background.jpg"
        local needWrite = true
        pcall(function()
            if typeof(isfile) == "function" and isfile(path) then
                needWrite = false
            end
        end)
        if needWrite then
            local ok = pcall(function()
                writefile(path, b64decode(BG_B64))
            end)
            if not ok then
                return nil
            end
        end
        local ok, asset = pcall(getAsset, path)
        return ok and asset or nil
    end

    function Hub.applyBackground(Library)
        local asset = Hub.getBackgroundAsset()
        local root = Library.ScreenGui
        if not asset or not root then
            return
        end
        -- Remove any older copy of the picture.
        for _, d in ipairs(root:GetDescendants()) do
            if d.Name == "MiyuBackground" then
                d:Destroy()
            end
        end
        -- The window frame = the top-most ancestor of the window title that is NOT screen-sized.
        local cam = workspace.CurrentCamera
        local vp = cam and cam.ViewportSize or Vector2.new(1280, 720)
        local titleLabel
        for _, d in ipairs(root:GetDescendants()) do
            if d:IsA("TextLabel") and d.Text == "MiyuGUI Hub" then
                titleLabel = d
                break
            end
        end
        if not titleLabel then
            return
        end
        local main
        local cur = titleLabel.Parent
        while cur and cur ~= root do
            if cur:IsA("GuiObject") then
                local sz = cur.AbsoluteSize
                if sz.X >= vp.X * 0.98 and sz.Y >= vp.Y * 0.98 then
                    break
                end
                main = cur
            end
            cur = cur.Parent
        end
        if not main or main.AbsoluteSize.X < 150 or main.AbsoluteSize.Y < 100 then
            return
        end
        local img = Instance.new("ImageLabel")
        img.Name = "MiyuBackground"
        img.BackgroundTransparency = 1
        img.Size = UDim2.new(1, 0, 1, 0)
        img.Image = asset
        img.ImageTransparency = 0.55
        img.ScaleType = Enum.ScaleType.Crop
        img.ZIndex = 0
        img.Active = false
        img.ClipsDescendants = true
        local corner = main:FindFirstChildOfClass("UICorner")
        if corner then
            corner:Clone().Parent = img
        end
        img.Parent = main
        -- Let the picture show through the big panels (small widgets stay solid).
        for _, d in ipairs(main:GetDescendants()) do
            if (d:IsA("Frame") or d:IsA("ScrollingFrame")) and d.BackgroundTransparency < 0.05 then
                local sz = d.AbsoluteSize
                if sz.X > 140 and sz.Y > 110 then
                    d.BackgroundTransparency = 0.3
                end
            end
        end
    end

    function Hub.create(options)
        options = options or {}
        local Library, SaveManager, ThemeManager = Hub.loadObsidian()
        local version = tostring(options.Version or MiyuGUI.version):gsub("^v", "")
        ThemeManager:SetFolder("miyugui_hub")
        SaveManager:SetFolder("miyugui_hub/universe_" .. tostring(game.GameId))
        local camNow = workspace.CurrentCamera
        local vpNow = camNow and camNow.ViewportSize or Vector2.new(1280, 720)
        local Window = Library:CreateWindow({
            Title = "MiyuGUI Hub",
            Footer = "v" .. version .. " · MiyuGUI",
            Center = true,
            AutoShow = true,
            Resizable = true,
            MobileButtonsSide = "Left",
            ShowCustomCursor = false,
            NotifySide = "Right",
            Icon = "sparkles",
            DisableSearch = true,
            Size = UDim2.fromOffset(
                math.min(620, math.max(300, vpNow.X - 40)),
                math.min(460, math.max(220, vpNow.Y - 60))
            ),
            CornerRadius = 8,
        })
        Library:OnUnload(function()
            Hub.setAntiAfk(false)
            Hub._presenceRunning = false
            if type(S.unloadMiyuGUIDtec) == "function" then
                S.unloadMiyuGUIDtec()
            end
        end)
        pcall(Hub.removeLockButton, Library)
        if options.ShowHomeTab ~= false then
            Hub.addHomeTab(Window, Library, options)
        end
        return Window, Library, SaveManager, ThemeManager, {
            gameTitle = options.Game or MiyuGUI.game,
            version = version,
        }
    end

    function Hub.addHomeTab(Window, Library, options)
        options = options or {}
        local tab = Window:AddTab("Home", "house")

        local welcome = tab:AddLeftGroupbox("MiyuGUI Hub", "sparkles")
        welcome:AddLabel("Welcome, " .. (LocalPlayer and (LocalPlayer.DisplayName ~= "" and LocalPlayer.DisplayName or LocalPlayer.Name) or "player") .. "!", true)
        welcome:AddLabel(options.HubBlurb or "Farm, loot, chests, ESP, combat and drill tools.", true)
        welcome:AddDivider()
        welcome:AddLabel("Version: v" .. MiyuGUI.version)
        welcome:AddLabel("Game: " .. (options.Game or MiyuGUI.game))

        local userBox = tab:AddLeftGroupbox("User", "user")
        userBox:AddLabel("User: " .. (LocalPlayer and LocalPlayer.Name or "?"))
        userBox:AddLabel("Executor: " .. S.getExecutorName())
        userBox:AddButton("Copy username", function()
            if LocalPlayer and S.copyToClipboard(LocalPlayer.Name) then
                Hub.notify(Library, "Copied", 2)
            end
        end)

        local sessionBox = tab:AddRightGroupbox("Session", "globe")
        sessionBox:AddLabel("PlaceId: " .. tostring(game.PlaceId))
        sessionBox:AddButton("Rejoin", function()
            TeleportService:Teleport(game.PlaceId, LocalPlayer)
        end)
        return tab
    end

    function Hub.complete(Window, Library, SaveManager, ThemeManager, options)
        options = options or {}
        local uiTab = Window:AddTab("UI Settings", "settings")
        local menuBox = uiTab:AddLeftGroupbox("Menu", "wrench")
        menuBox:AddToggle("MiyuGUIAntiAfk", {
            Text = "Anti-AFK",
            Default = true,
            Callback = function(v)
                Hub.setAntiAfk(v)
            end,
        })
        menuBox:AddLabel("Menu bind"):AddKeyPicker("MenuKeybind", {
            Default = options.ToggleKeybind or "RightControl",
            NoUI = true,
            Text = "Menu keybind",
            ChangedCallback = function()
                Library.ToggleKeybind = Library.Options.MenuKeybind
            end,
        })
        menuBox:AddButton("Unload script", function()
            if Library.Unload then
                Library:Unload()
            end
        end)
        -- MiyuGUI theme (mint / green). Added before the theme list is built.
        pcall(function()
            ThemeManager.BuiltInThemes = ThemeManager.BuiltInThemes or {}
            ThemeManager.BuiltInThemes["MiyuGUI"] = { 0, MIYU_THEME }
        end)
        ThemeManager:ApplyToTab(uiTab)
        pcall(function()
            ThemeManager:ApplyTheme("MiyuGUI")
            local list = Library.Options and Library.Options.ThemeManager_ThemeList
            if list and list.SetValue then
                list:SetValue("MiyuGUI")
            end
        end)
        SaveManager:BuildConfigSection(uiTab)
        local shareBox = uiTab:AddRightGroupbox("Share", "folder")
        shareBox:AddLabel("One config for the whole game, saved under the universe id: miyugui_hub/universe_" .. tostring(game.GameId) .. "/settings. Set one autoload. Lobby actions run in the lobby, and the farm runs in the match.")
        SaveManager:LoadAutoloadConfig()
        Library.ToggleKeybind = Library.Options.MenuKeybind or Enum.KeyCode.RightControl
        task.defer(function()
            Hub.setAntiAfk(true)
        end)
        -- Background picture + Lock button cleanup once the window has been laid out.
        task.delay(1, function()
            pcall(Hub.removeLockButton, Library)
            pcall(Hub.applyBackground, Library)
        end)
        task.delay(4, function()
            pcall(Hub.removeLockButton, Library)
            pcall(Hub.applyBackground, Library)
        end)
        return uiTab
    end

    return Hub
end

local function dropdownList(value)
    if type(value) ~= "table" then
        if type(value) == "string" then
            return { value }
        end
        return value
    end
    if value[1] ~= nil then
        return value
    end
    local out = {}
    for key, item in pairs(value) do
        if type(key) == "string" and item == true then
            out[#out + 1] = key
        elseif type(item) == "string" then
            out[#out + 1] = item
        end
    end
    return out
end

function S.attachMiyuGUIUiAdapter(Window, Library)
    local icons = {
        Lobby = "users",
        Core = "gem",
        Farm = "zap",
        Autofarm = "zap",
        Scrap = "recycle",
        Combat = "swords",
        ["Auto Combat"] = "shield",
        World = "map",
        Shop = "store",
        ESP = "eye",
        Player = "user",
        ["Auto Loot"] = "shopping-bag",
        Money = "coins",
        Pickaxe = "pickaxe",
        Teleport = "map",
        Upgrades = "sparkles",
        Drill = "arrow-down",
        Keybinds = "keyboard",
        Config = "settings",
        ["Auto Buy"] = "store",
        Depth = "layers",
    }
    local flags = {}
    S._miyuguiFlags = flags
    local rf = {}
    rf.Flags = flags
    function rf.LoadConfiguration()
    end
    function rf.Notify(_, opts)
        opts = opts or {}
        local text = tostring(opts.Content or opts.Title or "")
        if opts.Title and opts.Content then
            text = tostring(opts.Title) .. " · " .. tostring(opts.Content)
        end
        if Library and Library.Notify then
            pcall(function()
                Library:Notify(text, opts.Duration or 4)
            end)
        end
    end
    function rf.CreateWindow()
        return {
            CreateTab = function(_, name)
                local tab = Window:AddTab(name, icons[name] or "box")
                local nextLeft = true
                local box
                local api = {}
                local function ensureBox()
                    if box then
                        return box
                    end
                    box = tab:AddLeftGroupbox("Main", icons[name] or "box")
                    nextLeft = false
                    return box
                end

                local function bindFlag(flagName, element)
                    if type(flagName) ~= "string" or flagName == "" then
                        return element
                    end
                    flags[flagName] = element
                    rf.Flags = flags
                    if Rayfield then
                        Rayfield.Flags = flags
                    end
                    return element
                end

                    function api:CreateSection(title)
                        if nextLeft then
                            box = tab:AddLeftGroupbox(title, "box")
                        else
                            box = tab:AddRightGroupbox(title, "box")
                        end
                        nextLeft = not nextLeft
                    end

                    function api:CreateToggle(opts)
                        opts = opts or {}
                        local element = {
                            Flag = opts.Flag,
                            CurrentValue = opts.CurrentValue == true,
                            Callback = opts.Callback,
                            Set = function(self, value)
                                self.CurrentValue = value == true
                                self._suppressCallback = true
                                if self._obsidian and self._obsidian.SetValue then
                                    pcall(function()
                                        self._obsidian:SetValue(value == true)
                                    end)
                                end
                                self._suppressCallback = false
                            end,
                        }
                        element._obsidian = ensureBox():AddToggle(opts.Flag or opts.Name, {
                            Text = opts.Name,
                            Default = opts.CurrentValue == true,
                            Callback = function(value)
                                element.CurrentValue = value == true
                                if element._suppressCallback then
                                    return
                                end
                                if opts.Callback then
                                    opts.Callback(value == true)
                                end
                            end,
                        })
                        return bindFlag(opts.Flag, element)
                    end

                    function api:CreateSlider(opts)
                        opts = opts or {}
                        local range = opts.Range or { 0, 100 }
                        local increment = tonumber(opts.Increment) or 1
                        local rounding = 0
                        if increment < 1 then
                            rounding = 1
                        end
                        local element = {
                            Flag = opts.Flag,
                            CurrentValue = opts.CurrentValue,
                            Set = function(self, value)
                                self.CurrentValue = value
                                if self._obsidian and self._obsidian.SetValue then
                                    pcall(function()
                                        self._obsidian:SetValue(tostring(value))
                                    end)
                                end
                            end,
                        }
                        element._obsidian = ensureBox():AddSlider(opts.Flag or opts.Name, {
                            Text = opts.Name,
                            Default = opts.CurrentValue or range[1],
                            Min = range[1],
                            Max = range[2],
                            Rounding = rounding,
                            Callback = function(value)
                                element.CurrentValue = value
                                if opts.Callback then
                                    opts.Callback(value)
                                end
                            end,
                        })
                        return bindFlag(opts.Flag, element)
                    end

                    function api:CreateDropdown(opts)
                        opts = opts or {}
                        local multi = opts.MultipleOptions == true
                        local current = opts.CurrentOption
                        if multi then
                            if type(current) == "string" then
                                current = { current }
                            elseif type(current) ~= "table" then
                                current = {}
                            end
                        else
                            if type(current) == "table" then
                                current = current[1]
                            end
                            if type(current) ~= "string" then
                                current = nil
                            end
                        end
                        local element = {
                            Flag = opts.Flag,
                            CurrentOption = current,
                            CurrentValue = current,
                            Set = function(self, value)
                                self.CurrentOption = value
                                self.CurrentValue = value
                            end,
                            Refresh = function(self, list)
                                self.Options = list
                                if self._obsidian and self._obsidian.SetValues then
                                    pcall(function()
                                        self._obsidian:SetValues(list)
                                    end)
                                end
                            end,
                        }
                        local ok, widget = pcall(function()
                            return ensureBox():AddDropdown(opts.Flag or opts.Name, {
                                Text = opts.Name,
                                Values = opts.Options or { "None" },
                                Default = current,
                                Multi = multi,
                                AllowNull = true,
                                Callback = function(value)
                                    local list = dropdownList(value)
                                    if multi then
                                        element.CurrentOption = list
                                        element.CurrentValue = list
                                        if opts.Callback then
                                            opts.Callback(list or {})
                                        end
                                    else
                                        local picked = type(value) == "string" and value or (list and list[1])
                                        element.CurrentOption = picked
                                        element.CurrentValue = picked
                                        if opts.Callback then
                                            opts.Callback(picked)
                                        end
                                    end
                                end,
                            })
                        end)
                        if ok then
                            element._obsidian = widget
                        else
                            S.hubLog("dropdown fail " .. tostring(opts.Name) .. " " .. tostring(widget))
                        end
                        return bindFlag(opts.Flag, element)
                    end

                    function api:CreateButton(opts)
                        opts = opts or {}
                        ensureBox():AddButton(opts.Name or "Button", function()
                            if opts.Callback then
                                opts.Callback()
                            end
                        end)
                    end

                    function api:CreateParagraph(opts)
                        opts = opts or {}
                        ensureBox():AddLabel((opts.Title or "") .. (opts.Content and (" — " .. opts.Content) or ""))
                    end

                    function api:CreateStatusLabel(opts)
                        opts = opts or {}
                        local title = opts.Name or opts.Title or "Status"
                        local element = { Text = opts.Default or opts.Content or "—" }
                        local function paint()
                            local full = title .. ": " .. tostring(element.Text or "—")
                            if label.SetText then
                                pcall(function()
                                    label:SetText(full)
                                end)
                            elseif label.Set then
                                pcall(function()
                                    label:Set(full)
                                end)
                            end
                        end
                        local label = ensureBox():AddLabel(title .. ": " .. element.Text)
                        function element:Set(text)
                            element.Text = tostring(text or "—")
                            paint()
                        end
                        return element
                    end

                    function api:CreateInput(opts)
                        opts = opts or {}
                        local element = {
                            Flag = opts.Flag,
                            CurrentValue = "",
                            Set = function(self, value)
                                self.CurrentValue = tostring(value or "")
                            end,
                        }
                        if box.AddInput then
                            element._obsidian = ensureBox():AddInput(opts.Flag or opts.Name, {
                                Text = opts.Name,
                                Default = "",
                                Placeholder = opts.PlaceholderText,
                                Callback = function(text)
                                    element.CurrentValue = text
                                    if opts.Callback then
                                        opts.Callback(text)
                                    end
                                end,
                            })
                        else
                            ensureBox():AddLabel(opts.Name or "Input")
                        end
                        return bindFlag(opts.Flag, element)
                    end

                    function api:CreateKeybind(opts)
                        opts = opts or {}
                        local startKey = (type(opts.CurrentKeybind) == "string" and opts.CurrentKeybind ~= ""
                            and opts.CurrentKeybind ~= "Unknown") and opts.CurrentKeybind or nil
                        local element = {
                            Flag = opts.Flag,
                            CurrentKeybind = startKey or "Unknown",
                            Set = function(self, key)
                                self.CurrentKeybind = key
                            end,
                        }
                        local label = ensureBox():AddLabel(opts.Name or "Bind")
                        pcall(function()
                            label:AddKeyPicker(opts.Flag or (opts.Name .. "_kb"), {
                                Default = startKey or "RightControl",
                                Text = opts.Name,
                                ChangedCallback = function(key)
                                    local name = typeof(key) == "EnumItem" and key.Name or tostring(key)
                                    element.CurrentKeybind = name
                                    if opts.Callback then
                                        opts.Callback(name)
                                    end
                                end,
                            })
                        end)
                        return bindFlag(opts.Flag, element)
                    end

                return api
            end,
        }
    end
    return rf
end

