    nextBtn.BorderSizePixel = 0
    nextBtn.Font = Enum.Font.GothamBold
    nextBtn.TextSize = 11
    nextBtn.TextColor3 = Color3.fromRGB(210, 210, 220)
    nextBtn.Text = "Next item"
    nextBtn.Visible = false
