    end

    task.spawn(function()
        S.ensurePickaxe()
    end)

    local lastTick = 0
    State.connections.autoEquipPickaxe = RunService.Heartbeat:Connect(function()
        if not Pickaxe.autoEquip then
            return
        end
        if tick() - lastTick < 0.5 then
            return
        end
        lastTick = tick()

        local equipped = S.getEquippedTool()
