-- Bounty Hunter: targets only Crazy Miner and Bandit Miner.
local BountyFarm = {
    enabled = false,
    busy = false,
}

local function S_isBountyHunterTarget(model)
    if not model or not model.Parent or not S.isHostileMob(model) then
        return false
    end
    local realName = tostring(model:GetAttribute("RealName") or "")
    return realName:sub(1, 11) == "Miner_Crazy"
        or realName:sub(1, 12) == "Miner_Bandit"
end

local function S_getBountyHunterTargets()
    local targets, seen = {}, {}
    local function add(model)
        if not model or seen[model] or not S_isBountyHunterTarget(model) then
            return
        end
        local pos = S.getEspWorldPosition(model)
        local root = S.getRoot()
        -- Only intercept targets that have spawned near the current Run position.
        -- Distant NPCs are ignored so Bounty Hunter does not teleport across the map.
        if pos and root and (pos - root.Position).Magnitude <= 160 then
            seen[model] = true
            targets[#targets + 1] = { model = model, pos = pos }
        end
    end

    local folder = S.getNpcFolder()
    if folder then
        for _, child in ipairs(folder:GetChildren()) do
            if child:IsA("Model") then add(child) end
        end
    end
    for _, tagged in ipairs(CollectionService:GetTagged("NpcManager")) do
        add(S.getNpcModelFromManager(tagged))
    end

    local root = S.getRoot()
    if root then
        table.sort(targets, function(a, b)
            return (a.pos - root.Position).Magnitude < (b.pos - root.Position).Magnitude
        end)
    end
    return targets
end

local function S_attackBountyHunterTarget(model)
    if not S_isBountyHunterTarget(model) then return end
    if not Services.ToolService or not Services.ToolService.Update then return end

    if Combat.autoEquipBestDamage then
        pcall(function() S.ensureBestDamageTool() end)
    end
    local tool = S.getEquippedTool()
    if not tool or not S.isCombatTool(tool) then return end

    local range = math.max(10, tonumber(Combat.auraRange) or 50)
    pcall(function() S.boostToolRange(tool, range) end)
    local action = S.getToolCombatAction(tool)
    if action == "Shoot" then
        pcall(function() S.fireShootAttack(tool, { model }) end)
    elseif action == "Swing" then
        pcall(function() S.swingAtTargets({ model }) end)
    end
end

function S.setBountyHunterFarm(enabled)
    if enabled and game.PlaceId ~= MiyuGUI.placeId then
        S.notify("Bounty Hunter", "Wrong game/place", 3)
        return false
    end

    BountyFarm.enabled = enabled == true
    if not BountyFarm.enabled then
        Autofarm._bountyHunterHold = false
        S.notify("Bounty Hunter", "OFF", 3)
        return true
    end
    if BountyFarm.busy then return true end

    BountyFarm.busy = true
    task.spawn(function()
        S.notify("Bounty Hunter", "ON · Run can stay enabled", 3)
        while BountyFarm.enabled do
            local root = S.getRoot()
            local targets = S_getBountyHunterTargets()
            local entry = targets[1]

            if root and entry and S_isBountyHunterTarget(entry.model) then
                local model = entry.model
                local humanoid = model:FindFirstChildOfClass("Humanoid")
                local pos = S.getEspWorldPosition(model)

                if humanoid and humanoid.Health > 0 and pos then
                    -- Hold the normal Run route at its current distance while combat is active.
                    Autofarm._bountyHunterHold = true
                    pcall(S.cancelAutofarmTween)
                    pcall(S.clearDragTarget)

                    -- Re-read root/target position during the encounter.
                    local deadline = os.clock() + 20
                    while BountyFarm.enabled and model.Parent and os.clock() < deadline do
                        humanoid = model:FindFirstChildOfClass("Humanoid")
                        root = S.getRoot()
                        pos = S.getEspWorldPosition(model)

                        if not humanoid or humanoid.Health <= 0
                            or not root or not pos
                            or not S_isBountyHunterTarget(model) then
                            break
                        end

                        -- Keep the player at the target; the route resumes after the kill.
                        if (root.Position - pos).Magnitude > 7 then
                            pcall(function()
                                root.Anchored = false
                                root.CFrame = CFrame.new(pos + Vector3.new(0, 3, 0))
                                root.AssemblyLinearVelocity = Vector3.zero
                                root.AssemblyAngularVelocity = Vector3.zero
                            end)
                        end

                        S_attackBountyHunterTarget(model)
                        task.wait(0.25)
                    end

                    -- Release the route hold so Run resumes scanning the map.
                    Autofarm._bountyHunterHold = false
                    task.wait(0.15)
                else
                    task.wait(0.2)
                end
            else
                -- No target nearby: don't interfere with Run; let it keep moving forward.
                Autofarm._bountyHunterHold = false
                task.wait(0.2)
            end
            task.wait(0.05)
        end

        Autofarm._bountyHunterHold = false
        BountyFarm.busy = false
    end)
    return true
end

