            S.EPick = S.EPick or {}
            S.EPick.enabled = value == true
        end,
    })

    FarmTab:CreateToggle({
        Name = "Go to Drill before Church Save",
        CurrentValue = true,
        Flag = "terra_af_gear_to_drill",
        Callback = function(value)
            S.EPick = S.EPick or {}
            S.EPick.deliverToDrill = value == true
        end,
    })

    FarmTab:CreateToggle({
        Name = "Auto Pickup Shards (priority)",
        CurrentValue = S.ShardPick.enabled == true,
        Flag = "terra_af_pickup_shards",
        Callback = function(value)
            S.ShardPick.enabled = value == true
        end,
    })

    FarmTab:CreateSection("Drops")

    FarmTab:CreateSlider({
        Name = "Dump At (items)",
        Range = { 1, 50 },
        Increment = 1,
        CurrentValue = math.clamp(tonumber(Autofarm.sellThreshold) or 10, 1, 50),
        Flag = "terra_af_sell_threshold",
        Callback = function(value)
            Autofarm.sellThreshold = math.clamp(math.floor(value), 1, 50)
        end,
    })

    FarmTab:CreateToggle({
        Name = "Drop in Drill",
        CurrentValue = Autofarm.dropInDrill == true,
        Flag = "terra_af_drop_drill",
        Callback = function(value)
            S.runRayfieldSafeCallback("terra_af_drop_drill", function()
                S.setDropInDrill(value == true)
            end)
        end,
    })

    FarmTab:CreateToggle({
        Name = "Dump on Shredder",
        CurrentValue = Autofarm.dropInShredder == true,
        Flag = "terra_af_drop_shredder",
        Callback = function(value)
            S.runRayfieldSafeCallback("terra_af_drop_shredder", function()
                S.setDropInShredder(value == true)
            end)
        end,
    })

    -- Auto Loot, Auto Scrap, Auto Mine Ores and Auto Collect Sacks live in the Farm tab now.
    S.buildCollectorSections(FarmTab)
end

-- ===== Auto Mine Ores: smelted Iron / Gold bars dropped by a mined ore =====
-- Only bars that APPEAR right after an ore breaks next to it are collected; bars that were
-- already lying around (natural ones) are remembered and never picked up.
S.AO_BARS = S.AO_BARS or {
    seen = setmetatable({}, { __mode = "k" }),
    mined = setmetatable({}, { __mode = "k" }),
    recent = {},
    breakPos = nil,
    breakAt = 0,
}
S.ProspectorBars = S.ProspectorBars or {
    enabled = false,
    seen = setmetatable({}, { __mode = "k" }),
}

function S.isSmeltedBarItem(item)
    if not item or not item.Parent then return false end
    local names = { tostring(item.Name or ""), tostring(item:GetAttribute("DisplayName") or "") }
    local joined = string.lower(table.concat(names, " ")):gsub("[^%a]", "")
    local hasIron = joined:find("iron", 1, true) ~= nil
    local hasGold = joined:find("gold", 1, true) ~= nil
    if not (hasIron or hasGold) then return false end
    -- Prospector output may be named simply Iron/Gold, or IronOre/GoldOre/IronBar/GoldBar.
    -- Exclude unrelated objects whose display names merely contain the metal word.
    local hasOreOrBar = joined == "iron" or joined == "gold"
        or joined:find("ore", 1, true) ~= nil or joined:find("bar", 1, true) ~= nil
    if not hasOreOrBar then
        for _, attr in ipairs({ "Class", "ItemType", "Type", "Category", "DisplayCategory" }) do
            local v = string.lower(tostring(item:GetAttribute(attr) or ""))
            if v:find("ore", 1, true) or v:find("bar", 1, true) or v:find("smelt", 1, true) then
                hasOreOrBar = true; break
            end
        end
    end
    return hasOreOrBar and not joined:find("barrel", 1, true)
end

function S.noteOreBroken(breakPos)
    local AO, B = S.AutoOres, S.AO_BARS
    if not (AO and AO.owned and AO.collectBars and typeof(breakPos) == "Vector3") then
        return
    end
    B.breakPos, B.breakAt = breakPos, os.clock()
    -- Bars that showed up in the last moment before the break was noticed also count.
    for _, rec in ipairs(B.recent) do
        if rec.item.Parent and os.clock() - rec.t <= 2
            and (rec.pos - breakPos).Magnitude <= (AO.barRadius or 40) then
            B.mined[rec.item] = true
        end
    end
end

function S.isMinedBarDrop(item)
    local AO, B = S.AutoOres, S.AO_BARS
    if not (AO and AO.owned and AO.collectBars) or not item or not item.Parent then
        return false
    end
    if B.mined[item] ~= true or not S.isSmeltedBarItem(item) then
        return false
    end
    return not S.isItemInTruckZone(item)
end

task.spawn(function()
    while not S._unloading do
        task.wait(0.25)
        local AO, B = S.AutoOres, S.AO_BARS
        if AO and AO.owned and AO.collectBars then
            local folder = Workspace:FindFirstChild("Items")
            if folder then
                local now = os.clock()
                for _, item in ipairs(folder:GetChildren()) do
                    if not B.seen[item] and S.isSmeltedBarItem(item) then
                        B.seen[item] = true
                        local pos = S.getItemPosition(item)
                        if pos then
                            if B.breakPos and now - B.breakAt <= (AO.barWindow or 8)
                                and (pos - B.breakPos).Magnitude <= (AO.barRadius or 40) then
                                B.mined[item] = true
                            else
                                B.recent[#B.recent + 1] = { item = item, t = now, pos = pos }
                            end
                        end
                    end
                end
                for i = #B.recent, 1, -1 do
                    if now - B.recent[i].t > 4 or not B.recent[i].item.Parent then
                        table.remove(B.recent, i)
                    end
                end
            end
        end
    end
end)

-- Prospector passive smelting: the Prospector turns mined ore into smelted Iron / Gold drops.
-- Only drops that appear AFTER the toggle is turned on (and near you) count as "mined" -
-- everything already lying on the map is remembered and left alone. Each one is picked up by
-- standing on top of it (the server needs you close), then you go back where you were.
S.ProspectorBars.range = S.ProspectorBars.range or 150
task.spawn(function()
    while not S._unloading do
        task.wait(0.2)
        local P = S.ProspectorBars
        if P and P.enabled and game.PlaceId == MiyuGUI.placeId and not P.busy then
            local folder = Workspace:FindFirstChild("Items")
            local root = S.getRoot()
            if folder and root then
                P.seen = P.seen or setmetatable({}, { __mode = "k" })
                P.pending = P.pending or setmetatable({}, { __mode = "k" })
                local now = os.clock()
                for _, item in ipairs(folder:GetChildren()) do
                    if not P.seen[item] and S.isSmeltedBarItem(item) then
                        P.seen[item] = true
                        if P.primed then
                            local pos = S.getItemPosition(item)
                            if pos and (pos - root.Position).Magnitude <= (P.range or 150) then
                                P.pending[item] = now
                            end
                        end
                    end
                end
                P.primed = true
                local best, bestD = nil, math.huge
                for item, t in pairs(P.pending) do
                    if not item.Parent or now - t > 30 then
                        P.pending[item] = nil
                    elseif not S.isItemInTruckZone(item) then
                        local pos = S.getItemPosition(item)
                        if pos then
                            local d = (pos - root.Position).Magnitude
                            if d < bestD then
                                best, bestD = item, d
                            end
                        end
                    end
                end
                if best then
                    P.busy = true
                    local back = not (S.AutoOres and S.AutoOres.owned) and root.CFrame or nil
                    local ok = false
                    pcall(function()
                        ok = S.pickupInGame(best)
                    end)
                    if ok or not best.Parent then
                        P.pending[best] = nil
                    end
                    if back then
                        pcall(function()
                            local r = S.getRoot()
                            if r then
                                r.CFrame = back
                                r.AssemblyLinearVelocity = Vector3.zero
                            end
                        end)
                    end
                    P.busy = false
                end
            end
        end
    end
end)

-- ===== Collector: Auto Mine Ores =====
S.AUTO_ORE_OPTIONS = { "Coal", "Iron", "Gold", "Diamond", "Ruby", "Emerald", "HeartGem" }
S.AutoOres = S.AutoOres or {
    owned = false,
    saved = nil,
    breakWorms = true,
    useBest = true,
    autoCollect = true, -- collect ore/gem drops after each mined ore
    _lastSwap = 0,
    types = { "Coal", "Copper", "Gold", "Diamond", "Ruby", "Emerald", "HeartGem" },
    collectBars = true, -- pick up the smelted Iron / Gold bars that a mined ore drops
    barWindow = 8,
    barRadius = 40,
}

-- Keep the Auto Collect toggle independent from the mining engine.
-- When re-enabled, collect any drops left nearby while the miner is idle.
function S.isAutoMineOreAutoCollectEnabled()
    local AO = S.AutoOres
    return not (AO and AO.owned and AO.autoCollect == false)
end

function S.setAutoMineOreAutoCollect(enabled)
    local AO = S.AutoOres
    if not AO then
        return
    end

    AO.autoCollect = enabled == true
    AO._collectToggleGen = (AO._collectToggleGen or 0) + 1
    local generation = AO._collectToggleGen

    if not AO.autoCollect or not AO.owned or not Autofarm.enabled then
        return
    end

    task.spawn(function()
        -- If the toggle is turned on mid-swing, wait until the current
        -- mining pass is idle so pickup cannot interrupt the mining position.
        for _ = 1, 8 do
            if generation ~= AO._collectToggleGen
                or not AO.autoCollect
                or not AO.owned
                or not Autofarm.enabled
            then
                return
            end

            if not Autofarm.miningBusy then
                local root = S.getRoot()
                if root then
                    pcall(function()
                        S.yankOreDropsNearby(math.max(S.getAutofarmLootRange(), 800))
                    end)
                end
                return
            end
            task.wait(0.25)
        end
    end)
end

-- UI shows "Iron"; the game / hub filters call it "Copper".
function S.setAutoMineOreTypes(options)
    local AO = S.AutoOres
    local out, seen = {}, {}
    if type(options) == "string" then
        options = { options }
    end
    for key, value in pairs(type(options) == "table" and options or {}) do
        local name = type(value) == "string" and value or (value == true and type(key) == "string" and key) or nil
        if name then
            name = ORE_TYPE_REMAP[name] or name
            if not seen[name] then
                seen[name] = true
                out[#out + 1] = name
            end
        end
    end
    AO.types = out
    if AO.owned then
        Autofarm.oreUnderTypes = table.clone and table.clone(out) or { table.unpack(out) }
        Autofarm._oreScanCache = nil
    end
end

function S.setAutoMineOres(enabled)
    local AO = S.AutoOres
    enabled = enabled == true
    if enabled == AO.owned then
        return
    end
    if enabled then
        if Autofarm.enabled or (S.MineRun and S.MineRun.active) or S.isScrapFarmMode() or Autofarm.scrapSweep == true then
            S.notify("Auto Mine Ores", "Turn off Run / Auto Scrap first", 4)
            S.trySetRayfieldFlag("miyugui_auto_mine_ores", false, true)
            return
        end
        if game.PlaceId ~= MiyuGUI.placeId then
            S.notify("Auto Mine Ores", "Starts inside a match", 4)
            S.trySetRayfieldFlag("miyugui_auto_mine_ores", false, true)
            return
        end
        if #AO.types == 0 then
            S.notify("Auto Mine Ores", "Pick at least one ore first", 4)
            S.trySetRayfieldFlag("miyugui_auto_mine_ores", false, true)
            return
        end
        Autofarm._farmShuttingDown = false
        AO.saved = S.snapshotScrapSettings()
        AO.owned = true
        Autofarm.scrapSweep = false
        Autofarm.openChests = false
        Autofarm.enterMines = true
        Autofarm.oreUnderEnabled = true

        -- Auto Mine Ores: collect each broken ore/gem, then unload the full
        -- inventory at the drill instead of selling or dumping it elsewhere.
        if AO.dropWhenFull ~= false then
            S.setFarmDumpDest("drill", true)
            Autofarm.dropInDrill = true
            Autofarm.dropInShredder = false
        end
        Autofarm.sellThreshold = 999999 -- capacity check becomes the only dump trigger
        Autofarm.oreUnderTypes = table.clone and table.clone(AO.types) or { table.unpack(AO.types) }
        Autofarm.breakDeathWormOres = AO.breakWorms ~= false
        Autofarm._oreScanCache = nil
        S.trySetRayfieldFlag("terra_af_auto_chests", false, true)
        S.trySetRayfieldFlag("terra_af_join_mines", true, true)
        S.trySetRayfieldFlag("terra_af_auto_ores", true, true)
        Autofarm.distance = 0
        S.resetAutofarmStart()
        S.setAutofarm(true)
        S.trySetRayfieldFlag("terra_autofarm", true, true)
        S.notify("Auto Mine Ores", "ON - " .. table.concat(AO.types, ", "), 4)
    else
        AO.owned = false
        local saved = AO.saved
        AO.saved = nil
        task.spawn(function()
            -- Turning Auto Mine OFF only stops the farm: no end-of-run flush, no drop, no trip to the drill.
            Autofarm._skipNextEndGame = true
            pcall(S.setAutofarm, false, { skipReturn = true })
            S.trySetRayfieldFlag("terra_autofarm", false, true)
            Autofarm.oreUnderEnabled = false
            if saved then
                pcall(S.restoreScrapSettings, saved)
            end
            S.notify("Auto Mine Ores", "OFF", 3)
        end)
    end
end

-- The farm only asked for "any pickaxe in hand" (it picked the best one only when nothing was equipped).
-- While Auto Mine Ores runs, swap to the highest-tier pickaxe you own (Kings > Phoenix > Void > Diamond > ...).
do
    local origEnsurePickaxe = S.ensurePickaxe
    function S.ensurePickaxe(timeout)
        local AO = S.AutoOres
        if AO and AO.owned and AO.useBest ~= false and os.clock() - (AO._lastSwap or 0) > 1.5 then
            pcall(function()
                local equipped = S.getEquippedTool()
                if equipped and S.isPickaxeTool(equipped) then
                    local best = S.findBestPickaxe()
                    if best and best ~= equipped
                        and S.getPickaxeRank(best.Name) > S.getPickaxeRank(equipped.Name)
                    then
                        AO._lastSwap = os.clock()
                        S.callEquipTool(best)
                        task.wait(0.1)
                    end
                end
            end)
        end
        return origEnsurePickaxe(timeout)
    end
end

-- ===== Collector: loot categories + Auto Pickup Selected Items =====
S.LOOT_CATEGORY_OPTIONS = { "All Fuel", "All Scraps", "Ores/Gems", "Corpses", "Everything Else" }
S.SELECTED_PICKUP_OPTIONS = {
    "Void Gear", "Phoenix Gear", "Kings Gear", "Revive Kit",
    "Coal", "Iron / Copper", "Gold", "Diamond", "Emerald", "Ruby", "HeartGem",
}
-- hub ore key -> label in the selection list
S.SELECTED_ORE_LABEL = {
    Coal = "Coal", Copper = "Iron / Copper", Gold = "Gold", Diamond = "Diamond",
    Emerald = "Emerald", Ruby = "Ruby", HeartGem = "HeartGem",
}

S.LootSel = S.LootSel or {
    categorySet = {},
    categoryFilter = false, -- false = every category selected = no filtering
    selectedSet = {},
    wantGear = false,
    selectedOnly = false,
    ownedLoot = false,
    gearRange = 1500,
    passBusy = false,
}
for _, name in ipairs(S.LOOT_CATEGORY_OPTIONS) do
    S.LootSel.categorySet[name] = true
end

local function lootBlob(item)
    local name = string.lower(tostring(item.Name or ""))
    local display = string.lower(tostring(item:GetAttribute("DisplayName") or ""))
    return name .. " " .. display, (name .. display):gsub("[^%a]", "")
end

function S.isCorpseLootItem(item)
    if not item then
        return false
    end
    if item:GetAttribute("Category") == "Corpse" then
        return true
    end
    local blob = lootBlob(item) .. " " .. S.itemCategoryKey(item)
    return blob:find("corpse", 1, true) ~= nil
end

-- Coal / Voidcoal / Gas can and anything else that burns (corpses have their own category).
function S.isFuelLootItem(item)
    if not item or S.isCorpseLootItem(item) then
        return false
    end
    local fuel = item:GetAttribute("Fuel")
    if typeof(fuel) == "number" and fuel > 0 then
        return true
    end
    local _, squashed = lootBlob(item)
    return squashed:find("coal", 1, true) ~= nil
        or squashed:find("gascan", 1, true) ~= nil
        or squashed:find("fuel", 1, true) ~= nil
end

-- RAW ores and gems only. Strict on purpose: gear named after an ore (Diamond_Helmet, Gold_Revolver,
-- Golden_Medkit ...), bars, shards and scrap are never counted.
S.NOT_ORE_WORDS = {
    "helmet", "chest", "legs", "boots", "armor", "pickaxe", "sword", "rifle", "shotgun", "revolver",
    "gun", "rpg", "blackhole", "kit", "medkit", "bandage", "ammo", "potion", "lantern", "dynamite",
    "grenade", "landmine", "magnet", "bar", "ingot", "shard", "scrap", "staff", "axe", "blade",
    "hammer", "shield", "ring", "crown", "key", "sack", "bag", "corpse", "fuel", "gascan",
}
S.ORE_WORDS = { "coal", "iron", "copper", "gold", "diamond", "ruby", "emerald", "heartgem", "heart" }
S.ORE_NAME_PARTS = { "", "ore", "gem", "gems", "chunk", "nugget", "crystal", "rock", "stone", "raw" }

function S.isOreGemLootItem(item)
    if not item then
        return false
    end
    local key = S.getLootOreTypeKey(item)
    if not key then
        return false
    end
    local _, squashed = lootBlob(item)
    for _, word in ipairs(S.NOT_ORE_WORDS) do
        if squashed:find(word, 1, true) then
            return false
        end
    end
    local cat = S.itemCategoryKey(item)
    if cat == "bar" or cat == "armor" or cat == "tool" or cat == "consumable" then
        return false
    end
    if S.isWorldToolItem(item) then
        return false
    end
    local okGear, gear = pcall(S.getGearItemCategory, item)
    if okGear and gear then
        return false
    end

    -- Positive proof that it is a raw ore / gem drop.
    local oreAttr = item:GetAttribute("OreType") or item:GetAttribute("SessionOreType")
    if typeof(oreAttr) == "string" and oreAttr ~= "" then
        return true
    end
    if cat == "ore" or cat == "gem" or cat == "gems" or cat == "gemstone" or cat == "mineral" then
        return true
    end
    for _, word in ipairs(S.ORE_WORDS) do
        for _, part in ipairs(S.ORE_NAME_PARTS) do
            if squashed == word .. part or squashed == part .. word then
                return true
            end
        end
    end
    return false
end

function S.matchesLootCategories(item)
    local sel = S.LootSel.categorySet
    local fuel = S.isFuelLootItem(item)
    local scrap = S.isScrapCategoryItem(item)
    local ore = S.isOreGemLootItem(item)
    local corpse = S.isCorpseLootItem(item)
    if sel["All Fuel"] and fuel then
        return true
    end
    if sel["All Scraps"] and scrap then
        return true
    end
    if sel["Ores/Gems"] and ore then
        return true
    end
    if sel["Corpses"] and corpse then
        return true
    end
    if sel["Everything Else"] and not (fuel or scrap or ore or corpse) then
        return true
    end
    return false
end

function S.setLootCategories(options)
    local set = {}
    if type(options) == "string" then
        options = { options }
    end
    for key, value in pairs(type(options) == "table" and options or {}) do
        if type(value) == "string" then
            set[value] = true
        elseif value == true and type(key) == "string" then
            set[key] = true
        end
    end
    local all = true
    for _, name in ipairs(S.LOOT_CATEGORY_OPTIONS) do
        if not set[name] then
            all = false
        end
    end
    S.LootSel.categorySet = set
    S.LootSel.categoryFilter = not all
end

function S.setSelectedPickupItems(options)
    local set = {}
    if type(options) == "string" then
        options = { options }
    end
    for key, value in pairs(type(options) == "table" and options or {}) do
        if type(value) == "string" then
            set[value] = true
        elseif value == true and type(key) == "string" then
            set[key] = true
        end
    end
    S.LootSel.selectedSet = set
    S.LootSel.wantGear = set["Void Gear"] or set["Phoenix Gear"] or set["Kings Gear"] or set["Revive Kit"] or false
end

-- True when the item is one of the gear pieces / ores the player selected.
function S.matchesSelectedPickup(item)
    local sel = S.LootSel.selectedSet
    if not item or next(sel) == nil then
        return false
    end
    local okCat, gear = pcall(S.getGearItemCategory, item)
    gear = okCat and gear or nil
    if gear == "Revive" then
        return sel["Revive Kit"] == true
    end
    if gear and gear ~= "Shard" then
        local _, squashed = lootBlob(item)
        if squashed:find("kingslayer", 1, true) then
            return false
        end
        if sel["Void Gear"] and squashed:find("void", 1, true) then
            return true
        end
        if sel["Phoenix Gear"] and squashed:find("phoenix", 1, true) then
            return true
        end
        if sel["Kings Gear"] and squashed:find("kings", 1, true) then
            return true
        end
        return false
    end
    if S.isOreGemLootItem(item) then
        local label = S.SELECTED_ORE_LABEL[S.getLootOreTypeKey(item)]
        return label ~= nil and sel[label] == true
    end
    return false
end

-- Loot filters: categories, or "selected items only" when that mode is on.
do
    local origPasses = S.passesLootFilters
    function S.passesLootFilters(item)
        if not item then
            return false
        end
        local LS = S.LootSel
        if LS.selectedOnly then
            -- Gear is picked up by the F-key pass below; the loot cycle only handles ores/gems.
            local okCat, gear = pcall(S.getGearItemCategory, item)
            if okCat and gear then
                return false
            end
            return S.matchesSelectedPickup(item)
        end
        if LS.categoryFilter and not S.matchesLootCategories(item) then
            return false
        end
        return origPasses(item)
    end
end

-- Selected gear (Void / Phoenix / Kings / Revive Kit): fly next to it and press F once, nearest first.
function S.selectedGearPass()
    local EP = S.EPick
    local LS = S.LootSel
    if not EP or type(EP.pickup) ~= "function" or not S.getRoot() then
        return 0
    end
    local list = {}
    S.forEachWorldLootItem(function(item)
        if not item or not item.Parent or CollectionService:HasTag(item, "ShopItem") then
            return
        end
        local okCat, gear = pcall(S.getGearItemCategory, item)
        if not (okCat and gear and gear ~= "Shard") or not S.matchesSelectedPickup(item) then
            return
        end
        if Loot.skipTruckLoot and S.isItemInTruckZone(item) then
            return
        end
        local f = EP.fails and EP.fails[item]
        if f and f.untilAt and os.clock() < f.untilAt then
            return
        end
        local pos = S.getItemPosition(item)
        if pos then
            local dist = S.getFlatDistanceFromPosition(pos)
            if dist <= LS.gearRange then
                list[#list + 1] = { item = item, dist = dist }
            end
        end
    end)
    if #list == 0 then
        return 0
    end
    table.sort(list, function(a, b)
        return a.dist < b.dist
    end)
    local rootStart = S.getRoot()
    local homeCf = rootStart and rootStart.CFrame
    local picked = 0
    for i = 1, math.min(#list, 3) do
        if not LS.selectedOnly or S._unloading then
            break
        end
        if EP.pickup(list[i].item, true) then
            picked += 1
        end
        task.wait(0.05)
    end
    if homeCf then
        pcall(function()
            local r = S.getRoot()
            if r then
                r.Anchored = false
                r.CFrame = homeCf
                r.AssemblyLinearVelocity = Vector3.zero
            end
        end)
    end
    return picked
end

function S.setSelectedPickup(enabled)
    local LS = S.LootSel
    enabled = enabled == true
    if enabled == LS.selectedOnly then
        return
    end
    if enabled then
        if next(LS.selectedSet) == nil then
            S.notify("Auto Pickup", "Pick at least one item first", 4)
            S.trySetRayfieldFlag("miyugui_pickup_selected", false, true)
            return
        end
        LS.selectedOnly = true
        if not Loot.enabled then
            LS.ownedLoot = true
            S.setAutoLoot(true)
        end
        S.notify("Auto Pickup", "ON - only the selected items", 4)
    else
        LS.selectedOnly = false
        if LS.ownedLoot then
            LS.ownedLoot = false
            S.setAutoLoot(false)
        end
        S.notify("Auto Pickup", "OFF", 3)
    end
end

task.spawn(function()
    while not S._unloading do
        task.wait(0.8)
        local LS = S.LootSel
