            pcall(S.selectedGearPass)
            LS.passBusy = false
        end
    end
end)

-- ===== Aura Collect: picks up nearby items from where you stand (no teleporting) =====
S.Aura = S.Aura or {
    enabled = false,
    range = 15,
    busy = false,
    fails = setmetatable({}, { __mode = "k" }),
    skip = setmetatable({}, { __mode = "k" }),
}
S.Aura.range = math.clamp(tonumber(S.Aura.range) or 15, 5, 15) -- default 15 studs, never more

function S.setAuraCollect(enabled)
    local A = S.Aura
    A.enabled = enabled == true
    A.range = math.clamp(tonumber(A.range) or 15, 5, 15)
    if A.enabled then
        -- Retry previously missed items immediately after the user turns the feature on.
        A.fails = setmetatable({}, { __mode = "k" })
        A.skip = setmetatable({}, { __mode = "k" })
    end
    S.notify("Aura Collect", A.enabled and ("ON - " .. A.range .. " studs, continuous") or "OFF", 3)
end

-- One sweep: every item inside the range that passes your Auto Loot filters (categories, or the
-- selected-items list when that mode is on) gets the game's own pickup call. Nobody moves.
function S.auraCollectPass()
    local A = S.Aura
    local root = S.getRoot()
    local itemsFolder = Workspace:FindFirstChild("Items")
    if not root or not itemsFolder then
        return 0
    end
    local origin = root.Position
    local now = os.clock()
    local list = {}
    S.forEachWorldLootItem(function(item)
        if not item or not item.Parent or CollectionService:HasTag(item, "ShopItem") then
            return
        end
        -- Keep retrying while Aura Collect is enabled; no per-item timeout/blacklist.
        local pos = S.getItemPosition(item)
        if not pos then
            return
        end
        local dist = (pos - origin).Magnitude
        if dist > A.range then
            return
        end
        local ok
        if S.LootSel and S.LootSel.selectedOnly then
            ok = S.matchesSelectedPickup(item) and not (Loot.skipTruckLoot and S.isItemInTruckZone(item))
        else
            local good, res = pcall(S.isLootCandidate, item)
            ok = good and res == true and not (Loot.skipTruckLoot and S.isItemInTruckZone(item))
        end
        if not ok and S.AutoOres and S.AutoOres.owned then
            ok = (S.isSelectedOreDropItem(item) or S.isMinedBarDrop(item))
                and not (Loot.skipTruckLoot and S.isItemInTruckZone(item))
        end
        if ok then
            list[#list + 1] = { item = item, dist = dist }
        end
    end)
    if #list == 0 then
        return 0
    end
    -- Items that keep failing drop to the back of the queue, so one stuck item can never
    -- block the rest. The fail table is wiped every few seconds so everything is retried.
    if now - (A._lastWipe or 0) > 6 then
        A._lastWipe = now
        A.fails = setmetatable({}, { __mode = "k" })
    end
    for _, e in ipairs(list) do
        e.f = A.fails[e.item] or 0
    end
    table.sort(list, function(a, b)
        if a.f ~= b.f then
            return a.f < b.f
        end
        return a.dist < b.dist
    end)
    local batch = math.min(#list, 8)
    for i = 1, batch do
        local it = list[i].item
        S.inGameInteract(it, (A.fails[it] or 0) + 1)
    end
    task.wait(0.12)
    local got = 0
    for i = 1, batch do
        local it = list[i].item
        if not it.Parent or not it:IsDescendantOf(itemsFolder) then
            got += 1
            A.fails[it] = nil
        else
            -- The server may reject a pickup temporarily. Do not blacklist it:
            -- it just moves back in the queue and is retried while the toggle stays ON.
            A.fails[it] = (A.fails[it] or 0) + 1
        end
    end
    return got
end

task.spawn(function()
    while not S._unloading do
        task.wait(0.12)
        local A = S.Aura
        if A.enabled and not A.busy and game.PlaceId == MiyuGUI.placeId then
            A.busy = true
            local ok, err = pcall(S.auraCollectPass)
            A.busy = false
            if not ok then
                warn("[MiyuGUI] Aura Collect pass:", err)
            end
        end
    end
end)

