        end,
    })
    S.applyPriorityElementLayout("Auto Buy Upgrades", UPGRADE_PRIORITY_ADD_LAYOUT - 2)
    BuyTab:CreateButton({
        Name = UPGRADE_PRIORITY_ADD_BUTTON,
        Callback = function()
            S.addUpgradePrioritySlot(BuyTab)
        end,
