-- ========== PRIEST STAFF: tự buff đồng đội gần nhất ==========
-- Cầm Priest staff -> quay camera/nhân vật về đồng đội gần nhất -> kích hoạt gậy -> trả lại tool cũ.
-- Tuỳ chỉnh: S.Priest.range / S.Priest.cooldown / S.Priest.castMethod ("Key E" | "Right Click" | "Left Click" | "Activate").
S.Priest = {
    enabled = false,
    range = 60,
    cooldown = 3,
    aimCamera = true,
    faceTarget = true,
    restorePrev = true,
    castMethod = "Key E", -- gậy Priest dùng phím E
    busy = false,
    _lastCast = 0,
    _gen = 0,
}

function S.isPriestStaff(tool)
    if not tool or not tool:IsA("Tool") then
        return false
    end
    local name = string.lower(tool.Name)
    local class = string.lower(tostring(tool:GetAttribute("Class") or ""))
    if name:find("priest", 1, true) or name:find("staff", 1, true) then
        return true
    end
    return class:find("priest", 1, true) ~= nil or class:find("staff", 1, true) ~= nil
end

-- Đồng đội gần nhất còn sống trong tầm. Nếu game có Team thì chỉ lấy cùng Team.
function S.findNearestTeammate(range)
    local root = S.getRoot()
    if not root then
        return nil
    end
    local bestPlayer, bestRoot, bestDist = nil, nil, nil
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LocalPlayer then
            local sameTeam = LocalPlayer.Team == nil or plr.Team == LocalPlayer.Team
            local char = plr.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if sameTeam and hum and hum.Health > 0 and hrp then
                local dist = (hrp.Position - root.Position).Magnitude
                if dist <= range and (not bestDist or dist < bestDist) then
                    bestPlayer, bestRoot, bestDist = plr, hrp, dist
                end
            end
        end
    end
    return bestPlayer, bestRoot, bestDist
end

function S.priestCastOnce()
    local Priest = S.Priest
    if S.isPlayerDead() then
        return false
    end
    -- Đang đào quặng thì không giật pickaxe khỏi tay.
    if Autofarm.miningBusy or Autofarm._oreHuntMode then
        return false
    end

    local staff = S.findToolInInventory(S.isPriestStaff)
    if not staff then
        return false
    end
    local plr, targetRoot = S.findNearestTeammate(Priest.range)
    if not plr or not targetRoot then
        return false
    end

    local prev = S.getEquippedTool()
    if prev ~= staff then
        S.callEquipTool(staff)
        task.wait(0.15)
    end
    local held = S.getEquippedTool()
    if not held or not S.isPriestStaff(held) then
        return false
    end

    local root = S.getRoot()
    local hum = S.getHumanoid()
    local cam = Workspace.CurrentCamera
    local targetPos = targetRoot.Position

    if Priest.aimCamera and cam then
        pcall(function()
            cam.CFrame = CFrame.lookAt(cam.CFrame.Position, targetPos)
        end)
    end
    -- Đang ngồi drill/ghế thì không xoay root (tránh văng khỏi ghế).
    if Priest.faceTarget and root and hum and hum.SeatPart == nil then
        pcall(function()
            root.CFrame = CFrame.lookAt(root.Position, Vector3.new(targetPos.X, root.Position.Y, targetPos.Z))
        end)
    end

    local method = Priest.castMethod
    if method == "Activate" then
        pcall(function()
            held:Activate()
        end)
    elseif method == "Key E" then
        pcall(function()
            local vim = game:GetService("VirtualInputManager")
            vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)
            task.wait(0.1)
            vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)
        end)
    elseif cam then
        -- VirtualInputManager: 0 = chuột trái, 1 = chuột phải
        local button = method == "Left Click" and 0 or 1
        pcall(function()
            local vim = game:GetService("VirtualInputManager")
            local pt, onScreen = cam:WorldToScreenPoint(targetPos)
            if onScreen then
                vim:SendMouseButtonEvent(pt.X, pt.Y, button, true, game, 0)
                task.wait(0.08)
                vim:SendMouseButtonEvent(pt.X, pt.Y, button, false, game, 0)
            end
        end)
    end

    task.wait(0.25)
    if Priest.restorePrev and prev and prev ~= held and prev.Parent then
        S.callEquipTool(prev)
    end
    return true
end

function S.setPriestBuff(enabled)
    local Priest = S.Priest
    Priest.enabled = enabled == true
    Priest._gen += 1
    if not Priest.enabled then
        return
    end
    local gen = Priest._gen
    task.spawn(function()
        while Priest.enabled and Priest._gen == gen do
            if not Priest.busy and os.clock() - Priest._lastCast >= Priest.cooldown then
                Priest.busy = true
                local ok, casted = pcall(S.priestCastOnce)
                Priest.busy = false
                if ok and casted then
                    Priest._lastCast = os.clock()
                end
            end
            task.wait(0.25)
        end
    end)
end

-- In ra console thông tin gậy (thuộc tính + con) để biết remote/cách bắn chính xác.
function S.priestDumpInfo()
    local staff = S.findToolInInventory(S.isPriestStaff)
    if not staff then
        S.notify("Priest", "Priest staff not found in backpack/hand", 4)
        return
    end
    print("[MiyuGUI Priest] Tool:", staff:GetFullName(), "Class:", staff.ClassName)
    for k, v in pairs(staff:GetAttributes()) do
        print("  attr", k, "=", v)
    end
    for _, d in ipairs(staff:GetDescendants()) do
        print("  child", d.ClassName, d:GetFullName())
    end
    S.notify("Priest", "Staff info printed to console (F9)", 4)
end

