        Title = "How to use",
        Content = "Unbound by default (shows Unknown). Click a row, press a key to bind. That key toggles the feature.",
    })

    Keybinds.list = {}

    local binds = {
        { name = "Kill Aura", flag = "terra_kill_aura" },
        { name = "Dodge Attack Hitboxes", flag = "terra_dodge_hitbox" },
        { name = "Auto Equip Best Damage", flag = "terra_combat_auto_equip_damage" },
        { name = "Auto Loot", flag = "terra_auto_loot" },
        { name = "Auto Equip Bag", flag = "terra_auto_equip_bag" },
        { name = "Auto Fuel Drill", flag = "terra_auto_fuel" },
        { name = "Auto Lock Truck Items", flag = "terra_auto_lock_truck" },
        { name = "Auto Equip Pickaxe", flag = "terra_auto_equip_pickaxe" },
        { name = "Auto Mine", flag = "terra_auto_mine" },
        { name = "Speed Hack", flag = "terra_speed" },
        { name = "Fly", flag = "terra_fly" },
        { name = "Noclip", flag = "terra_noclip" },
        { name = "Fullbright", flag = "terra_fullbright" },
        { name = "Auto Buy Upgrades", flag = "terra_auto_upgrades" },
        { name = "Autofarm", flag = "terra_autofarm" },
    }

    for _, bind in ipairs(binds) do
        -- Rayfield crashes on Enum.KeyCode[""] — never pass empty string.
        local settings = KeybindsTab:CreateKeybind({
            Name = bind.name,
            CurrentKeybind = "Unknown",
            HoldToInteract = false,
            Flag = "terra_kb_" .. bind.flag,
            Callback = function(key)
                if type(key) == "string" and (key == "" or key == "None") then
                    if settings and settings.Set then
                        pcall(function()
                            settings:Set("Unknown")
                        end)
                    end
                end
            end,
        })
        table.insert(Keybinds.list, {
            flag = bind.flag,
            settings = settings,
        })
        if settings then
            S.registerRayfieldFlag(settings)
        end
    end

    S.startKeybindListener()
end

function S.teleportToNearestBountySell()
    local root = S.getRoot()
    if not root then S.notify("BountyCamp", "Character root not found", 4); return false end
    local candidates = {}
    local function add(inst)
        if inst:IsA("BasePart") then table.insert(candidates, inst)
        else for _, d in ipairs(inst:GetDescendants()) do if d:IsA("BasePart") then table.insert(candidates, d) end end end
    end
    -- Resolve the named path first, then fall back to all streamed descendants with the same name.
    local camp = Workspace:FindFirstChild("BountyCamp", true)
    local important = camp and camp:FindFirstChild("Important", true)
    local target = important and important:FindFirstChild("BountySell", true)
    if target then add(target) end
    if #candidates == 0 then
        for _, inst in ipairs(Workspace:GetDescendants()) do
            if inst.Name == "BountySell" then add(inst) end
        end
    end
    local best, bestDist = nil, math.huge
    for _, part in ipairs(candidates) do
        if part.Parent then
            local dist = (part.Position - root.Position).Magnitude
            if dist < bestDist then best, bestDist = part, dist end
        end
    end
    if not best then S.notify("BountyCamp", "BountySell part is not currently streamed in", 5); return false end
    pcall(function() S.requestStreamAround(best.Position, 2) end)
    root.CFrame = best.CFrame + Vector3.new(0, 4, 0)
    root.AssemblyLinearVelocity = Vector3.zero
    root.AssemblyAngularVelocity = Vector3.zero
    S.notify("BountyCamp", "Teleported to nearest BountySell", 3)
    return true
end

function S.getVillageDepthMeters(village)
    if not village then return nil end
    for _, key in ipairs({"DepthMeters", "Depth", "LayerDepth", "DepthM", "DepthInMeters"}) do
        local v = village:GetAttribute(key)
        if tonumber(v) then return tonumber(v) end
    end
    local pos = S.getInstancePosition(village)
    if pos then
        local ds = S.getDepthScale and S.getDepthScale()
        if ds and type(ds.GetMetersFromWorldPosition) == "function" then
            local ok, depth = pcall(ds.GetMetersFromWorldPosition, ds, pos)
            if ok and tonumber(depth) then return tonumber(depth) end
        end
        local ok, depth = pcall(S.computeDepthMetersDump, pos)
        if ok and tonumber(depth) then return tonumber(depth) end
    end
    return nil
end

function S.teleportToNextVillageLayer()
    local root = S.getRoot()
    if not root then S.notify("Village By Depth", "Character not found", 4); return false end
    local current = S.computeDepthMetersDump(root.Position) or 0
    local best, bestDepth = nil, math.huge
    S.scanWorldModels(function(inst)
        if S.isVillageModel(inst) then
            local depth = S.getVillageDepthMeters(inst)
            if depth and depth > current + 5 and depth < bestDepth then best, bestDepth = inst, depth end
        end
    end)
    if not best then S.notify("Village By Depth", "No deeper loaded village found", 5); return false end
    local cf = S.getVillageEntranceCFrame(best)
    if not cf then S.notify("Village By Depth", "Village entrance not found", 4); return false end
    root.CFrame = cf
    root.AssemblyLinearVelocity = Vector3.zero
    root.AssemblyAngularVelocity = Vector3.zero
    S.notify("Village By Depth", "Next layer: " .. best.Name, 4)
    return true
end

function S.buildWorldTab(Window)
    local WorldTab = Window:CreateTab("World")

    WorldTab:CreateSection("Manual Save Gear")
    local manualGearByLabel = {}
    local manualGearLimit = 9
    local selectedManualGear = {} -- gear id -> true
    local gearDropdown

    -- Loading again only REPLACES the options of this one list - no new controls are ever added.
    WorldTab:CreateButton({
        Name = "Load Available Gear",
        Callback = function()
            task.spawn(function()
                local ok, choices = pcall(function()
                    local rf = game:GetService("ReplicatedStorage").Packages._Index["sleitnick_knit@1.4.6"].knit.Services.PlayerService.RF
                    return rf.GetSaveGearChoices:InvokeServer()
                end)
                if not ok or type(choices) ~= "table" then
                    S.notify("Manual Save Gear", "Could not load available gear: " .. tostring(choices), 5)
                    return
                end
                manualGearByLabel = {}
                selectedManualGear = {}
                manualGearLimit = math.max(0, math.floor(tonumber(choices.Limit) or 9))
                local entries = {}
                for _, item in pairs(choices.Items or {}) do
                    local id = item.Id
                    local name = tostring(item.Name or "Unknown gear")
                    local count = math.max(0, math.floor(tonumber(item.Count) or 0))
                    if type(id) == "string" and id ~= "" and count > 0 then
                        table.insert(entries, { Id = id, Name = name, Count = count })
                    end
                end
                table.sort(entries, function(a, b)
                    return a.Name < b.Name
                end)
                local labels = {}
                for i, item in ipairs(entries) do
                    local label = string.format("%s (x%d)", item.Name, item.Count)
                    if manualGearByLabel[label] then
                        label = label .. " #" .. i
                    end
                    manualGearByLabel[label] = item
                    labels[#labels + 1] = label
                end
                if gearDropdown then
                    pcall(function()
                        gearDropdown:Refresh(#labels > 0 and labels or { "(no gear available)" })
                    end)
                    pcall(function()
                        if gearDropdown._obsidian then
                            gearDropdown._obsidian:SetValue({})
                        end
                    end)
                end
                if #entries == 0 then
                    S.notify("Manual Save Gear", "The server returned no selectable gear. Check that you have gear available.", 6)
                else
                    S.notify("Manual Save Gear", "Loaded " .. #entries .. " gear entries (the list was replaced). Tick what you want to save.", 6)
                end
            end)
        end,
    })

    gearDropdown = WorldTab:CreateDropdown({
        Name = "Gear to save",
        Options = { "(press Load Available Gear)" },
        CurrentOption = {},
        MultipleOptions = true,
        Flag = "miyugui_manual_save_gear_pick",
        Callback = function(options)
            selectedManualGear = {}
            for _, label in ipairs(options or {}) do
                local item = manualGearByLabel[label]
                if item then
                    selectedManualGear[item.Id] = item
                end
            end
        end,
    })

    WorldTab:CreateButton({
        Name = "Save Selected Gear Anywhere",
        Callback = function()
            task.spawn(function()
                local payload = {}
                local total = 0
                for id, item in pairs(selectedManualGear) do
                    payload[id] = item.Count
                    total += item.Count
                end
                if total == 0 then
                    S.notify("Manual Save Gear", "Load gear and select at least one item first", 4)
                    return
                end
                if total > manualGearLimit then
                    S.notify("Manual Save Gear", "Selected quantity " .. total .. " exceeds the " .. manualGearLimit .. " slot limit. Deselect some gear.", 5)
                    return
                end
                local ok, result = pcall(function()
                    local rf = game:GetService("ReplicatedStorage").Packages._Index["sleitnick_knit@1.4.6"].knit.Services.PlayerService.RF
                    return rf.SaveGear:InvokeServer(payload)
                end)
                if not ok then
                    S.notify("Manual Save Gear", "Save request errored: " .. tostring(result), 5)
                elseif result == true then
                    S.notify("Manual Save Gear", "Server confirmed saving " .. total .. " gear items", 5)
                else
                    S.notify("Manual Save Gear", "Server rejected save (response: " .. tostring(result) .. "). Check selected items/slot limit.", 6)
                end
            end)
        end,
    })

    WorldTab:CreateSection("Teleport")
    WorldTab:CreateButton({
        Name = "Village",
        Callback = function()
            S.teleportHubToNearest("village")
        end,
    })
    WorldTab:CreateButton({
        Name = "Dungeon",
        Callback = function()
            S.teleportHubToNearest("dungeon")
        end,
    })
    WorldTab:CreateButton({
        Name = "Mine",
        Callback = function()
            S.teleportHubToNearest("mine")
        end,
    })
    WorldTab:CreateButton({
        Name = "Bounty Sell (Nearest)",
        Callback = function() S.teleportToNearestBountySell() end,
    })
    WorldTab:CreateButton({
        Name = "Next Village Layer (By Depth)",
        Callback = function() S.teleportToNextVillageLayer() end,
    })
    WorldTab:CreateButton({
        Name = "Rejoin",
        Callback = function()
            S.rejoinSameServer()
        end,
    })

    WorldTab:CreateSection("Drill")
    WorldTab:CreateButton({
        Name = "TP to Drill",
        Callback = function()
            if S.teleportToDrillViaVoid() then
                S.notify("Drill", "Sent to void - you respawn at drill", 4)
            else
                S.notify("Drill", "Character not found", 3)
            end
        end,
    })
    WorldTab:CreateToggle({
        Name = "Auto Fuel",
        CurrentValue = false,
        Flag = "terra_auto_fuel",
        Callback = function(value)
            S.setAutoFuel(value)
        end,
    })
    WorldTab:CreateToggle({
        Name = "Auto Drive",
        CurrentValue = AutoDrive.enabled,
        Flag = "terra_auto_drive",
        Callback = function(value)
            S.setAutoDrive(value == true)
        end,
    })
    WorldTab:CreateToggle({
        Name = "Lock Truck (Z)",
        CurrentValue = false,
        Flag = "terra_auto_lock_truck",
        Callback = function(value)
            S.setAutoLockTruck(value)
        end,
    })

    WorldTab:CreateSection("Depth")
    S.bindDepthReadout("drill", WorldTab:CreateSlider({
        Name = "Drill depth",
        Range = { 0, 100000 },
        Increment = 1,
        CurrentValue = 0,
        Flag = "miyugui_dtec_drill_depth_m",
        Callback = function() end,
    }))
    S.bindDepthReadout("you", WorldTab:CreateSlider({
        Name = "Your depth",
        Range = { 0, 100000 },
        Increment = 1,
        CurrentValue = 0,
        Flag = "miyugui_dtec_player_depth_m",
