-- ========== AUTO MINE RUN ==========
-- 1) seek a Diamond+ pickaxe (every mine + chests, same as Scrap seek)
-- 2) mine every ore type for N laps
-- 3) optional chest lap
-- 4) back to the lobby; the lobby loop starts the next match (same as Auto Core)
S.MineRun = {
    enabled = false,
    active = false,
    phase = "off", -- seek | farm | chests | leaving
    mineLaps = 2,
    chestsAfter = false,
    farmLaps = 0,
    chestLaps = 0,
    _lapLock = 0,
    _phaseSince = 0,
    _gen = 0,
    _starting = false,
    saveGear = true,
    saveSeconds = 4,
    savedCount = 0,
    _saved = {},
    _saveScanAt = 0,
    oreTypes = nil, -- nil = all ore types
    skipSeek = true, -- class pickaxe is enough, no pickaxe search
}

S.MobHunter = { enabled = false, range = 50, busy = false, running = false, cooldownUntil = 0 }

function S.mineRunFlagValue(name)
    local flags = Rayfield and Rayfield.Flags
    local flag = flags and flags[name]
    if not flag then
        return nil
    end
    local obs = flag._obsidian
    if obs and obs.Value ~= nil then
        return obs.Value
    end
    return flag.CurrentValue
end

function S.mineRunReadSettings()
    local MR = S.MineRun
    local laps = tonumber(S.mineRunFlagValue("miyugui_mine_laps"))
    if laps then
        MR.mineLaps = math.clamp(math.floor(laps), 1, 10)
    end
    local chests = S.mineRunFlagValue("miyugui_mine_chests")
    if chests ~= nil then
        MR.chestsAfter = chests == true
    end
    local save = S.mineRunFlagValue("miyugui_mine_save")
    if save ~= nil then
        MR.saveGear = save == true
    end
    local secs = tonumber(S.mineRunFlagValue("miyugui_mine_save_secs"))
    if secs then
        MR.saveSeconds = math.clamp(secs, 2, 12)
    end
end

function S.mineRunSetPhase(phase)
    S.MineRun.phase = phase
    S.MineRun._phaseSince = os.clock()
end

function S.mineRunCopyList(list)
    local out = {}
    for _, v in ipairs(list) do
        out[#out + 1] = v
    end
    return out
end

function S.mineRunBeginFarm(forced)
    local MR = S.MineRun
    if not MR.active then
        return
    end
    S.mineRunSetPhase("farm")
    MR.farmLaps = 0
    MR._lapLock = os.clock()

    -- Mine Run farm phase = Scrap Sweep (tween khắp map, chỉ nhặt scrap, nghiền ở shredder).
    -- Không đào quặng, không bán quặng.
    Autofarm._pendingMapWrap = false
    Autofarm._oreScanCache = nil
    Autofarm.stuckOres = {}
    Autofarm._oreFailCount = {}
    S.applyScrapSweepSettings()

    -- Auto Mine Run is the master toggle, so it must start the farm engine itself.
    if not Autofarm.enabled then
        S.setAutofarm(true)
    end
    Autofarm.distance = 0
    S.resetAutofarmStart()
    S.notify("Mine Run", "Scrap sweep - " .. MR.mineLaps .. " laps (no ore mining / selling)", 5)
end

function S.mineRunBeginChests()
    local MR = S.MineRun
    if not MR.active then
        return
    end
    S.mineRunSetPhase("chests")
    MR._lapLock = os.clock()
    Autofarm._pendingMapWrap = false
    Autofarm.oreUnderEnabled = false
    Autofarm.enterMines = false
    Autofarm.autoSell = false
    S.scrapSweepFlush()
    S.clearScrapSweepFlags()
    Autofarm.dropInShredder = false
    Autofarm.openChests = true
    Autofarm.chestTypes = S.mineRunCopyList(CHEST_TYPE_OPTIONS)
    Autofarm._oreScanCache = nil
    S.trySetRayfieldFlag("terra_af_auto_ores", false, true)
    S.trySetRayfieldFlag("terra_af_join_mines", false, true)
    S.trySetRayfieldFlag("terra_af_auto_sell", false, true)
    S.trySetRayfieldFlag("terra_af_auto_chests", true, true)
    Autofarm.distance = 0
    S.resetAutofarmStart()
    S.notify("Mine Run", "Ores done — opening chests (1 lap)", 5)
end

function S.mineRunFinish(reason)
    local MR = S.MineRun
    if not MR.active or MR.phase == "leaving" then
        return
    end
    S.mineRunSetPhase("leaving")
    S.notify("Mine Run", "Finished (" .. tostring(reason) .. ") — back to lobby", 5)
    task.spawn(function()
        pcall(S.setAutofarm, false, { skipReturn = true })
        local svc = S.coreTeleportService()
        if svc and type(svc.TeleportToLobby) == "function" then
            pcall(function()
                S.coreAwait(svc:TeleportToLobby(true))
            end)
        end
    end)
end

function S.mineRunAfterMining()
    local MR = S.MineRun
    if MR.chestsAfter then
        S.mineRunBeginChests()
    elseif MR.saveGear then
        S.mineRunBeginStore()
    else
        S.mineRunFinish("ores done")
    end
end

function S.mineRunAfterChests()
    local MR = S.MineRun
    if MR.saveGear then
        S.mineRunBeginStore()
    else
        S.mineRunFinish("chests done")
    end
end

-- Lap after the chests: fly the map again and save gear at every SaveGear ring.
function S.mineRunBeginStore()
    local MR = S.MineRun
    if not MR.active then
        return
    end
    S.mineRunSetPhase("store")
    MR._lapLock = os.clock()
    MR._saved = {}
    MR.savedCount = 0
    MR._saveScanAt = 0
    Autofarm._pendingMapWrap = false
    Autofarm.oreUnderEnabled = false
    S.scrapSweepFlush()
    S.clearScrapSweepFlags()
    Autofarm.dropInShredder = false
    Autofarm.enterMines = false
    Autofarm.autoSell = false
    Autofarm.openChests = false
    Autofarm._oreScanCache = nil
    S.trySetRayfieldFlag("terra_af_auto_ores", false, true)
    S.trySetRayfieldFlag("terra_af_join_mines", false, true)
    S.trySetRayfieldFlag("terra_af_auto_sell", false, true)
    S.trySetRayfieldFlag("terra_af_auto_chests", false, true)
    Autofarm.distance = 0
    S.resetAutofarmStart()
    S.notify("Mine Run", "Saving gear at every well (1 lap)", 5)
end

function S.mineRunWellKey(pos)
    return string.format("%d_%d", math.floor(pos.X / 25), math.floor(pos.Z / 25))
end

-- Một instance có phải điểm "Save Gear" không? Trả về BasePart (hoặc nil).
-- Game đổi tên/cấu trúc thì vẫn bắt được: tên chứa savegear/gearsave/..., hoặc ProximityPrompt có chữ "save".
function S.mineRunSaveGearPartOf(d)
    local flat = (string.lower(d.Name):gsub("[%s_%-]", ""))
    local nameHit = flat:find("savegear", 1, true)
        or flat:find("gearsave", 1, true)
        or flat:find("savewell", 1, true)
        or flat:find("savealtar", 1, true)
        or flat:find("savepoint", 1, true)
        or flat == "save"
    if d:IsA("BasePart") then
        return nameHit and d or nil
    elseif d:IsA("Model") then
        if nameHit then
            return d.PrimaryPart or d:FindFirstChildWhichIsA("BasePart", true)
        end
    elseif d:IsA("ProximityPrompt") then
        local text = string.lower(tostring(d.ActionText) .. " " .. tostring(d.ObjectText))
        if text:find("save", 1, true) then
            local par = d.Parent
            if par and par:IsA("Attachment") then
                par = par.Parent
            end
            if par and par:IsA("BasePart") then
                return par
            elseif par and par:IsA("Model") then
                return par.PrimaryPart or par:FindFirstChildWhichIsA("BasePart", true)
            end
        end
    end
    return nil
end

function S.mineRunFindSaveGear()
    local MR = S.MineRun
    local now = os.clock()
    if now - (MR._saveScanAt or 0) < 2.5 then
        return nil
    end
    MR._saveScanAt = now
    pcall(S.mineRunCacheChurch)
    local desc = workspace:GetDescendants()
    -- 1) tên gốc "SaveGear" (như cũ)
    for _, d in ipairs(desc) do
        if d.Name == "SaveGear" and d:IsA("BasePart") and not MR._saved[S.mineRunWellKey(d.Position)] then
            return d
        end
    end
    -- 2) tìm rộng hơn (game đổi tên / đổi cấu trúc)
    for _, d in ipairs(desc) do
        local part = S.mineRunSaveGearPartOf(d)
        if part and not MR._saved[S.mineRunWellKey(part.Position)] then
            if not MR._saveFallbackNoted then
                MR._saveFallbackNoted = true
                S.notify("Mine Run", "Save point found via fallback: " .. d:GetFullName(), 6)
            end
            return part
        end
    end
    -- 3) Không thấy gì (nhà thờ bị StreamingEnabled gỡ khi bay xa) -> bay về nhà thờ đã nhớ vị trí.
    local pos = MR._churchPos
    if pos and not MR._saved[S.mineRunWellKey(pos)] then
        return S.mineRunGoToChurch(pos)
    end
    return nil
end

-- Nhà thờ: Workspace.Church.Structure.Ring.SaveGear (MeshPart). Nhớ vị trí lúc nó đang được tải.
function S.mineRunFindChurchRing()
    local church = workspace:FindFirstChild("Church")
    if not church then
        return nil
    end
    for _, d in ipairs(church:GetDescendants()) do
        if d.Name == "SaveGear" and d:IsA("BasePart") then
            return d
        end
    end
    return nil
end

function S.mineRunCacheChurch()
    local MR = S.MineRun
    if MR._churchPos then
        return true
    end
    local ring = S.mineRunFindChurchRing()
    if ring then
        MR._churchPos = ring.Position
        return true
    end
    return false
end

function S.mineRunGoToChurch(pos)
    local MR = S.MineRun
    local root = S.getRoot()
    if not root then
        return nil
    end
    -- Thử lại tối đa mỗi 20s nếu lần trước thất bại.
    if MR._churchTryAt and os.clock() - MR._churchTryAt < 20 then
        return nil
    end
    MR._churchTryAt = os.clock()
    S.notify("Mine Run", "Church not loaded - flying back to it", 5)

    S.holdAutofarmCruise("church")
    S.cancelAutofarmTween()
    S.ensureAutofarmAntiFall(true)
    S.lockAutofarmHover(true)
    S.setAutofarmPlatformStand(true)

    local stand = pos + Vector3.new(0, 3, 0)
    local deadline = os.clock() + 12
    while os.clock() < deadline do
        local r = S.getRoot()
        if r then
            r.Anchored = false
            r.CFrame = CFrame.new(stand)
            r.AssemblyLinearVelocity = Vector3.zero
            r.AssemblyAngularVelocity = Vector3.zero
        end
        pcall(function()
            S.requestStreamAround(pos, 1.0)
        end)
        local ring = S.mineRunFindChurchRing()
        if ring then
            MR._churchTryAt = nil
            return ring
        end
        task.wait(0.4)
    end
    S.notify("Mine Run", "Church still not loaded after 12s", 5)
    return nil
end

task.spawn(function()
    for _ = 1, 300 do
        if S._unloading or S.mineRunCacheChurch() then
            break
        end
        task.wait(3)
    end
end)

-- Debug: in ra console (F9) mọi thứ có vẻ là chỗ lưu đồ, để biết game đặt tên gì.
function S.mineRunDumpSaveGear()
    local keys = { "save", "gear", "altar", "church", "chapel", "shrine", "fountain", "well", "sanct" }
    local n = 0
    local root = S.getRoot()
    for _, d in ipairs(workspace:GetDescendants()) do
        local low = string.lower(d.Name)
        local hit = false
        for _, k in ipairs(keys) do
            if low:find(k, 1, true) then
                hit = true
                break
            end
        end
        if not hit and d:IsA("ProximityPrompt") then
            local t = string.lower(tostring(d.ActionText) .. " " .. tostring(d.ObjectText))
            hit = t:find("save", 1, true) ~= nil or t:find("altar", 1, true) ~= nil
        end
        if hit and (d:IsA("BasePart") or d:IsA("Model") or d:IsA("ProximityPrompt")) then
            n = n + 1
            if n <= 60 then
                local extra = ""
                if d:IsA("ProximityPrompt") then
                    extra = " | " .. tostring(d.ActionText) .. " / " .. tostring(d.ObjectText)
                end
                local pos = d:IsA("BasePart") and d.Position or nil
                local dist = (pos and root) and math.floor((pos - root.Position).Magnitude) or -1
                print(string.format("[SaveGear?] %s (%s) dist=%s%s", d:GetFullName(), d.ClassName, tostring(dist), extra))
            end
        end
    end
    S.notify("Mine Run", n .. " save-point candidates printed to console (F9)", 6)
end

function S.mineRunWellPrompts(part)
    local list, seen = {}, {}
    local function add(prompt)
        if prompt:IsA("ProximityPrompt") and prompt.Enabled and not seen[prompt] then
            seen[prompt] = true
            list[#list + 1] = prompt
        end
    end
    for _, d in ipairs(part:GetDescendants()) do
        add(d)
    end
    local origin = part.Position
    for _, d in ipairs(workspace:GetDescendants()) do
        if d:IsA("ProximityPrompt") and not seen[d] and d.Enabled then
            local wp = S.getPromptWorldPosition(d)
            if wp then
                local dist = (wp - origin).Magnitude
                local text = string.lower(tostring(d.ActionText) .. " " .. tostring(d.ObjectText))
                local isSave = text:find("save", 1, true) ~= nil or text:find("altar", 1, true) ~= nil
                if dist <= 30 or (isSave and dist <= 80) then
                    add(d)
                end
            end
        end
    end
    return list
end

-- ===== "Return to Lobby?" confirm dialog (appears after holding Save Gear) =====
function S.mineRunGuiTextVisible(obj)
    local cur = obj
    while cur do
        if cur:IsA("ScreenGui") and cur.Enabled == false then
            return false
        end
        if cur:IsA("GuiObject") and cur.Visible == false then
            return false
        end
        cur = cur.Parent
    end
    return true
end

-- Returns the visible "Teleport" button of the Return to Lobby dialog, or nil.
function S.mineRunFindTeleportButton()
    local pg = Players.LocalPlayer and Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
    if not pg then
        return nil
    end
    for _, sg in ipairs(pg:GetChildren()) do
        if sg:IsA("ScreenGui") and sg.Enabled ~= false then
            local dialogSeen = false
            local teleportLabel = nil
            for _, d in ipairs(sg:GetDescendants()) do
                if (d:IsA("TextLabel") or d:IsA("TextButton")) and S.mineRunGuiTextVisible(d) then
                    local text = string.lower(tostring(d.Text))
                    if text:find("return to", 1, true) or text:find("gear will be saved", 1, true) then
                        dialogSeen = true
                    end
                    if text:gsub("%s+", "") == "teleport" then
                        teleportLabel = teleportLabel or d
                    end
                end
            end
            if dialogSeen and teleportLabel then
                local cur = teleportLabel
                while cur and cur ~= sg do
                    if cur:IsA("GuiButton") then
                        return cur
                    end
                    cur = cur.Parent
                end
                return teleportLabel
            end
        end
    end
    return nil
end

function S.mineRunPressGui(btn)
    if not btn or not btn.Parent then
        return false
    end
    if btn:IsA("GuiButton") and typeof(getconnections) == "function" then
        for _, signalName in ipairs({ "Activated", "MouseButton1Click" }) do
            pcall(function()
                for _, c in ipairs(getconnections(btn[signalName])) do
                    if type(c.Fire) == "function" then
                        pcall(c.Fire, c)
                    elseif type(c.Function) == "function" then
                        pcall(c.Function)
                    end
                end
            end)
        end
    end
    if btn:IsA("GuiButton") then
        pcall(function()
            btn:Activate()
        end)
    end
    return true
end

-- "Ghost" tap: a virtual touch inside the game. No mouse cursor appears and your own
-- controls keep working. Coordinates are GUI-space (the top bar inset is added here).
S.GHOST_TOUCH_ID = 91
S.AllowRealMouse = false -- true = fall back to the real virtual mouse (shows a cursor)
function S.ghostTap(x, y, holdSeconds)
    local ok = pcall(function()
        local vim = game:GetService("VirtualInputManager")
        local inset = Vector2.zero
        pcall(function()
            inset = game:GetService("GuiService"):GetGuiInset()
        end)
        local px, py = x + inset.X, y + inset.Y
        vim:SendTouchEvent(S.GHOST_TOUCH_ID, 0, px, py)
        task.wait(holdSeconds or 0.05)
        vim:SendTouchEvent(S.GHOST_TOUCH_ID, 2, px, py)
    end)
    return ok
end

function S.mineRunClickGuiCenter(btn)
    pcall(function()
        local center = btn.AbsolutePosition + btn.AbsoluteSize / 2
        if not S.ghostTap(center.X, center.Y, 0.06) and S.AllowRealMouse then
            local vim = game:GetService("VirtualInputManager")
            local inset = game:GetService("GuiService"):GetGuiInset()
            vim:SendMouseButtonEvent(center.X, center.Y + inset.Y, 0, true, game, 0)
            task.wait(0.06)
            vim:SendMouseButtonEvent(center.X, center.Y + inset.Y, 0, false, game, 0)
        end
    end)
end

-- Waits for the dialog, presses Teleport. Returns true if the dialog was confirmed.
function S.mineRunConfirmReturnLobby(timeout)
    local deadline = os.clock() + (tonumber(timeout) or 6)
    while os.clock() < deadline do
        local btn = S.mineRunFindTeleportButton()
        if btn then
            task.wait(0.2)
            S.mineRunPressGui(btn)
            task.wait(0.4)
            if btn.Parent and S.mineRunGuiTextVisible(btn) then
                S.mineRunClickGuiCenter(btn)
            end
            return true
        end
        task.wait(0.25)
    end
    return false
end

function S.mineRunVisitSaveGear(part)
    local MR = S.MineRun
    local pos = part.Position
    MR._saved[S.mineRunWellKey(pos)] = true
    local savedDist = Autofarm.distance or S.syncAutofarmDistanceFromRoot()

    S.holdAutofarmCruise("save gear")
    S.cancelAutofarmTween()
    S.ensureAutofarmAntiFall(true)
    S.lockAutofarmHover(true)
    S.setAutofarmPlatformStand(true)
    pcall(function()
        S.requestStreamAround(pos, 1.0)
    end)

    -- Same height the character has when standing in the ring.
    local standPos = pos + Vector3.new(0, 3, 0)
    Autofarm._mineHoldPos = standPos
    Autofarm._mineLookAt = pos
    Autofarm._gatePinY = standPos.Y

    local function place()
        local root = S.getRoot()
        if root then
            root.Anchored = false
            root.CFrame = CFrame.new(standPos)
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end
        return root
    end

    local root = place()
    task.wait(0.25)
    if root and part.Parent and typeof(firetouchinterest) == "function" then
        pcall(function()
            firetouchinterest(root, part, 0)
            task.wait(0.1)
            firetouchinterest(root, part, 1)
        end)
    end

    -- Saving needs HOLD E while standing in the ring (standing alone does nothing).
    local holdFor = tonumber(MR.saveSeconds) or 4
    local prompts = S.mineRunWellPrompts(part)
    local maxHold = 0
    for _, prompt in ipairs(prompts) do
        maxHold = math.max(maxHold, tonumber(prompt.HoldDuration) or 0)
    end
    if maxHold + 0.6 > holdFor then
        holdFor = maxHold + 0.6
    end

    local promptBackup = S.preparePromptsForHold(prompts)
    local vim
    pcall(function()
        vim = game:GetService("VirtualInputManager")
    end)
    place()
    S.faceCharacterToward(pos)
    local camBackup = S.aimCameraAtWorld(pos, nil)
    task.wait(0.15)

    for _, prompt in ipairs(prompts) do
        pcall(function()
            prompt:InputHoldBegin()
        end)
    end
    pcall(function()
        if vim then
            vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)
        end
    end)

    local stayUntil = os.clock() + holdFor
    while Autofarm.enabled and os.clock() < stayUntil and not S.autofarmCycleShouldAbort() do
        place()
        S.faceCharacterToward(pos)
        camBackup = S.aimCameraAtWorld(pos, camBackup)
        task.wait(0.1)
    end

    for _, prompt in ipairs(prompts) do
        pcall(function()
            prompt:InputHoldEnd()
        end)
    end
    pcall(function()
        if vim then
            vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)
        end
    end)
    -- Fire the "Save Gear" altar prompt directly as a backup (mobile has no E key).
    for _, prompt in ipairs(prompts) do
        local text = string.lower(tostring(prompt.ActionText) .. " " .. tostring(prompt.ObjectText))
        if text:find("save", 1, true) or text:find("altar", 1, true) then
            pcall(S.tryFireProximityPrompt, prompt)
        end
    end
    S.restorePromptsAfterHold(promptBackup)
    S.restoreCameraAim(camBackup)

    -- удержание E не выбирает вещи само → явно сохраняем лучшие через RF (лимит слотов сервера)
    pcall(function()
        local rf = game:GetService("ReplicatedStorage").Packages._Index["sleitnick_knit@1.4.6"].knit.Services.PlayerService.RF
        local choices = rf.GetSaveGearChoices:InvokeServer()
        if type(choices) ~= "table" then return end
        local limit = math.max(0, math.floor(tonumber(choices.Limit) or 9))
        local rank = { kings = 6, phoenix = 5, blackhole = 5, void = 4, diamond = 3, gold = 2 }
        local entries = {}
        for _, it in pairs(choices.Items or {}) do
            local cnt = math.max(0, math.floor(tonumber(it.Count) or 0))
            if type(it.Id) == "string" and cnt > 0 then
                local n, r = string.lower(tostring(it.Name)), 0
                for k, v in pairs(rank) do
                    if n:find(k, 1, true) and not n:find("kingslayer", 1, true) then r = math.max(r, v) end
                end
                entries[#entries + 1] = { id = it.Id, name = tostring(it.Name), cnt = cnt, r = r }
            end
        end
        table.sort(entries, function(a, b) return a.r > b.r end)
        local payload, total, names = {}, 0, {}
        for _, e in ipairs(entries) do
            local take = math.min(e.cnt, limit - total)
            if take > 0 then
                payload[e.id] = take
                total += take
                names[#names + 1] = e.name .. "x" .. take
            end
        end
        if total == 0 then return end
        local res = rf.SaveGear:InvokeServer(payload)
        pcall(appendfile, "DrillFarm.log", os.date("%H:%M:%S") .. " [Save] " .. table.concat(names, ", ") .. " → " .. tostring(res) .. "\n")
    end)

    -- Game shows "Return to Lobby? Your gear will be saved" -> press Teleport.
    local confirmed = S.mineRunConfirmReturnLobby(6)

    MR.savedCount = (MR.savedCount or 0) + 1
    if confirmed then
        S.notify("Mine Run", "Gear saved - Teleport confirmed, returning to lobby", 5)
        S.mineRunFinish("gear saved")
    end
    S.clearMineHoldPin()
    Autofarm._gatePinY = nil
    Autofarm.distance = savedDist
    if Autofarm.enabled then
        S.setAutofarmPose(savedDist)
        S.setAutofarmPlatformStand(true)
        S.ensureAutofarmAntiFall(true)
        S.lockAutofarmHover(true)
    end
    S.notify("Mine Run", "Held E at well #" .. MR.savedCount .. " - gear should be saved", 4)
    return true
end

-- Called from the farm cycle while phase == "store". Returns true if it used the cycle.
function S.mineRunStoreStep()
    local MR = S.MineRun
    if not MR.active then
        return false
    end
    -- Save during the LAST mining lap (no extra lap): lap N of N, one well, then lobby.
    local finalFarmLap = MR.phase == "farm"
        and MR.saveGear == true
        and not MR.chestsAfter
        and (MR.farmLaps or 0) >= (MR.mineLaps or 1) - 1
    if MR.phase ~= "store" and not finalFarmLap then
        return false
    end
    MR._saved = MR._saved or {}
    local part = S.mineRunFindSaveGear()
    if part then
        S.mineRunVisitSaveGear(part)
        return true
    end
    return false
end

function S.mineRunSkipSeek()
    local v = S.mineRunFlagValue("miyugui_mine_skip_seek")
    if v == nil then
        return S.MineRun.skipSeek ~= false
    end
    return v == true
end

-- ===== Core run: save gear at a well after the last chest lap =====
function S.coreWantsStoreLap()
    if game.PlaceId ~= MiyuGUI.placeId or not Autofarm.enabled then
        return false
    end
    local v = S.mineRunFlagValue("miyugui_core_save")
    if v == nil then
        return true
    end
    return v == true
end

function S.coreBeginStore()
    local MR = S.MineRun
    if MR.active then
        return false
    end
    local ok = pcall(function()
        S.mineRunReadSettings()
        MR.saveGear = true
        MR.chestsAfter = false
        MR.active = true
        MR._gen = MR._gen + 1
        MR.farmLaps = 0
        MR.chestLaps = 0
        Autofarm.scrapFarm = false
        S.mineRunBeginStore()
        task.spawn(S.mineRunWatchdog, MR._gen)
    end)
    if not ok then
        MR.active = false
        MR.phase = "off"
        return false
    end
    S.notify("Core", "Chests done - saving gear at a well", 5)
    return true
end

-- ===== Kill mobs on the way (sword swing at hostile mobs near the cruise path) =====
function S.mobHunterStep()
    local H = S.MobHunter
    if not Autofarm.enabled or Autofarm.miningBusy or Autofarm._oreHuntMode or Autofarm._scrapProcessing then
        return
    end
    if Combat._killingWorm or os.clock() < (H.cooldownUntil or 0) then
        return
    end
    if S.MineRun and S.MineRun.active and S.MineRun.phase == "leaving" then
        return
    end
    if not Services.ToolService or not Services.ToolService.Update then
        return
    end
    local range = math.max(15, tonumber(H.range) or 50)
    local mobs = S.findHostileMobsInRange(range)
    if #mobs == 0 then
        return
    end
    H.busy = true
    local ok, err = pcall(function()
        if not S.ensureSwordTool() then
            H.cooldownUntil = os.clock() + 10
            return
        end
        local deadline = os.clock() + 6
        while H.enabled and Autofarm.enabled and os.clock() < deadline do
            if Autofarm.miningBusy or Autofarm._oreHuntMode then
                break
            end
            mobs = S.findHostileMobsInRange(range)
            if #mobs == 0 then
                break
            end
            local tool = S.getEquippedTool()
            if tool then
                S.boostToolRange(tool, range)
            end
            pcall(function()
                S.swingAtTargets(mobs)
            end)
            task.wait(0.15)
        end
        if os.clock() >= deadline then
            H.cooldownUntil = os.clock() + 5 -- mob we cannot kill: do not stall the run
        end
    end)
    H.busy = false
    if not ok then
        warn("[TERRA HUB] mobHunter", err)
    end
    pcall(S.ensurePickaxe, 0.8)
end

function S.setMobHunter(enabled)
    local H = S.MobHunter
    H.enabled = enabled == true
    if H.enabled and not H.running then
        H.running = true
        task.spawn(function()
            while H.running and not S._unloading do
                task.wait(0.35)
                if H.enabled and not H.busy then
                    pcall(S.mobHunterStep)
                end
            end
            H.running = false
        end)
    end
end

-- Called when the cruise wraps at the end of the map.
function S.mineRunNoteLap()
    local MR = S.MineRun
    if not MR.active then
        return
    end
    if MR.phase ~= "farm" and MR.phase ~= "chests" and MR.phase ~= "store" then
        return
    end
    local now = os.clock()
    if now - (MR._lapLock or 0) < 4 then
        return
    end
    MR._lapLock = now
    Autofarm._pendingMapWrap = false
    if MR.phase == "farm" then
        MR.farmLaps = MR.farmLaps + 1
        S.notify("Mine Run", "Mining lap " .. MR.farmLaps .. "/" .. MR.mineLaps, 4)
        if MR.farmLaps >= MR.mineLaps then
            S.mineRunAfterMining()
        end
    elseif MR.phase == "chests" then
        MR.chestLaps = MR.chestLaps + 1
        S.mineRunAfterChests()
    else
        S.mineRunFinish(MR.savedCount > 0 and ("gear saved at " .. MR.savedCount .. " wells") or "no well found")
    end
end

function S.mineRunWatchdog(gen)
    while S.MineRun.active and S.MineRun._gen == gen do
        task.wait(5)
        local MR = S.MineRun
        if not MR.active or MR._gen ~= gen then
            return
        end
        -- Never sit in one match forever; on timeout move on to the next step.
        local limit = 1500
        if MR.phase == "farm" then
            limit = 300 + (MR.mineLaps or 2) * 420
        elseif MR.phase == "chests" or MR.phase == "store" then
            limit = 600
        end
        if os.clock() - (MR._phaseSince or 0) > limit then
            S.notify("Mine Run", "Phase timeout (" .. tostring(MR.phase) .. ") - moving on", 5)
            if MR.phase == "seek" then
                S.mineRunBeginFarm(true)
            elseif MR.phase == "farm" then
                S.mineRunAfterMining()
            elseif MR.phase == "chests" then
                S.mineRunAfterChests()
            elseif MR.phase == "store" then
                S.mineRunFinish("timeout")
            end
        end
    end
end

function S.startMineRun()
    local MR = S.MineRun
    if MR.active or MR._starting then
        return
    end
    if game.PlaceId ~= MiyuGUI.placeId then
        S.notify("Mine Run", "Starts inside a match. In the lobby it only starts the next match.", 5)
        return
    end
    MR._starting = true
    MR._gen = MR._gen + 1
    local gen = MR._gen
    S.mineRunReadSettings()

    local deadline = os.clock() + 60
    while MR._gen == gen and MR.enabled and os.clock() < deadline do
        if S.corePlayerReady() and Services.ToolService and S.getRoot() then
            break
        end
        task.wait(0.5)
    end
    if MR._gen ~= gen or not MR.enabled then
        MR._starting = false
        return
    end

    MR._starting = false
    MR.active = true
    MR.farmLaps = 0
    MR.chestLaps = 0
    MR.savedCount = 0
    MR._saved = {}
    MR._lapLock = os.clock()
    task.spawn(S.mineRunWatchdog, gen)

    S.mineRunBeginFarm(false)
end

function S.stopMineRun()
    local MR = S.MineRun
    MR.enabled = false
    MR.active = false
    MR._starting = false
    MR._gen = MR._gen + 1
    MR.phase = "off"
    S.clearScrapSweepFlags()
    S.restoreScrapSweepLoot()

    -- Auto Mine Run owns the farm lifecycle now. Stop either its temporary
    -- Scrap Farm helper or the main Autofarm engine when the master toggle turns off.
    if game.PlaceId == MiyuGUI.placeId then
        if S.isScrapFarmMode() then
            pcall(S.setScrapFarm, false)
        elseif Autofarm.enabled then
            pcall(S.setAutofarm, false, { skipReturn = true })
        end
    end
end

-- ========== SACKLESS COMPAT (game update: nhấn F nhặt thẳng vào túi đồ, không còn Sack) ==========
-- Nếu không còn tool Sack/ItemBag và không có SackUI -> bỏ qua việc equip/đợi Sack,
-- nhặt bằng ProximityPrompt (F) của item, dự phòng bằng remote Pickup như cũ.
-- Đếm túi lấy từ UI balo mới; thả đồ bán bằng cách bấm món trong balo (chế độ DROP ALL).
function S.isSackless()
    local now = os.clock()
    if S._sacklessAt and now - S._sacklessAt < 4 then
        return S._sackless == true
    end
    S._sacklessAt = now
    local char = LocalPlayer.Character
    if not char or not LocalPlayer:FindFirstChildOfClass("Backpack") then
        return S._sackless == true -- chưa tải xong, giữ kết quả cũ
    end
    local hasBag = false
    pcall(function()
        local eq = S.getEquippedTool()
        if eq and S.isItemBagTool(eq) then
            hasBag = true
        end
        if not hasBag and S.findToolInInventory(S.isItemBagTool) then
            hasBag = true
        end
        if not hasBag and LocalPlayer.PlayerGui:FindFirstChild("SackUI", true) then
            hasBag = true
        end
    end)
    local v = not hasBag
    if v and S._sackless ~= true then
        S.notify("Compat", "No Sack found - using direct pickup (F prompt)", 5)
    end
    S._sackless = v
    return v
end

S._scOrigEnsureItemBag = S.ensureItemBag
function S.ensureItemBag(...)
    if S.isSackless() then
        return
    end
    return S._scOrigEnsureItemBag(...)
end

S._scOrigWaitBag = S.waitForItemBagEquipped
function S.waitForItemBagEquipped(...)
    if S.isSackless() then
        return true
    end
    return S._scOrigWaitBag(...)
end

S._scOrigReadyBag = S.ensureBagReadyForLoot
function S.ensureBagReadyForLoot(...)
    if S.isSackless() then
        return true
    end
    return S._scOrigReadyBag(...)
end

-- ----- Balo mới: UI.HUD.Backpack.Ignore.Inventory (ScrollingFrame > InventoryItem, Label "4 / 15", DropToggle) -----
S.invKeep = { "medkit", "gas can", "gascan", "fuel", "revive" } -- món KHÔNG thả/bán (tên chứa chuỗi này)

function S.invRoot()
    local ui = LocalPlayer.PlayerGui:FindFirstChild("UI")
    local hud = ui and ui:FindFirstChild("HUD")
    return hud and hud:FindFirstChild("Backpack")
end

function S.invFrame()
    local bp = S.invRoot()
    local ig = bp and bp:FindFirstChild("Ignore")
    return ig and ig:FindFirstChild("Inventory")
end

function S.invIsOpen()
    local inv = S.invFrame()
    if not inv or not inv:IsA("GuiObject") then
        return false
    end
    local cur = inv
    while cur and not cur:IsA("LayerCollector") do
        if cur:IsA("GuiObject") and cur.Visible == false then
            return false
        end
        cur = cur.Parent
    end
    local cam = workspace.CurrentCamera
    local vp = cam and cam.ViewportSize
    if vp and (inv.AbsolutePosition.Y > vp.Y or inv.AbsolutePosition.X > vp.X or inv.AbsoluteSize.X <= 0) then
        return false
    end
    return true
end

function S.invIsKeep(name)
    local low = string.lower(tostring(name or ""))
    for _, k in ipairs(S.invKeep) do
        if low:find(k, 1, true) then
            return true
        end
    end
    return false
end

-- "x4" -> 4, "x1,234" -> 1234, rỗng/ẩn -> 1
function S.invParseCount(ct)
    if ct and ct:IsA("TextLabel") then
        local digits = tostring(ct.Text or ""):gsub("[^%d]", "")
        return tonumber(digits) or 1
    end
    return 1
end

-- Cuộn danh sách để ô đồ nằm trong vùng nhìn thấy (máy màn hình nhỏ / nhiều món).
function S.invEnsureVisible(btn)
    local sf = btn and btn.Parent
    if not sf or not sf:IsA("ScrollingFrame") then
        return
    end
    pcall(function()
        local top = sf.AbsolutePosition.Y
        local view = sf.AbsoluteSize.Y
        local by, bh = btn.AbsolutePosition.Y, btn.AbsoluteSize.Y
        if by < top or by + bh > top + view then
            local target = sf.CanvasPosition.Y + (by - top) - (view - bh) / 2
            sf.CanvasPosition = Vector2.new(sf.CanvasPosition.X, math.max(0, target))
            task.wait(0.15)
        end
    end)
end

-- Danh sách món trong balo: { {btn=, name=, count=, keep=} }
function S.invItems()
    local out = {}
    local inv = S.invFrame()
    local sf = inv and inv:FindFirstChild("ScrollingFrame")
    if not sf then
        return out
    end
    for _, b in ipairs(sf:GetChildren()) do
        if b:IsA("ImageButton") then
            local fb = b:FindFirstChild("IconFallback")
            local ct = b:FindFirstChild("Count")
            local name = fb and fb:IsA("TextLabel") and fb.Text or ""
            if name == "" then
                -- Món không có chữ tên: dùng ảnh icon làm tên để các món khác nhau không bị gộp chung.
                local icon = b:FindFirstChild("Icon")
                if icon and icon:IsA("ImageLabel") and icon.Image ~= "" then
                    name = icon.Image
                else
                    name = b.Name
                end
            end
            local count = S.invParseCount(ct)
            out[#out + 1] = { btn = b, name = name, count = count, keep = S.invIsKeep(name) }
        end
    end
    return out
end

-- cur, max (cả đồ trang bị), sellable (số món có thể bán)
function S.invStats()
    local inv = S.invFrame()
    if not inv then
        return nil, nil, 0
    end
    local cur, mx
    local lbl = inv:FindFirstChild("Label")
    if lbl and lbl:IsA("TextLabel") then
        cur, mx = lbl.Text:match("(%d+)%s*/%s*(%d+)")
    end
    local sell = 0
    for _, it in ipairs(S.invItems()) do
        if not it.keep then
            sell = sell + it.count
        end
    end
    return tonumber(cur), tonumber(mx), sell
end

-- Cảnh báo (giãn cách 8s) để biết bước nào của thả đồ bị hỏng.
function S.invWarn(msg)
    local now = os.clock()
    if S._invWarnAt and now - S._invWarnAt < 8 then
        return
    end
    S._invWarnAt = now
    pcall(S.notify, "Drop", msg, 5)
end

-- check: function() -> true khi thao tác có hiệu lực (mở balo / đổi chế độ / món giảm...).
-- Có check: thử lần lượt 3 cách, cách nào có hiệu lực thì dừng (không bấm thừa).
-- Không có check: chỉ cách đầu tiên chạy được.
function S.invClick(btn, check, settle)
    if not btn or not btn.Parent then
        return false
    end
    local function worked()
        if not check then
            return true
        end
        local ok, r = pcall(check)
        return ok and r == true
    end
    local function center()
        local c = btn.AbsolutePosition + btn.AbsoluteSize / 2
        return c.X, c.Y
    end

    -- Cách 1: firesignal (như bản cũ)
    local function m1()
        local done = false
        if typeof(firesignal) == "function" then
            pcall(function()
                firesignal(btn.MouseButton1Click)
                done = true
            end)
            pcall(function()
                firesignal(btn.Activated)
            end)
        end
        return done
    end

    -- Cách 2: gọi thẳng các hàm game đã nối vào nút (cho trường hợp game nghe Down/Up/Activated)
    local function m2()
        if typeof(getconnections) ~= "function" then
            return false
        end
        local x, y = center()
        local done = false
        for _, name in ipairs({ "MouseButton1Down", "MouseButton1Click", "Activated", "MouseButton1Up" }) do
            pcall(function()
                for _, conn in ipairs(getconnections(btn[name])) do
                    local ok = pcall(function()
                        if name == "MouseButton1Down" or name == "MouseButton1Up" then
                            conn:Fire(x, y)
                        else
                            conn:Fire()
                        end
                    end)
                    done = done or ok
                end
            end)
        end
        return done
    end

    -- Method 3: ghost touch inside the game (no mouse cursor, no interruption).
    local function m3()
        local x, y = center()
        if S.ghostTap(x, y, 0.05) then
            return true
        end
        if not S.AllowRealMouse then
            return false
        end
        local vim
        pcall(function()
            vim = game:GetService("VirtualInputManager")
        end)
        if not vim then
            return false
        end
        local inset = Vector2.zero
        pcall(function()
            inset = game:GetService("GuiService"):GetGuiInset()
        end)
        x, y = x + inset.X, y + inset.Y
        local back
        pcall(function()
            back = game:GetService("UserInputService"):GetMouseLocation()
        end)
        pcall(function()
            vim:SendMouseMoveEvent(x, y, game)
            task.wait(0.03)
            vim:SendMouseButtonEvent(x, y, 0, true, game, 0)
            task.wait(0.04)
            vim:SendMouseButtonEvent(x, y, 0, false, game, 0)
            task.wait(0.02)
            if back then
                vim:SendMouseMoveEvent(back.X, back.Y, game)
            end
        end)
        return true
    end

    -- Nút bật/tắt: phải chờ hiệu ứng xong (settle) rồi mới đổi cách, nếu không sẽ bấm đúp = đóng lại.
    local methods = { m1, m2, m3 }
    S._invBest = S._invBest or { InventoryItem = 3 } -- ô đồ: firesignal/getconnections không ăn, chuột thật mới ăn
    local key = btn.Name
    local first = S._invBest[key] or 1
    local order = { first }
    for i = 1, 3 do
        if i ~= first then
            order[#order + 1] = i
        end
    end
    for _, idx in ipairs(order) do
        if not btn.Parent then
            return true -- nút biến mất = game đã xử lý
        end
        local fired = methods[idx]()
        if fired then
            if not check then
                return true
            end
            local waited = 0
            while waited < (settle or 0.3) do
                task.wait(0.1)
                waited = waited + 0.1
                if not btn.Parent or worked() then
                    S._invBest[key] = idx
                    return true
                end
            end
        end
    end
    return false
end

function S.invSetOpen(want)
    if S.invIsOpen() == want then
        return true
    end
    local bp = S.invRoot()
    local toggle = bp and bp:FindFirstChild("Inventory")
    if toggle and toggle:IsA("GuiButton") then
        S.invClick(toggle, function()
            return S.invIsOpen() == want
        end, 1.0)
    else
        S.invWarn("Backpack button not found (UI.HUD.Backpack.Inventory)")
    end
    local okOpen = S.invIsOpen() == want
    if not okOpen then
        S.invWarn(want and "Clicked the Backpack button but it did not open" or "Could not close the Backpack")
    end
    return okOpen
end

-- Đảm bảo nút chế độ ở DROP ALL. Thất bại -> nghỉ 30s, không bấm lại liên tục.
function S.invSetDropAll()
    if S._invDropAllFail and os.clock() < S._invDropAllFail then
        return false
    end
    local inv = S.invFrame()
    local tg = inv and inv:FindFirstChild("DropToggle")
    if not tg then
        return false
    end
    local function isAll()
        local lbl = tg:FindFirstChild("Label", true)
        local text = lbl and lbl:IsA("TextLabel") and string.upper(lbl.Text) or ""
        return text:find("ALL", 1, true) ~= nil
    end
    for _ = 1, 2 do
        if isAll() then
            return true
        end
        S.invClick(tg, isAll, 0.8)
    end
    if isAll() then
        return true
    end
    S._invDropAllFail = os.clock() + 30
    S.invWarn("Could not switch to DROP ALL (only drops 1 per click)")
    return false
end

-- Thả món bán được kế tiếp (DROP ALL = cả stack). Trả về true nếu đã bấm 1 món.
-- Hết đồ -> đóng balo 1 lần rồi nghỉ 2s (dropAllFromBagInstant gọi bagDrop tới 40 lần,
-- trước đây mỗi lần gọi lại mở/đóng balo => spam).
function S.invDropNext()
    S._invSkip = S._invSkip or {}
    local now0 = os.clock()
    if S._invEmptyUntil and now0 < S._invEmptyUntil then
        return false
    end
    if not S.invIsOpen() then
        if S.invSetOpen(true) then
            S._invOpenedByUs = true
        else
            S._invEmptyUntil = os.clock() + 2
            return false
        end
    end
    S.invSetDropAll()
    local now = os.clock()
    for _, it in ipairs(S.invItems()) do
        local until_ = S._invSkip[it.name]
        if not it.keep and not (until_ and until_ > now) then
            local last = S._invLast
            if last and last.name == it.name and last.count == it.count then
                last.tries = last.tries + 1
                if last.tries >= 3 then
                    S._invSkip[it.name] = now + 10 -- bấm 3 lần không đổi -> bỏ qua 10s
                    S._invLast = nil
                    continue
                end
            else
                S._invLast = { name = it.name, count = it.count, tries = 1 }
            end
            S.invEnsureVisible(it.btn)
            local inv0 = S.invFrame()
            local lblObj = inv0 and inv0:FindFirstChild("Label")
            local lbl0 = lblObj and lblObj:IsA("TextLabel") and lblObj.Text or ""
            local clicked = S.invClick(it.btn, function()
                if not it.btn.Parent then
                    return true
                end
                local n = S.invParseCount(it.btn:FindFirstChild("Count"))
                if n ~= it.count then
                    return true
                end
                local f = S.invFrame()
                local l2 = f and f:FindFirstChild("Label")
                return l2 ~= nil and l2:IsA("TextLabel") and l2.Text ~= lbl0
            end, 0.6)
            if not clicked then
                S.invWarn("Clicked '" .. tostring(it.name) .. "' but it did not drop")
            end
            S._sacklessFullUntil = nil
            S._pickConsec = 0
            task.wait(0.12)
            return true
        end
    end
    -- Không còn gì để thả: đóng balo đúng 1 lần rồi nghỉ.
    if S._invOpenedByUs or S.invIsOpen() then
        S.invSetOpen(false)
    end
    S._invOpenedByUs = false
    S._invLast = nil
    S._invEmptyUntil = os.clock() + 2
    return false
end

S._scOrigBagDrop = S.bagDrop
function S.bagDrop(...)
    if S.isSackless() then
        return S.invDropNext()
    end
    return S._scOrigBagDrop(...)
end

S._scOrigGetBagFill = S.getBagFillCount
function S.getBagFillCount(...)
    if S.isSackless() then
        local _, _, sell = S.invStats()
        return sell or 0
    end
    return S._scOrigGetBagFill(...)
end

S._scOrigGetBagCapacity = S.getBagCapacity
function S.getBagCapacity(...)
    if S.isSackless() then
        local cur, mx, sell = S.invStats()
        if mx then
            return math.max(1, mx - math.max(0, (cur or 0) - (sell or 0)))
        end
        return 10
    end
    return S._scOrigGetBagCapacity(...)
end

S._scOrigIsBagFull = S.isBagFull
function S.isBagFull(...)
    if S.isSackless() then
        if S._sacklessFullUntil and os.clock() < S._sacklessFullUntil then
            return true
        end
        local cur, mx = S.invStats()
        return cur ~= nil and mx ~= nil and cur >= mx
    end
    return S._scOrigIsBagFull(...)
end

-- ===== In-game pickup (no F key, no mouse, no camera) =====
-- Stand right on top of the item, then call what the game's own F key calls:
-- InteractionService:Interact(item) / DragController:PerformConsoleInteract() / the item's prompt.
S.PickupKeyFallback = false -- true = press F as a last resort when the in-game pickup fails

function S.inGameInteract(item, attempt)
    pcall(S.setDragTarget, item)
    if Services.InteractionService then
        pcall(function()
            Services.InteractionService:Interact(item)
            for _, d in ipairs(item:GetDescendants()) do
                if CollectionService:HasTag(d, "Interactive") then
                    Services.InteractionService:Interact(d)
                end
            end
        end)
    end
    pcall(function()
        local knit = S.getKnit()
        local drag = knit and knit.GetController("DragController")
        if drag then
            drag.Target = item
            if drag.PerformConsoleInteract then
                drag:PerformConsoleInteract()
            end
        end
    end)
    pcall(S.tryFireProximityPrompt, item)
    if (attempt or 1) >= 2 and Services.ToolService then
        pcall(function()
            local update = Services.ToolService.Update
            if update and update.Fire then
                update:Fire({ "Pickup", item })
            end
        end)
    end
end

function S.pickupInGame(item)
    if not item or not item.Parent then
        return false
    end
    local itemsFolder = Workspace:FindFirstChild("Items")
    local function gone()
        return not item.Parent or (itemsFolder ~= nil and not item:IsDescendantOf(itemsFolder))
    end
    local P = S.ScrapPick or {}
    local prevPin, prevY = Autofarm._mineHoldPos, Autofarm._gatePinY
    local jitter = { 0, 1, -1 }
    local ok = false
    for attempt = 1, math.max(1, tonumber(P.tries) or 3) do
        if gone() then
            ok = true
            break
        end
        if S._unloading then
            break
        end
        local pos = (S.getInstancePosition and S.getInstancePosition(item)) or S.getItemPosition(item)
        local root = S.getRoot()
        if not pos or not root then
            break
        end
        -- Go on top of the item once (no teleport spam if we are already there).
        local standPos = pos + Vector3.new(0, math.max(0, (tonumber(P.stand) or 1) + (jitter[attempt] or 0)), 0)
        if (root.Position - standPos).Magnitude > 2 then
            Autofarm._mineHoldPos = standPos
            Autofarm._gatePinY = standPos.Y
            root.Anchored = false
            root.CFrame = CFrame.new(standPos)
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            RunService.Heartbeat:Wait()
        end
        S.inGameInteract(item, attempt)
        local t0 = os.clock()
        while os.clock() - t0 < 0.15 and not gone() do
            RunService.Heartbeat:Wait()
        end
        if gone() then
            ok = true
            break
        end
    end
    Autofarm._mineHoldPos, Autofarm._gatePinY = prevPin, prevY
    if not ok and not gone() and S.PickupKeyFallback then
        local vim
        pcall(function()
            vim = game:GetService("VirtualInputManager")
        end)
        local pos = S.getInstancePosition and S.getInstancePosition(item)
        if vim and pos then
            local camBackup
            pcall(function()
                S.faceCharacterToward(pos)
                camBackup = S.aimCameraAtWorld(pos, nil)
            end)
            task.wait(0.08)
            pcall(function()
                vim:SendKeyEvent(true, Enum.KeyCode.F, false, game)
                task.wait(0.08)
                vim:SendKeyEvent(false, Enum.KeyCode.F, false, game)
            end)
            pcall(S.restoreCameraAim, camBackup)
            task.wait(0.12)
        end
    end
    return gone()
end

S._scOrigBagPickup = S.bagPickup
function S.bagPickup(item, allowMove)
    if not S.isSackless() then
        return S._scOrigBagPickup(item)
    end
    return S.pickupInGame(item)
end

S._scOrigSackPickupVerified = S.sackPickupVerified
S._pickFail = setmetatable({}, { __mode = "k" })
S._pickSkip = setmetatable({}, { __mode = "k" })
S._pickConsec = 0

function S.sacklessLootAllowed()
    local DR = S.DrillRun
    return Loot.enabled == true
        or Autofarm.enabled == true
        or S.MineRun.active == true
        or (DR and DR.owned == true)
end

function S.sackPickupVerified(item)
    if not S.isSackless() then
        return S._scOrigSackPickupVerified(item)
    end
    -- Auto Loot / Farm switched off: stop right away, do not finish the rest of the batch.
    if not S.sacklessLootAllowed() then
        return false
    end
    if not item or not item.Parent then
        return false
    end
    if (S._pickSkip[item] or 0) > os.clock() then
        return false -- failed twice already: skipped for a while
    end
    if S.pickupInGame(item) then
        S._pickFail[item] = nil
        pcall(S.markAutofarmDrillDropPending, item)
        return true
    end
    local fails = (S._pickFail[item] or 0) + 1
    S._pickFail[item] = fails
    if fails >= 2 then
        S._pickSkip[item] = os.clock() + 60
    end
    return false
end

-- ========== REVIVE KIT (nằm trong Auto Equip Best, loại "Revive") ==========
S.reviveKeepMax = 3 -- keep at most this many Revive Kits on you, stop picking up once reached
function S.isReviveKitItem(item)
    if not item then
        return false
    end
    local blob = string.lower((item.Name or "") .. " " .. tostring(item:GetAttribute("DisplayName") or ""))
    blob = blob:gsub("[^%w]", "")
    return blob:find("revive", 1, true) ~= nil
end

function S.countOwnedReviveKits()
    local tools = 0
    local function scan(container)
        if container then
            for _, ch in ipairs(container:GetChildren()) do
                if ch:IsA("Tool") and S.isReviveKitItem(ch) then
                    tools = tools + 1
                end
            end
        end
    end
    scan(LocalPlayer:FindFirstChildOfClass("Backpack"))
    scan(LocalPlayer.Character)
    local stacked = 0
    pcall(function()
        for _, it in ipairs(S.invItems()) do
            local low = string.lower(tostring(it.name)):gsub("[^%w]", "")
            if low:find("revive", 1, true) then
                stacked = stacked + it.count
            end
        end
    end)
    return math.max(tools, stacked)
end


-- ========== HOLD F DROP + AUTO SCRAP > SHREDDER ==========
-- Giữ F ~7s = game thả sạch túi tại chỗ. Dùng cho ScrapShredder (tất cả luồng dump shredder).
S.HoldDrop = {
    enabled = true,
    seconds = 7,
    maxRounds = 3, -- if the bag still has items after a hold-F, hold again at most this many times
}

-- Auto Scrap: collects natural map scrap; hold F at the selected dump pad to drop the whole bag.
S.ScrapPick = {
    enabled = true,
    stand = 1, -- height above the item when pressing F (low = close to item; each try shifts 1 > 0 > 2)
    tapSeconds = 0.12, -- how long F is held per tap (must be short)
    aimWait = 0.1, -- wait for the game to update its target after aiming the camera
    tries = 3, -- number of F taps per item
}

-- Auto Scrap: tầm quét scrap (stud, tính phẳng như ESP).
S.ScrapSweepRange = 5000

-- Auto Scrap: mở rương > chờ rương nhả đồ > nhặt scrap rơi ra > ra shredder nghiền.
S.ScrapChest = {
    enabled = true,
    waitSeconds = 4.5, -- wait after opening a chest (4-5s)
    dropRadius = 90, -- scrap within this radius of the chest counts as the chest's drops
    lootPasses = 4,
    shredAfterChest = true, -- true: go shred right after picking up; false: only shred when the bag is full
    types = { "Void", "Diamond", "Gold", "Steel", "Core", "Mimic", "Rusty", "Common", "Free", "TutorialCommon" },
}

-- tick(): gọi mỗi 0.1s khi đang giữ, trả false để nhả F sớm.
function S.holdFKey(seconds, tick)
    local vim
    pcall(function()
        vim = game:GetService("VirtualInputManager")
    end)
    if not vim then
        return false
    end
    local okDown = pcall(function()
        vim:SendKeyEvent(true, Enum.KeyCode.F, false, game)
    end)
    if not okDown then
        return false
    end
    local completed = true
    local t0 = os.clock()
    while os.clock() - t0 < (tonumber(seconds) or 7) do
        task.wait(0.1)
        if S._unloading then
            completed = false
            break
        end
        if tick then
            local ok, res = pcall(tick)
            if ok and res == false then
                completed = false
                break
            end
        end
    end
    pcall(function()
        vim:SendKeyEvent(false, Enum.KeyCode.F, false, game)
    end)
    return completed
end

-- Đứng trên pad rồi giữ F. Trả về số món đã thả.
function S.dumpBagHoldF(part, label, opts)
    opts = type(opts) == "table" and opts or {}
    local force = opts.force == true
    if not part then
        return 0
    end
    local before = S.getBagFillCount()
    if before <= 0 then
        return 0
    end

    local root = S.getRoot()
    S.cancelAutofarmTween()
    if root then
        Autofarm.resumePocketDistance = Autofarm.distance or S.syncAutofarmDistanceFromRoot()
        Autofarm.resumePocketPos = root.Position
    end
    if not S.arriveAtDumpPad(part, label, { force = force, timeout = force and 8 or 6 }) then
        return 0
    end
    local standCf = S.getDumpPadStandCFrame(part)
    S.clearDragTarget()

    local function tick()
        if not force and (not Autofarm.enabled or Autofarm._farmShuttingDown) then
            return false
        end
        local r = S.getRoot()
        if r and standCf and not S.isCharacterAtDumpPad(part, 8) then
            r.Anchored = false
            r.CFrame = standCf
            r.AssemblyLinearVelocity = Vector3.zero
            r.AssemblyAngularVelocity = Vector3.zero
        end
        return true
    end

    local after = before
    for round = 1, math.max(1, tonumber(S.HoldDrop.maxRounds) or 1) do
        S.notify(tostring(label or "Drop"), "Holding F " .. tostring(S.HoldDrop.seconds) .. "s (round " .. round .. ")", 3)
        local completed = S.holdFKey(S.HoldDrop.seconds, tick)
        task.wait(0.6)
        pcall(function()
            local update = Services.ToolService and Services.ToolService.Update
            if update and update.Fire then
                update:Fire({ "GetStoredItems" })
            end
        end)
        after = S.getBagFillCount()
        if after <= 0 or not completed then
            break
        end
    end

    Money.trackedBagSize = S.getBagFillCount()
    local dumped = math.max(0, before - after)
    S.notify(tostring(label or "Drop"), "Dropped " .. tostring(dumped) .. " (bag left " .. tostring(after) .. ")", 3)
    return dumped
end

-- ----- Auto Scrap (Scrap Sweep): tween khắp map > thấy scrap thì dừng nhặt > đầy túi thì ra ScrapShredder giữ F -----
-- Dùng lại engine tween của Autofarm. KHÔNG đào quặng, KHÔNG bán, chỉ nhặt item loại scrap.
S.ScrapSweep = { owned = false, saved = nil, autoSell = false, dropInDrill = false }

function S.isScrapSweepMode()
    return Autofarm.scrapSweep == true
end

-- Tên món scrap bổ sung (chữ thường, khớp một phần) nếu game không gắn category "scrap". Ví dụ: { "old boot", "tin can" }
S.ScrapExtraNames = {}

function S.isScrapCategoryItem(item)
    if not item then
        return false
    end
    local name = string.lower(tostring(item.Name or ""))
    local display = string.lower(tostring(item:GetAttribute("DisplayName") or ""))
    local rarity = item:GetAttribute("Rarity")
    local blob = S.itemCategoryKey(item) .. " " .. name .. " " .. display
    for _, attr in ipairs({ "DisplayCategory", "Category", "Class", "ItemType", "Type" }) do
        local raw = item:GetAttribute(attr)
        if raw ~= nil and tostring(raw) ~= "" then
            blob = blob .. " " .. string.lower(tostring(S.stripRarityPrefix(raw, rarity)))
        end
    end
    if blob:find("scrap", 1, true) then
        return true
    end
    for _, n in ipairs(S.ScrapExtraNames) do
        if n ~= "" and (name:find(n, 1, true) or display:find(n, 1, true)) then
            return true
        end
    end
    return false
end

-- Log debug (F9) mỗi ~8s khi đang chạy: số item trong map, số scrap nhận diện được, và 1 item mẫu không khớp.
function S.scrapSweepDebug()
    local now = os.clock()
    if now - (S._ssDbgAt or 0) < 8 then
        return
    end
    S._ssDbgAt = now
    local itemsFolder = Workspace:FindFirstChild("Items")
    if not itemsFolder then
        print("[MiyuGUI scrap] Workspace.Items not found")
        return
    end
    local total, scrap, sample = 0, 0, nil
    for _, it in ipairs(itemsFolder:GetChildren()) do
        total = total + 1
        if S.isScrapCategoryItem(it) then
            scrap = scrap + 1
        elseif not sample then
            sample = it
        end
    end
    local info = ""
    if sample then
        local parts = {}
        for _, attr in ipairs({ "DisplayCategory", "Category", "Class", "ItemType", "Type", "DisplayName", "Rarity" }) do
            parts[#parts + 1] = attr .. "=" .. tostring(sample:GetAttribute(attr))
        end
        info = " | sample non-scrap: " .. sample.Name .. " {" .. table.concat(parts, ", ") .. "}"
    end
    print(string.format("[MiyuGUI scrap] items=%d scrapMatched=%d%s", total, scrap, info))
end

-- Cấu hình engine cho chế độ nhặt scrap (dùng cả cho Auto Scrap lẫn pha farm của Mine Run).
function S.applyScrapSweepSettings()
    Autofarm.scrapSweep = true
    Autofarm.scrapOnlyLoot = true
    Autofarm.scrapFarm = false
    Autofarm.scrapPhase = "seek_pick"
    local SW = S.ScrapSweep or {}
    local useDrill = SW.dropInDrill == true or Autofarm.dropInDrill == true
    local useSell = not useDrill and SW.autoSell == true
    Autofarm.autoSell = useSell
    Autofarm.dropInDrill = useDrill
    Autofarm.dropInShredder = not useDrill and not useSell
    -- Scrap collection is world-loot only: never open chests.
    Autofarm.openChests = false
    Autofarm.enterMines = false
    if Autofarm._dungeonsBeforeSweep == nil then
        Autofarm._dungeonsBeforeSweep = Autofarm.enterDungeons
    end
    Autofarm.enterDungeons = false
    Autofarm.scrapDetectRange = Autofarm.scrapDetectRange or 1500
    Autofarm.oreUnderEnabled = false
    Autofarm.sellThreshold = useSell and 1 or 999 -- sell each collected batch; otherwise process on full bag
    if Autofarm._lootBeforeSweep == nil then
        Autofarm._lootBeforeSweep = Loot.enabled == true
    end
    Loot.enabled = true
    Loot.autoDropAfterLoot = false
    S.trySetRayfieldFlag("terra_af_auto_sell", useSell, true)
    S.trySetRayfieldFlag("terra_af_drop_drill", useDrill, true)
    S.trySetRayfieldFlag("terra_af_drop_shredder", not useDrill and not useSell, true)
    S.trySetRayfieldFlag("terra_af_auto_chests", false, true)
    S.trySetRayfieldFlag("terra_af_join_mines", false, true)
    S.trySetRayfieldFlag("terra_af_auto_ores", false, true)
    S.setAutofarmEquipBest(false)
    S.trySetRayfieldFlag("terra_af_equip_best", false, true)
    GearEquip.enabled = false
end

function S.clearScrapSweepFlags()
    Autofarm.scrapSweep = false
    Autofarm.scrapOnlyLoot = false
end

-- Xả scrap còn trong túi vào shredder trước khi rời pha sweep.
function S.scrapSweepFlush()
    if not (Autofarm.enabled and Autofarm.scrapSweep == true and S.getBagFillCount() > 0) then
        return
    end
    -- Respect the active Auto Scrap destination on shutdown as well as during normal cycles.
    if S.isDropInDrillMode() then
        pcall(S.autofarmDumpBagToDrill)
    elseif Autofarm.autoSell == true then
        pcall(S.autofarmAutoSell)
    elseif S.isDropInShredderMode() then
        pcall(S.autofarmDumpBagToShredder)
    end
end

function S.restoreScrapSweepLoot()
    if Autofarm._dungeonsBeforeSweep ~= nil then
        Autofarm.enterDungeons = Autofarm._dungeonsBeforeSweep
        Autofarm._dungeonsBeforeSweep = nil
    end
    if Autofarm._lootBeforeSweep ~= nil then
        Loot.enabled = Autofarm._lootBeforeSweep == true
        Autofarm._lootBeforeSweep = nil
    end
end

function S.setScrapSweep(enabled)
    local SW = S.ScrapSweep
    enabled = enabled == true
    if enabled == (Autofarm.scrapSweep == true and SW.owned) then
        return
    end
    if enabled then
        if Autofarm.enabled or (S.MineRun and S.MineRun.active) or S.isScrapFarmMode() then
            S.notify("Auto Scrap", "Turn off Autofarm / Mine Run first", 4)
            S.trySetRayfieldFlag("miyugui_scrap_sweep", false, true)
            return
        end
        if game.PlaceId ~= MiyuGUI.placeId then
            S.notify("Auto Scrap", "Starts inside a match", 4)
            S.trySetRayfieldFlag("miyugui_scrap_sweep", false, true)
            return
        end
        Autofarm._farmShuttingDown = false
        SW.saved = S.snapshotScrapSettings()
        SW.saved.sellThreshold = Autofarm.sellThreshold
        SW.owned = true
        S.applyScrapSweepSettings()
        Autofarm.distance = 0
        S.resetAutofarmStart()
        S.setAutofarm(true)
        S.trySetRayfieldFlag("terra_autofarm", true, true)
        S.notify("Auto Scrap", "ON - tween map > loot scrap > shredder (hold F)", 4)
    else
        SW.owned = false
        local saved = SW.saved
        SW.saved = nil
        task.spawn(function()
            -- Tắt engine trước (nó tự xả túi còn lại vào shredder), rồi mới trả cài đặt.
            pcall(S.setAutofarm, false)
            S.clearScrapSweepFlags()
            S.restoreScrapSweepLoot()
            S.trySetRayfieldFlag("terra_autofarm", false, true)
            if saved then
                pcall(S.restoreScrapSettings, saved)
                Autofarm.sellThreshold = saved.sellThreshold or Autofarm.sellThreshold
            end
            S.notify("Auto Scrap", "OFF", 3)
        end)
    end
end

-- Cruise chỉ dừng nhặt khi item trong ~220 stud. Ở chế độ scrap thì nới ra Autofarm.scrapDetectRange (1500).
S._ssOrigHasLoot = S.hasAutofarmLootInRange
function S.hasAutofarmLootInRange(range)
    if Autofarm.scrapSweep == true then
        pcall(S.scrapSweepDebug)
        if range == nil then
            range = tonumber(Autofarm.scrapDetectRange) or 1500
        end
    end
    return S._ssOrigHasLoot(range)
end

-- ===== Scrap Sweep v2 =====

-- (a) Tầm quét xa hơn: collectLootTargets/cruise dùng getLootMaxRange, nên nâng nó lên khi đang sweep.
S._ssOrigGetLootMaxRange = S.getLootMaxRange
function S.getLootMaxRange()
    local r = S._ssOrigGetLootMaxRange()
    if Autofarm.scrapSweep == true then
        r = math.max(tonumber(r) or 0, tonumber(Autofarm.scrapDetectRange) or 0)
    end
    return r
end

S._ssOrigApplySettings = S.applyScrapSweepSettings
function S.applyScrapSweepSettings(...)
    S._ssOrigApplySettings(...)
    Autofarm.scrapDetectRange = math.max(tonumber(Autofarm.scrapDetectRange) or 0, tonumber(S.ScrapSweepRange) or 5000)
    -- Only the standalone Auto Scrap mode disables chest opening; Mine Run keeps its own chest phase.
    if S.ScrapSweep and S.ScrapSweep.owned == true then
        Autofarm.openChests = false
        S.trySetRayfieldFlag("terra_af_auto_chests", false, true)
    end
end

-- (b) Nhặt bằng phím F: bay sát item > ngắm camera vào item > bấm F ngắn > kiểm tra item biến mất.
S._ssFFail = setmetatable({}, { __mode = "k" })

function S._ssPickInner(item)
    return S.pickupInGame(item)
end

function S.scrapPickItemF(item)
    local prevPin, prevY = Autofarm._mineHoldPos, Autofarm._gatePinY
    local camera = Workspace.CurrentCamera
    local oldSubject = camera and camera.CameraSubject
    local oldType = camera and camera.CameraType
    local ok, res = xpcall(function() return S._ssPickInner(item) end, debug.traceback)
    Autofarm._mineHoldPos, Autofarm._gatePinY = prevPin, prevY
    pcall(function()
        local current = Workspace.CurrentCamera
        if current and (current.CameraType == Enum.CameraType.Scriptable or current.CameraSubject == item) then
            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            current.CameraType = Enum.CameraType.Custom
            current.CameraSubject = (oldSubject and oldSubject.Parent) and oldSubject or hum
            if oldType and oldType ~= Enum.CameraType.Scriptable then current.CameraType = oldType end
        end
    end)
    if not ok then warn("[MiyuGUI][AutoScrap] pickup error:", res); return false end
    return res == true
end

-- Sweep: nhặt hụt vài lần KHÔNG được coi là túi đầy (chỉ đầy thật khi số món >= sức chứa).
S._ssOrigSackPickupVerified = S.sackPickupVerified
function S.sackPickupVerified(item)
    local r = S._ssOrigSackPickupVerified(item)
    if Autofarm.scrapSweep == true and S._sacklessFullUntil then
        local okS, cur, mx = pcall(S.invStats)
        if not (okS and cur ~= nil and mx ~= nil and cur >= mx) then
            S._sacklessFullUntil = nil
            S._pickConsec = 0
        end
    end
    return r
end

S._ssOrigBagPickup = S.bagPickup
function S.bagPickup(item, allowMove)
    if Autofarm.scrapSweep == true and S.ScrapPick and S.ScrapPick.enabled ~= false and item then
        local failedAt = S._ssFFail[item]
        if not failedAt or os.clock() - failedAt > 0.65 then
            if S.scrapPickItemF(item) then
                S._ssFFail[item] = nil
                return true
            end
            S._ssFFail[item] = os.clock()
        end
    end
    return S._ssOrigBagPickup(item, allowMove)
end

-- (c) Mở rương > chờ 4-5s > nhặt scrap rơi ra > (nghiền ở shredder).
function S.scrapSweepAfterChest(_chestPos)
    -- Intentionally disabled: Auto Scrap only collects naturally spawned map scrap.
    return 0
end

S._ssOrigVisitChest = S.autofarmVisitChest
function S.autofarmVisitChest(chest)
    -- Auto Scrap must never open a chest or collect chest-generated drops.
    if Autofarm.scrapSweep == true and S.ScrapSweep and S.ScrapSweep.owned == true then
        return false
    end
    return S._ssOrigVisitChest(chest)
end

-- ========== AUTO DRILL RUN (1 nút) ==========
-- Một nút bật tất cả, chạy vòng lặp:
--   FARM : đào ore (bán khi đầy) -> mở rương -> nhặt scrap + bán hết
--   DRIVE: ngồi cabin tự lái drill driveSeconds giây (Kill Aura đánh quái lại gần)
--   rồi lặp lại. Auto Buy Upgrades chạy suốt (Drill Power > Máu > Damage kiếm > ...).
-- Dùng lại Mine Run có sẵn nên mọi logic farm/rương giữ nguyên.
S.DrillRun = {
    enabled = false,
    owned = false,
    phase = "off", -- off | farm | drive
    _gen = 0,
    _own = {},
    _mrBackup = nil,
    mineLaps = 1, -- ore farm laps before opening chests
    killRange = 40, -- mob attack range (studs), only hits ones that come close
    driveSeconds = 150, -- seconds to drive before returning to farm/chests/sell/upgrade
    autoFuel = true, -- turn on Auto Fuel when driving starts
    -- Thứ tự mua nâng cấp (tên nội bộ): Drill Power -> Máu -> Damage kiếm -> còn lại.
    upgradeOrder = {
        "DrillPower",
        "TeamHealth",
        "TeamMeleeDamage",
        "HealthRegen",
        "EngineOverdrive",
        "DeadlyDrill",
        "DrillDefense",
        "PowerDrive",
        "SackStorage",
        "FuelStorage",
        "DriveSpeed",
    },
}

function S.drillRunFlag(name, value)
    pcall(S.trySetRayfieldFlag, name, value, true)
end

-- Ưu tiên nâng cấp của Drill Run đứng trước, ưu tiên người dùng đặt ở tab Shop đứng sau.
S._drOrigGetUpgradePriorities = S.getUpgradePriorities
function S.getUpgradePriorities()
    local list = {}
    local D = S.DrillRun
    if D and D.owned then
        for _, internal in ipairs(D.upgradeOrder) do
            list[#list + 1] = S.getUpgradeDisplayName(internal)
        end
    end
    for _, v in ipairs(S._drOrigGetUpgradePriorities()) do
        list[#list + 1] = v
    end
    return list
end

-- Ép Mine Run chạy đúng kiểu Drill Run: có vòng rương, không save gear, không bỏ qua pickaxe.
S._drOrigMineRunReadSettings = S.mineRunReadSettings
function S.mineRunReadSettings(...)
    S._drOrigMineRunReadSettings(...)
    local D = S.DrillRun
    if D and D.owned then
        local MR = S.MineRun
        MR.mineLaps = math.clamp(math.floor(tonumber(D.mineLaps) or 1), 1, 10)
        MR.chestsAfter = true
        MR.saveGear = false
        MR.skipSeek = true
    end
end

-- Khi Mine Run xong (đã mở rương) thì thay vì về lobby: lái drill.
S._drOrigMineRunFinish = S.mineRunFinish
function S.mineRunFinish(reason)
    local D = S.DrillRun
    local MR = S.MineRun
    if D and D.owned and D.phase == "farm" and MR.active and MR.phase ~= "leaving" then
        task.spawn(function()
            pcall(S.drillRunBeginDrive, reason)
        end)
        return
    end
    return S._drOrigMineRunFinish(reason)
end

S._drOrigMineRunBeginChests = S.mineRunBeginChests
function S.mineRunBeginChests(...)
    S._drOrigMineRunBeginChests(...)
    local D = S.DrillRun
end

function S.drillRunRestoreMR()
    local D = S.DrillRun
    local b = D._mrBackup
    if not b then
        return
    end
    local MR = S.MineRun
    MR.mineLaps = b.mineLaps
    MR.chestsAfter = b.chestsAfter
    MR.saveGear = b.saveGear
    MR.skipSeek = b.skipSeek
    D._mrBackup = nil
end

function S.drillRunBeginDrive(reason)
    local D = S.DrillRun
    if not D.owned or D.phase ~= "farm" then
        return
    end
    D.phase = "drive"
    local gen = D._gen

    -- Tắt Mine Run (giữ farm engine tới khi bán xong).
    local MR = S.MineRun
    MR.active = false
    MR.enabled = false
    MR._starting = false
    MR._gen = MR._gen + 1
    MR.phase = "off"

    Autofarm.openChests = false
    Autofarm.oreUnderEnabled = false
    Autofarm.enterMines = false
    Autofarm.autoSell = true
    S.drillRunFlag("terra_af_auto_chests", false)
    S.drillRunFlag("terra_af_auto_ores", false)
    S.drillRunFlag("terra_af_join_mines", false)

    -- Bán hết đồ còn lại (scrap/ore) trước khi lái.
    pcall(function()
        if Autofarm.enabled and S.getBagFillCount() > 0 then
            S.autofarmAutoSell()
        end
    end)
    if not D.owned or D._gen ~= gen then
        return
    end

    S.notify("Drill Run", "Farm done (" .. tostring(reason) .. ") - sold, upgrading, driving", 5)
    pcall(S.setAutofarm, false, { skipReturn = true })
    task.wait(3) -- chờ Auto Buy mua nâng cấp bằng tiền vừa bán
    if not D.owned or D._gen ~= gen then
        return
    end

    if D.autoFuel and not Loot.autoFuel then
        D._own.fuel = true
        pcall(S.setAutoFuel, true)
        S.drillRunFlag("terra_auto_fuel", true)
    end

    D._driveSince = os.clock()
    if not AutoDrive.enabled and not AutoDrive.claiming then
        pcall(S.setAutoDrive, true)
    end
    S.drillRunFlag("terra_auto_drive", true)
end

-- Hết thời gian lái: rời cabin, quay lại farm + rương + bán + nâng cấp.
function S.drillRunBeginFarm()
    local D = S.DrillRun
    if not D.owned or D.phase ~= "drive" then
        return
    end
    D.phase = "farm"
    D.cycles = (D.cycles or 0) + 1
    S.notify("Drill Run", "Cycle " .. D.cycles .. ": back to farm / chests / sell", 5)
    if AutoDrive.enabled or AutoDrive.claiming then
        pcall(S.setAutoDrive, false)
    end
    S.drillRunFlag("terra_auto_drive", false)
    task.wait(0.6)
    if not D.owned then
        return
    end
    local MR = S.MineRun
    MR.enabled = true
    pcall(S.startMineRun)
end

-- Giám sát: đổi pha theo thời gian, ngồi lại ghế nếu mất.
function S.drillRunWatch(gen)
    local D = S.DrillRun
    local misses = 0
    while D.owned and D._gen == gen and not S._unloading do
        task.wait(3)
        if not D.owned or D._gen ~= gen then
            return
        end
        if D.phase == "farm" then
            local MR = S.MineRun
            -- Mine Run đã tắt từ ngoài mà chưa sang lái -> sang lái luôn.
            if not MR.active and not MR._starting and not MR.enabled then
                pcall(S.drillRunBeginDrive, "farm ended")
            end
        elseif D.phase == "drive" then
            if os.clock() - (D._driveSince or os.clock()) >= (tonumber(D.driveSeconds) or 150) then
                task.spawn(function()
                    pcall(S.drillRunBeginFarm)
                end)
                misses = 0
            elseif AutoDrive.claiming then
                misses = 0
            elseif not AutoDrive.enabled or not S.isLocalDrillDriver() then
                misses = misses + 1
                if misses >= 2 then
                    misses = 0
                    pcall(S.setAutoDrive, false)
                    task.wait(0.4)
                    if D.owned and D._gen == gen and D.phase == "drive" then
                        pcall(S.setAutoDrive, true)
                    end
                end
            else
                misses = 0
            end
        end
    end
end

function S.startDrillRun()
    local D = S.DrillRun
    if D.owned then
        return true
    end
    if game.PlaceId ~= MiyuGUI.placeId then
        S.notify("Drill Run", "Only works inside a match (not the lobby).", 5)
        return false
    end
    if D._starting then
        return true
    end
    D._starting = true
    local readyDeadline = os.clock() + 30
    while not (Services.DrillService and Services.ToolService) and os.clock() < readyDeadline do
        task.wait(0.5)
    end
    D._starting = false
    if D.owned then
        return true
    end

    -- Dọn các chế độ farm khác để không đánh nhau.
    local MR = S.MineRun
    if MR.enabled or MR.active or MR._starting then
        pcall(S.stopMineRun)
        S.drillRunFlag("miyugui_mine_run", false)
        S.drillRunFlag("terra_autofarm", false)
    end
    if Autofarm.enabled then
        pcall(S.setAutofarm, false, { skipReturn = true })
    end

    D.enabled = true
    D.owned = true
    D.phase = "farm"
    D._gen = D._gen + 1
    D._own = {}
    D.cycles = 0
    local gen = D._gen

    D._mrBackup = {
        mineLaps = MR.mineLaps,
        chestsAfter = MR.chestsAfter,
        saveGear = MR.saveGear,
        skipSeek = MR.skipSeek,
    }

    -- 1) Auto buy upgrades
    if not Upgrades.autoBuy then
        D._own.upgrades = true
        pcall(S.setAutoUpgrade, true)
        S.drillRunFlag("terra_auto_upgrades", true)
    end

    -- 2) Kill Aura: chỉ đánh quái trong tầm gần
    local range = math.clamp(tonumber(D.killRange) or 60, 15, 200)
    if not Combat.killAura then
        D._own.aura = true
        Combat.auraRange = range
        pcall(S.setKillAura, true)
        S.drillRunFlag("terra_kill_aura", true)
    end

    -- 3) Auto farm + chests (Mine Run), 4) rồi lái drill (xem mineRunFinish)
    MR.enabled = true
    task.spawn(function()
        pcall(S.startMineRun)
    end)
    task.spawn(S.drillRunWatch, gen)
    S.notify("Drill Run", "ON: farm -> chests -> sell -> upgrade -> drive, repeating", 5)
    return true
end

function S.stopDrillRun()
    local D = S.DrillRun
    if not D.owned then
        D.enabled = false
        D.phase = "off"
        return
    end
    D.owned = false
    D.enabled = false
    D._gen = D._gen + 1
    D.phase = "off"

    local MR = S.MineRun
    if MR.active or MR.enabled or MR._starting then
        pcall(S.stopMineRun)
    end
    S.drillRunRestoreMR()

    if AutoDrive.enabled or AutoDrive.claiming then
        pcall(S.setAutoDrive, false)
    end
    S.drillRunFlag("terra_auto_drive", false)

    if D._own.fuel then
        pcall(S.setAutoFuel, false)
        S.drillRunFlag("terra_auto_fuel", false)
    end
    if D._own.upgrades then
        pcall(S.setAutoUpgrade, false)
        S.drillRunFlag("terra_auto_upgrades", false)
    end
    if D._own.aura then
        pcall(S.setKillAura, false)
        S.drillRunFlag("terra_kill_aura", false)
    end
    D._own = {}
    S.notify("Drill Run", "OFF", 3)
end

function S.coreBootAutoload()
    pcall(S.corePullLoadedFlags)
    if game.PlaceId ~= MiyuGUI.placeId then
        return
    end
    if S.coreToggleOn("miyugui_drill_run") then
        task.spawn(function()
            pcall(S.startDrillRun)
        end)
        return
    end
    if S.coreToggleOn("miyugui_mine_run") then
        S.MineRun.enabled = true
        task.spawn(function()
            pcall(S.startMineRun)
        end)
        return
    end
    if S.coreToggleOn("dtec_core_open") or CoreFarm.openAll == true then
        if not CoreFarm._runStarted and not CoreFarm._applying then
            CoreFarm.openAll = true
            CoreFarm._ownedRun = true
            S.coreApplyRun()
        end
        return
    end
    if S.coreToggleOn("terra_af_scrap_farm") then
        S.setScrapFarm(true)
        return
    end
    -- Legacy terra_autofarm is now only a compatibility/UI flag.
    -- Auto Mine Run (miyugui_mine_run) owns the actual farm startup.
end

function S.buildUI()
    S._configLoading = true
    S.hubLog("CreateWindow...")
    Autofarm.depthHudVisible = false
    pcall(S.destroyDepthGui)
    local Window = Rayfield:CreateWindow({})

    local function safeTab(name, fn)
        local ok, err = pcall(fn)
        if not ok then
            S.hubLog("TAB FAIL " .. name .. ": " .. tostring(err))
            S.notify("UI", name .. " failed: " .. tostring(err), 8)
        end
    end

    safeTab("Lobby", function()
        S.buildLobbyTab(Window)
    end)
    safeTab("Core", function()
        S.buildCoreTab(Window)
    end)
    safeTab("Farm", function()
    S.buildAutofarmTab(Window)
    end)
    safeTab("Combat", function()
    S.buildCombatTab(Window)
    end)
    safeTab("Auto Combat", function()
        S.buildAutoCombatTab(Window)
    end)
    safeTab("ESP", function()
    S.buildEspTab(Window)
    end)
    safeTab("World", function()
        S.buildWorldTab(Window)
    end)
    safeTab("Player", function()
    S.buildPlayerTab(Window)
    end)
    safeTab("Shop", function()
        S.buildAutoBuyTab(Window)
    end)

    pcall(function()
        if S._miyuguiHub and S._miyuguiHub.complete then
            S._miyuguiHub.complete(S._miyuguiWindow, S._miyuguiLibrary, S._miyuguiSave, S._miyuguiTheme, {
                ToggleKeybind = "RightControl",
                Game = MiyuGUI.game,
                Version = MiyuGUI.version,
            })
        end
    end)

    S._configLoading = false
    task.defer(function()
        S._configLoading = false
        -- Load the selected saved profile first; configTryAutoload will start
        -- the appropriate farm only after its saved toggle values are applied.
        pcall(S.configTryAutoload)
    end)
    S.hubLog("UI ready")
    pcall(function()
        S.setFullbright(true)
        S.trySetRayfieldFlag("terra_fullbright", true, true)
    end)
    S.notify(HUB_NAME, "UI loaded successfully", 5)
    S._uiReady = true
end

