-- ============================================================
-- AUTO SKIP CUTSCENE ĐẦU GAME (chạy độc lập, không cần bật Auto Chest)
-- Spam skip trong SKIP_WINDOW giây đầu tiên để bỏ qua cả 2 cutscene liền nhau.
-- ============================================================
local SKIP_WINDOW = 60          -- chỉnh 30 -> 60 giây tuỳ ý
local SKIP_INTERVAL = 0.25      -- chu kỳ KIỂM TRA (giây) - chỉ bấm khi thật sự có cutscene
local SKIP_ACT_GAP = 1.2        -- giãn cách tối thiểu giữa 2 lần vote/bấm (giây)
local SKIP_BLIND_CLICK = false  -- true = click mù góc phải dưới, nhưng CHỈ khi đang trong cutscene

function S.startupFindSkipButton()
    local gui = LocalPlayer:FindFirstChild("PlayerGui")
    local cs = gui and gui:FindFirstChild("CutSceneUI")
    local skip = cs and cs:FindFirstChild("Skip")
    if skip and skip.Visible == true then
        return skip
    end
    return nil
end

function S.startupVoteSkip()
    local nowVote = os.clock()
    if nowVote - (S._lastSkipVoteAt or 0) < SKIP_ACT_GAP then
        return
    end
    S._lastSkipVoteAt = nowVote
    local knit = S.getKnit()
    if not knit then
        return
    end
    local ctrl, svc
    pcall(function()
        ctrl = knit.GetController("CutSceneController")
    end)
    pcall(function()
        svc = knit.GetService("CutSceneService")
    end)
    local scene = ctrl and ctrl.CurrentCutScene
    if not scene then
        return
    end
    if svc then
        local ctx = ctrl.CurrentCutSceneContext
        if ctx and ctx.Private and ctx.RuntimeId ~= nil then
            pcall(function()
                svc:VoteSkipPrivate(ctx.RuntimeId, scene)
            end)
        else
            pcall(function()
                svc:VoteSkip(scene)
            end)
        end
    end
    if ctrl.AbortCutScene and workspace:GetAttribute("InCutScene") == true then
        pcall(function()
            ctrl:AbortCutScene()
        end)
    end
end

-- Bấm vào góc phải dưới màn hình (vị trí nút "Skip Cutscene")
function S.startupClickBottomRight()
    pcall(function()
        local cam = workspace.CurrentCamera
        if not cam then
            return
        end
        local vp = cam.ViewportSize
        local x, y = vp.X * 0.85, vp.Y * 0.92
        if not S.ghostTap(x, y, 0.03) and S.AllowRealMouse then
            local vim = game:GetService("VirtualInputManager")
            vim:SendMouseButtonEvent(x, y, 0, true, game, 0)
            task.wait(0.03)
            vim:SendMouseButtonEvent(x, y, 0, false, game, 0)
        end
    end)
end

local SKIP_WITH_MINE_RUN = true -- true = Auto Mine Run đang bật thì luôn tự skip cutscene

function S.startupMineRunOn()
    local MR = S.MineRun
    if MR and (MR.active == true or MR.enabled == true) then
        return true
    end
    local ok, on = pcall(S.coreToggleOn, "miyugui_mine_run")
    return ok and on == true
end

task.spawn(function()
    local t0 = os.clock()
    local lastPress, lastClick, lastBlind = 0, 0, 0
    while true do
        task.wait(SKIP_INTERVAL)
        local inStartup = os.clock() - t0 < SKIP_WINDOW
        local withMineRun = SKIP_WITH_MINE_RUN and S.startupMineRunOn()
        if inStartup or withMineRun then
            pcall(function()
                local btn = S.startupFindSkipButton()
                local inCut = workspace:GetAttribute("InCutScene") == true
                -- Không có cutscene và không có nút Skip -> đứng yên, KHÔNG bấm gì.
                if not btn and not inCut then
                    return
                end
                local now = os.clock()
                S.startupVoteSkip() -- tự giới hạn tần suất (SKIP_ACT_GAP)
                if btn then
                    if now - lastPress >= SKIP_ACT_GAP then
                        lastPress = now
                        S.mineRunPressGui(btn)
                    elseif now - lastPress >= 0.6 and now - lastClick >= SKIP_ACT_GAP * 2 then
                        -- Nút vẫn còn sau 0.6s -> bấm chuột thật 1 lần (dự phòng).
                        lastClick = now
                        S.mineRunClickGuiCenter(btn)
                    end
                elseif SKIP_BLIND_CLICK and inCut and now - lastBlind >= SKIP_ACT_GAP * 2 then
                    lastBlind = now
                    S.startupClickBottomRight()
                end
            end)
        end
    end
end)

function S.coreToggleOn(flagName)
    local flags = Rayfield and Rayfield.Flags
    local flag = flags and flags[flagName]
    if flag and flag._obsidian and flag._obsidian.Value ~= nil then
        return flag._obsidian.Value == true
    end
    if flag and flag.CurrentValue == true then
        return true
    end
    local lib = S._miyuguiLibrary
    local toggle = lib and lib.Toggles and lib.Toggles[flagName]
    return toggle ~= nil and toggle.Value == true
end

function S.corePullLoadedFlags()
    local flags = Rayfield and Rayfield.Flags
    if type(flags) ~= "table" then
        return
    end
    if flags.dtec_lobby_auto then
        CoreFarm.enabled = S.coreToggleOn("dtec_lobby_auto")
    end
    local mode = flags.dtec_lobby_mode
    if mode and type(mode.CurrentValue) == "string" then
        CoreFarm.mode = mode.CurrentValue == "Ranked" and "Ranked" or "Unranked"
    end
    local size = flags.dtec_lobby_size
    if size and tonumber(size.CurrentValue) then
        CoreFarm.partySize = math.clamp(math.floor(tonumber(size.CurrentValue)), 1, 8)
    end
    if flags.dtec_core_open then
        CoreFarm.openAll = S.coreToggleOn("dtec_core_open")
    end
    local rescans = flags.dtec_core_rescan
    if rescans and tonumber(rescans.CurrentValue) then
        CoreFarm.rescans = math.clamp(math.floor(tonumber(rescans.CurrentValue)), 1, 10)
    end
    local dungeon = flags.dtec_core_dungeon
    if dungeon then
        CoreFarm.joinDungeon = dungeon.CurrentValue == true
    end
    local mines = flags.dtec_core_mines
    if mines then
        CoreFarm.joinMines = mines.CurrentValue == true
    end
    local types = flags.dtec_core_chest_types
    local pickedTypes = types and S.chestSelectionList(types.CurrentValue or (types._obsidian and types._obsidian.Value))
    if pickedTypes and #pickedTypes > 0 then
        CoreFarm.chestTypes = pickedTypes
    end
    if flags.dtec_lobby_chest_auto_buy then
        LobbyChestWatch.autoBuy = S.coreToggleOn("dtec_lobby_chest_auto_buy")
    end
    local chestTiers = flags.dtec_lobby_chest_tiers
    local tierPick = chestTiers and S.lobbyChestWatchListFromDropdown(chestTiers.CurrentValue or (chestTiers._obsidian and chestTiers._obsidian.Value))
    if tierPick and #tierPick > 0 then
        LobbyChestWatch.watchTiers = tierPick
    end
end

task.spawn(function()
    while true do
        local waitSec = 1.0
        if LobbyChestWatch.autoBuy then
            waitSec = 0.65
        end
        task.wait(waitSec)
        pcall(S.tickLobbyChestWatch)
    end
end)

task.spawn(function()
    while not S._uiReady do
        task.wait(0.2)
    end
    task.wait(0.4)
    pcall(S.corePullLoadedFlags)
    while true do
        task.wait(1.5)
        if S._configLoading then
            continue
        end
        if game.PlaceId == LOBBY_PLACE and not CoreFarm._starting then
            if S.coreToggleOn("dtec_lobby_auto") then
                CoreFarm.enabled = true
                local flags = Rayfield and Rayfield.Flags
                local modeFlag = flags and flags.dtec_lobby_mode
                local modeObs = modeFlag and modeFlag._obsidian
                local modeVal = (modeObs and modeObs.Value) or (modeFlag and modeFlag.CurrentValue)
                if type(modeVal) == "string" then
                    CoreFarm.mode = modeVal == "Ranked" and "Ranked" or "Unranked"
                end
                local sizeFlag = flags and flags.dtec_lobby_size
                local sizeObs = sizeFlag and sizeFlag._obsidian
                local sizeVal = (sizeObs and sizeObs.Value) or (sizeFlag and sizeFlag.CurrentValue)
                if tonumber(sizeVal) then
                    CoreFarm.partySize = math.clamp(math.floor(tonumber(sizeVal)), 1, 8)
                end
            end
            if S.coreToggleOn("miyugui_mine_run") then
                if not CoreFarm.enabled then
                    CoreFarm.enabled = true
                    S._mineRunLobbyOwned = true
                end
            elseif S._mineRunLobbyOwned then
                S._mineRunLobbyOwned = false
                if not S.coreToggleOn("dtec_lobby_auto") then
                    CoreFarm.enabled = false
                    CoreFarm._partyStarted = false
                end
            end
            if CoreFarm.enabled then
                if S.corePartyIsLeaving() then
                    CoreFarm._partyStarted = true
                elseif not CoreFarm._partyStarted then
                    task.spawn(function()
                        pcall(S.coreStartLobby)
                    end)
                else
                    local knit = S.getKnit()
                    local ctrl
                    if knit then
                        pcall(function()
                            ctrl = knit.GetController("PartyCreateController")
                        end)
                    end
                    if not ctrl or not ctrl.Zone then
                        CoreFarm._partyStarted = false
                    end
                end
            end
        elseif game.PlaceId == MiyuGUI.placeId then
            if CoreFarm._userStop then
                local mineRunBusy = S.MineRun ~= nil and S.MineRun.active == true
                CoreFarm.openAll = false
                CoreFarm._ownedRun = false
                CoreFarm._runStarted = false
                CoreFarm._applying = false
                if Autofarm.enabled and not mineRunBusy then
                    S.setAutofarm(false)
                end
                if S.coreToggleOn("dtec_core_open") then
                    S.trySetRayfieldFlag("dtec_core_open", false)
                end
                if S.coreToggleOn("terra_autofarm") and not mineRunBusy then
                    S.trySetRayfieldFlag("terra_autofarm", false)
                end
                if mineRunBusy
                    or (not Autofarm.enabled and not S.coreToggleOn("dtec_core_open") and not S.coreToggleOn("terra_autofarm"))
                then
                    CoreFarm._userStop = false
                end
            elseif S.coreToggleOn("dtec_core_open") then
                CoreFarm.openAll = true
            end
            local farmOn = Autofarm.enabled == true and typeof(Autofarm.origin) == "Vector3"
            if CoreFarm._applying and not farmOn and os.clock() - (CoreFarm._applySince or 0) > 5 then
                CoreFarm._applying = false
                CoreFarm._runStarted = false
            end
            if not CoreFarm._userStop and CoreFarm.openAll and not farmOn and not CoreFarm._applying then
                CoreFarm._runStarted = false
                CoreFarm._ownedRun = true
                task.spawn(function()
                    pcall(S.coreApplyRun)
                end)
            elseif CoreFarm.openAll and farmOn then
                pcall(S.coreHoldChestRun)
                pcall(S.coreUnstickRun)
            end
        end
    end
end)


-- ===================================================================
-- MiyuGUI patch: Auto Pickup gear bằng phím F (chỉ sau khi MỞ rương)
--  * Chỉ nhặt: Pickaxe/Sword/Gun tier Diamond, Void, Phoenix, Kings + Revive Kit (bỏ qua Miner Helmet / giáp / còn lại)
--  * Mở rương xong đi tiếp NGAY, không chờ. Chỉ khi thấy món cần tìm rơi ra mới dừng lại nhặt
--  * Chỉ nhặt món MỚI rơi ra sau khi mở 1 rương (không quét cả map sau khi farm xong)
--  * Bay 1 lần tới sát item, lơ lửng DƯỚI item + nhìn vào item (neo yên, không tp lặp), chờ tới khi nhặt được
--  * Về Drill rồi mới sang Church (không thả / nhặt lại nữa)
--  * Church: chỉ vào Workspace.Church, không vào SaveGear (rương gear) ở đầu game
-- Tuỳ chỉnh: S.EPick.enabled / key / stand / waitSeconds / tapGap / tiers / chestRadius
-- ===================================================================
do
    S.EPick = S.EPick or {}
    local EP = S.EPick
    if EP.enabled == nil then EP.enabled = true end
    if EP.afterChestOnly == nil then EP.afterChestOnly = true end
    if EP.debug == nil then EP.debug = true end   -- in lý do khi nhặt hụt
    EP.key = EP.key or Enum.KeyCode.F        -- phím nhặt
    EP.stand = EP.stand or 3                 -- lơ lửng cách item bao nhiêu stud
    if EP.under == nil then EP.under = true end -- true: lơ lửng DƯỚI item, false: phía trên
    EP.waitSeconds = EP.waitSeconds or 8     -- chờ tối đa cho 1 item
    EP.tapGap = EP.tapGap or 0.6             -- giây giữa 2 lần bấm
    EP.holdMin = EP.holdMin or 0.15          -- giữ phím tối thiểu
    EP.holdMax = EP.holdMax or 1.5           -- giữ tối đa (giữ F ~7s là game DROP cả túi)
    EP.chestRadius = EP.chestRadius or 150   -- item rơi trong bán kính này quanh rương
    EP.chestWait = EP.chestWait or 8         -- chờ rương nhả đồ tối đa (giây)
    EP.chestMaxSeconds = EP.chestMaxSeconds or 30
    EP.range = EP.range or 1500              -- chỉ dùng khi afterChestOnly = false
    EP.tiers = { "diamond", "void", "phoenix", "kings" }
    EP.excludeNames = { "helmet", "miner", "kingslayer" } -- không nhặt
    EP.fails = EP.fails or {}
    EP.busy = false
    EP.total = EP.total or 0

    local CATS = { Pickaxe = true, Sword = true, Gun = true, Revive = true }

    local function epCategory(item)
        local ok, cat = pcall(S.getGearItemCategory, item)
        if ok and cat and CATS[cat] then
            return cat
        end
        return nil
    end
    EP.category = epCategory

    -- Món nào được phép nhặt? Revive Kit + Pickaxe/Sword/Gun tier Diamond/Void/Phoenix/Kings.
    function EP.wanted(item)
        local cat = epCategory(item)
        local blob = string.lower((item.Name or "") .. " " .. tostring(item:GetAttribute("DisplayName") or ""))
        blob = blob:gsub("[^%a]", "")
        if not cat then
            -- броня: только сеты Kings/Phoenix (надеваются через Interact)
            local ok, c = pcall(S.getGearItemCategory, item)
            return ok and c == "Armor" and not blob:find("kingslayer", 1, true)
                and (blob:find("phoenix", 1, true) or blob:find("kings", 1, true)) and true or false
        end
        for _, bad in ipairs(EP.excludeNames) do
            if blob:find(bad, 1, true) then
                return false
            end
        end
        if cat == "Revive" then
            return true
        end
        for _, t in ipairs(EP.tiers) do
            if blob:find(t, 1, true) then
                return true
            end
        end
        return false
    end

    -- подбор заменяет вещь в слоте (старая выпадает) → брать только строго лучше текущей
    local baseWanted = EP.wanted
    function EP.wanted(item)
        if not baseWanted(item) then
            return false
        end
        local ws, cs
        local ok, better = pcall(function()
            local cat = S.getGearItemCategory(item)
            ws, cs = S.getWorldGearScore(item), S.getCurrentGearScore(cat, item)
            return ws > cs
        end)
        if not (ok and better == true) then
            EP._skipLogged = EP._skipLogged or {}
            if not EP._skipLogged[item] then
                EP._skipLogged[item] = true
                pcall(appendfile, "DrillFarm.log", os.date("%H:%M:%S") .. " [Gear] пропуск " .. tostring(item.Name) .. " " .. tostring(ws) .. "<=" .. tostring(cs) .. (ok and "" or (" err " .. tostring(better))) .. "\n")
            end
        end
        return ok and better == true
    end

    -- 1) Không kéo item về người cho 4 loại gear này (nguồn gốc lỗi teleport lặp).
    local origBring = S.bringItemToPlayer
    function S.bringItemToPlayer(item)
        if EP.enabled and item and epCategory(item) then
            return false
        end
        return origBring(item)
    end

    -- 2) Auto Equip Best cũ không xử lý 4 loại này nữa.
    local origEquipWorld = S.equipWorldGearItem
    function S.equipWorldGearItem(item)
        if EP.enabled and item and epCategory(item) then
            return false
        end
        return origEquipWorld(item)
    end

    local function itemGone(item, itemsFolder, inWorld)
        return not item.Parent or (inWorld and not item:IsDescendantOf(itemsFolder))
    end

    local function collectPrompts(item)
        local list = {}
        pcall(function()
            if item:IsA("ProximityPrompt") then
                list[#list + 1] = item
            end
            for _, d in ipairs(item:GetDescendants()) do
                if d:IsA("ProximityPrompt") and d.Enabled then
                    list[#list + 1] = d
                end
            end
        end)
        return list
    end

    -- Phím F của game = InteractionService:Interact(item) / DragController:PerformConsoleInteract().
    -- Gọi thẳng các hàm này (giống đường nhặt đang chạy tốt của Scrap) rồi mới bấm phím F.
    local function gameInteract(item)
        pcall(function()
            if S.setDragTarget then
                S.setDragTarget(item)
            end
        end)
        pcall(function()
            local svc = Services.InteractionService
            if svc and type(svc.Interact) == "function" then
                svc:Interact(item)
                for _, d in ipairs(item:GetDescendants()) do
                    if CollectionService:HasTag(d, "Interactive") then
                        svc:Interact(d)
                    end
                end
            end
        end)
        pcall(function()
            local knit = S.getKnit()
            local drag = knit and knit.GetController("DragController")
            if drag then
                drag.Target = item
                if drag.PerformConsoleInteract then
                    drag:PerformConsoleInteract()
                end
            end
        end)
    end

    -- Nhặt 1 item: bay tới 1 lần, lơ lửng trên item + nhìn vào nó, bấm phím tới khi nhặt được.
    function EP.pickupCustom(item, keepThere)
        if not item or not item.Parent then
            return false
        end
        local info = EP.fails[item]
        if info and info.untilAt and os.clock() < info.untilAt then
            return false
        end
        local vim
        pcall(function()
            vim = game:GetService("VirtualInputManager")
        end)
        if not vim then
            return false
        end

        local itemsFolder = Workspace:FindFirstChild("Items")
        local inWorld = itemsFolder ~= nil and item:IsDescendantOf(itemsFolder)
        local prompts = collectPrompts(item)
        local backup = S.preparePromptsForHold and S.preparePromptsForHold(prompts) or nil

        local hold = EP.holdMin
        for _, p in ipairs(prompts) do
            local h = tonumber(p.HoldDuration) or 0
            if h + 0.1 > hold then
                hold = h + 0.1
            end
        end
        hold = math.min(hold, EP.holdMax)

        local prevPin, prevY = Autofarm._mineHoldPos, Autofarm._gatePinY
        local root0 = S.getRoot()
        local home = root0 and root0.CFrame
        S.shardPauseBegin()

        local camBackup
        pcall(function()
            local pos = (S.getInstancePosition and S.getInstancePosition(item)) or S.getItemPosition(item)
            local root = S.getRoot()
            if not pos or not root then
                return
            end

            -- Bay tới ĐÚNG 1 LẦN, neo yên ở đó (không rơi, không tp lặp lại).
            local dy = EP.under and -EP.stand or EP.stand
            local standPos = pos + Vector3.new(0, dy, 0)
            local lastStand = standPos
            Autofarm._mineHoldPos = standPos
            Autofarm._gatePinY = standPos.Y
            root.Anchored = false
            root.CFrame = CFrame.new(standPos)
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            if S.setDragTarget then
                pcall(S.setDragTarget, item)
            end

            local deadline = os.clock() + EP.waitSeconds
            local lastTap = -math.huge
            while os.clock() < deadline and not S._unloading do
                if itemGone(item, itemsFolder, inWorld) then
                    break
                end
                local r = S.getRoot()
                if not r then
                    break
                end
                pos = (S.getInstancePosition and S.getInstancePosition(item)) or S.getItemPosition(item) or pos
                standPos = pos + Vector3.new(0, dy, 0)
                Autofarm._mineHoldPos = standPos
                Autofarm._gatePinY = standPos.Y

                -- Lơ lửng: neo yên tại chỗ; chỉ dời khi item bị trôi đi xa (> 3 stud).
                r.Anchored = true
                r.AssemblyLinearVelocity = Vector3.zero
                if (standPos - lastStand).Magnitude > 3 then
                    lastStand = standPos
                    r.CFrame = CFrame.new(standPos)
                end

                -- Luôn nhìn vào item.
                pcall(function()
                    S.faceCharacterToward(pos)
                    camBackup = S.aimCameraAtWorld(pos, camBackup)
                end)

                -- Bấm phím mỗi tapGap giây cho tới khi nhặt được.
                if os.clock() - lastTap >= EP.tapGap then
                    lastTap = os.clock()
                    gameInteract(item)
                    for _, p in ipairs(prompts) do
                        pcall(function()
                            p:InputHoldBegin()
                        end)
                    end
                    if typeof(fireproximityprompt) == "function" then
                        for _, p in ipairs(prompts) do
                            pcall(fireproximityprompt, p)
                        end
                    end
                    pcall(function()
                        vim:SendKeyEvent(true, EP.key, false, game)
                    end)
                    local t0 = os.clock()
                    while os.clock() - t0 < hold do
                        task.wait(0.05)
                        if itemGone(item, itemsFolder, inWorld) then
                            break
                        end
                    end
                    for _, p in ipairs(prompts) do
                        pcall(function()
                            p:InputHoldEnd()
                        end)
                    end
                    pcall(function()
                        vim:SendKeyEvent(false, EP.key, false, game)
                    end)
                end
                task.wait(0.05)
            end
        end)

        pcall(S.restoreCameraAim, camBackup)
        if backup then
            pcall(S.restorePromptsAfterHold, backup)
        end
        pcall(function()
            local r = S.getRoot()
            if r then
                r.Anchored = false
            end
        end)
        Autofarm._mineHoldPos, Autofarm._gatePinY = prevPin, prevY
        -- Về chỗ cũ (bỏ qua khi đang nhặt cả loạt: chỉ về 1 lần ở cuối).
        if home and not keepThere then
            pcall(function()
                local r = S.getRoot()
                if r then
                    r.CFrame = home
                    r.AssemblyLinearVelocity = Vector3.zero
                end
            end)
        end
        pcall(S.shardPauseEnd)

        if itemGone(item, itemsFolder, inWorld) then
            EP.fails[item] = nil
            EP.total = EP.total + 1
            pcall(S.farmLog, "pickup", tostring(item.Name))
            return true
        end
        local count = ((info and info.count) or 0) + 1
        EP.fails[item] = { count = count, untilAt = os.clock() + (count >= 2 and 30 or 3) }
        if EP.debug then
            local d = -1
            pcall(function()
                local r, ip = S.getRoot(), S.getItemPosition(item)
                d = (r and ip) and math.floor((r.Position - ip).Magnitude) or -1
            end)
            local inv = ""
            pcall(function()
                local cur, mx = S.invStats()
                inv = " inv=" .. tostring(cur) .. "/" .. tostring(mx)
            end)
            print(("[EPick FAIL] %s | %s | dist=%d | prompts=%d%s"):format(
                tostring(item.Name), item.ClassName, d, #prompts, inv))
            pcall(S.notify, "Gear", "Could not pick up " .. tostring(item.Name) .. " (try " .. count .. ")" .. inv, 5)
        end
        return false
    end

    -- Nhặt bằng ĐÚNG cơ chế của Auto Scrap (S.scrapPickItemF):
    -- bay sát item > ngắm camera > bấm F ngắn > kiểm tra item biến mất. Lặp tới khi nhặt được.
    -- Cần Autofarm đang bật (như Auto Scrap); nếu không thì dùng bản tự viết ở trên.
    EP.rounds = EP.rounds or 3   -- số vòng Scrap-F (mỗi vòng ~3 lần bấm F)
    function EP.pickup(item, keepThere)
        if not item or not item.Parent then
            return false
        end
        local info = EP.fails[item]
        if info and info.untilAt and os.clock() < info.untilAt then
            return false
        end
        if type(S.scrapPickItemF) ~= "function" then
            return EP.pickupCustom(item, keepThere)
        end

        local itemsFolder = Workspace:FindFirstChild("Items")
        local inWorld = itemsFolder ~= nil and item:IsDescendantOf(itemsFolder)
        local root0 = S.getRoot()
        local home = root0 and root0.CFrame
        S.shardPauseBegin()
        for _ = 1, math.max(1, EP.rounds) do
            if S._unloading or itemGone(item, itemsFolder, inWorld) then
                break
            end
            pcall(S.scrapPickItemF, item)
        end
        pcall(function()
            local r = S.getRoot()
            if r then
                r.Anchored = false
            end
        end)
        if home and not keepThere then
            pcall(function()
                local r = S.getRoot()
                if r then
                    r.CFrame = home
                    r.AssemblyLinearVelocity = Vector3.zero
                end
            end)
        end
        pcall(S.shardPauseEnd)

        if itemGone(item, itemsFolder, inWorld) then
            EP.fails[item] = nil
            EP.total = EP.total + 1
            pcall(S.farmLog, "pickup", tostring(item.Name))
            return true
        end
        local count = ((info and info.count) or 0) + 1
        EP.fails[item] = { count = count, untilAt = os.clock() + (count >= 2 and 30 or 3) }
        if EP.debug then
            local inv = ""
            pcall(function()
                local cur, mx = S.invStats()
                inv = " inv=" .. tostring(cur) .. "/" .. tostring(mx)
            end)
            print("[EPick FAIL] " .. tostring(item.Name) .. inv)
            pcall(S.notify, "Gear", "Could not pick up " .. tostring(item.Name) .. " (try " .. count .. ")" .. inv, 5)
        end
        return false
    end

    -- ---------- Chỉ nhặt SAU KHI MỞ RƯƠNG ----------
    local function looksLikeChest(inst)
        local cur = inst
        for _ = 1, 4 do
            if not cur or cur == Workspace then
                break
            end
            local n = string.lower(cur.Name)
            if n:find("chest", 1, true) or n:find("mimic", 1, true) then
                return true
            end
            cur = cur.Parent
        end
        return false
    end

    -- Chạy NỀN sau khi mở rương: KHÔNG chặn việc mở rương tiếp theo.
    -- Dò theo VỊ TRÍ quanh rương (giống Auto Scrap), không phụ thuộc snapshot.
    -- Chỉ khi thấy món cần tìm mới chờ + đi nhặt; không thấy thì thôi.
    function EP.watchChestDrops(chest, beforeSet, givenPos)
        local chestPos = givenPos
            or (chest and chest.Parent and ((S.getInstancePosition and S.getInstancePosition(chest)) or S.getItemPosition(chest)))
        if not chestPos then
            return 0
        end

        local function flat(pos)
            local dx, dz = pos.X - chestPos.X, pos.Z - chestPos.Z
            return math.sqrt(dx * dx + dz * dz)
        end

        local function nearItems()
            local all, wanted = {}, {}
            S.forEachWorldLootItem(function(item)
                if not item or not item.Parent or CollectionService:HasTag(item, "ShopItem") then
                    return
                end
                local pos = S.getItemPosition(item)
                if not pos or flat(pos) > EP.chestRadius then
                    return
                end
                all[#all + 1] = item
                local f = EP.fails[item]
                if EP.wanted(item) and not (f and f.untilAt and os.clock() < f.untilAt) then
                    wanted[#wanted + 1] = { item = item, dist = flat(pos) }
                end
            end)
            table.sort(wanted, function(a, b)
                return a.dist < b.dist
            end)
            return wanted, all
        end

        if EP.debug then
            pcall(S.notify, "Gear", "Chest opened - scanning for wanted items...", 2)
        end

        -- Theo dõi rương nhả đồ (không chặn ai). Không có món cần tìm thì thoát.
        local list, all = nearItems()
        local watchUntil = os.clock() + EP.chestWait
        while #list == 0 and os.clock() < watchUntil and not S._unloading do
            task.wait(0.25)
            list, all = nearItems()
        end
        if #list == 0 then
            if EP.debug then
                local names = {}
                for i = 1, math.min(#all, 6) do
                    local it = all[i]
                    local okc, cat = pcall(S.getGearItemCategory, it)
                    names[#names + 1] = tostring(it.Name) .. "(" .. tostring(okc and cat or "-") .. ")"
                end
                local msg = ("No wanted items. Near chest: %d items %s"):format(#all, table.concat(names, ", "))
                print("[EPick] " .. msg)
                pcall(S.notify, "Gear", msg, 5)
            end
            return 0
        end

        -- Tìm thấy món cần: chờ các món còn lại rơi hết, đợi rương khác mở xong rồi mới nhặt.
        if EP.debug then
            pcall(S.notify, "Gear", "Found " .. #list .. " wanted item(s): " .. tostring(list[1].item.Name), 4)
        end
        task.wait(0.6)
        local lockUntil = os.clock() + 20
        while (EP.busy or (EP._opening or 0) > 0) and os.clock() < lockUntil and not S._unloading do
            task.wait(0.1)
        end
        if EP.busy or not EP.enabled then
            return 0
        end

        EP.busy = true
        local picked = 0
        pcall(function()
            local rootStart = S.getRoot()
            local homeCf = rootStart and rootStart.CFrame
            local t0 = os.clock()
            while not S._unloading and EP.enabled and os.clock() - t0 < EP.chestMaxSeconds do
                list = nearItems()
                if #list == 0 then
                    break
                end
                local nm = tostring(list[1].item.Name)
                if EP.pickup(list[1].item, true) then
                    picked += 1
                    pcall(appendfile, "DrillFarm.log", os.date("%H:%M:%S") .. " [Gear] взял " .. nm .. string.char(10))
                else
                    pcall(appendfile, "DrillFarm.log", os.date("%H:%M:%S") .. " [Gear] не взял " .. nm .. string.char(10))
                end
                task.wait(0.05)
            end
            -- Nhặt xong cả loạt mới về chỗ cũ 1 lần.
            if homeCf then
                local r = S.getRoot()
                if r then
                    r.Anchored = false
                    r.CFrame = homeCf
                    r.AssemblyLinearVelocity = Vector3.zero
                end
            end
        end)
        EP.busy = false
        if EP.debug then
            pcall(S.notify, "Gear", "Picked up " .. picked .. " item(s)", 3)
        end
        return picked
    end

    -- Móc vào hàm mở rương (cả Auto Chests lẫn Core run đều đi qua đây).
    EP._opening = 0
    local origHold = S.holdChestInteract
    function S.holdChestInteract(instance, seconds)
        -- Đang trong lượt ghé rương: wrapper bên dưới đã chụp snapshot + sẽ tự theo dõi.
        local inVisit = EP._visitSnap ~= nil
        local doWatch = not inVisit and EP.enabled and EP.afterChestOnly and instance ~= nil
            and looksLikeChest(instance)
        local beforeSet = doWatch and S.snapshotItemsSet() or nil
        local chestPos0 = doWatch and ((S.getInstancePosition and S.getInstancePosition(instance)) or S.getItemPosition(instance)) or nil
        EP._opening += 1
        local okCall, ok = pcall(origHold, instance, seconds)
        EP._opening = math.max(0, EP._opening - 1)
        if not okCall then
            error(ok, 0)
        end
        if ok and doWatch and beforeSet then
            task.spawn(function()
                pcall(EP.watchChestDrops, instance, beforeSet, chestPos0)
            end)
        end
        return ok
    end

    -- Cả lượt ghé rương (bay tới + mở) cũng được tính là "đang mở rương".
    local origVisit = S.autofarmVisitChest
    function S.autofarmVisitChest(chest)
        local watch = EP.enabled and EP.afterChestOnly and chest ~= nil
        if EP.debug then
            print("[EPick] visit chest | watch=" .. tostring(watch))
        end
        -- Chụp danh sách item TRƯỚC khi bấm mở (rương có thể nhả đồ ngay khi Interact).
        local snap = watch and S.snapshotItemsSet() or nil
        local visitPos = nil
        if watch then
            local model = (S.resolveDungeonChestModel and S.resolveDungeonChestModel(chest)) or chest
            visitPos = (S.getInstancePosition and S.getInstancePosition(model)) or S.getItemPosition(model)
        end
        local prevSnap = EP._visitSnap
        EP._visitSnap = snap
        EP._opening += 1
        local okCall, res = pcall(origVisit, chest)
        EP._opening = math.max(0, EP._opening - 1)
        EP._visitSnap = prevSnap
        if not okCall then
            error(res, 0)
        end
        if EP.debug then
            print("[EPick] visit result=" .. tostring(res))
        end
        if res and snap then
            task.spawn(function()
                pcall(EP.watchChestDrops, chest, snap, visitPos)
            end)
        end
        return res
    end

    -- Chế độ cũ (quét theo vùng, bất kể rương): chỉ chạy khi afterChestOnly = false.
    function EP.pass()
        if EP.busy or not EP.enabled then
            return 0
        end
        local root = S.getRoot()
        if not root then
            return 0
        end
        EP.busy = true
        local picked = 0
        pcall(function()
            local list = {}
            S.forEachWorldLootItem(function(item)
                if item and item.Parent and not CollectionService:HasTag(item, "ShopItem") and EP.wanted(item) then
                    local pos = S.getItemPosition(item)
                    if pos then
                        local dist = S.getFlatDistanceFromPosition(pos)
                        if dist <= EP.range then
                            list[#list + 1] = { item = item, dist = dist }
                        end
                    end
                end
            end)
            table.sort(list, function(a, b)
                return a.dist < b.dist
            end)
            if list[1] and EP.pickup(list[1].item) then
                picked += 1
            end
        end)
        EP.busy = false
        return picked
    end

    print("[EPick] loaded | enabled=" .. tostring(EP.enabled) .. " afterChestOnly=" .. tostring(EP.afterChestOnly))
    pcall(S.notify, "Gear", "Auto Pickup Gear (F) loaded - enabled=" .. tostring(EP.enabled), 4)
    if typeof(getgenv) == "function" then
        getgenv().MiyuGUI_EPICK = EP
    end

    task.spawn(function()
        while not S._unloading do
            task.wait(0.5)
            if EP.enabled and not EP.afterChestOnly and not EP.busy and not Autofarm.miningBusy
                and game.PlaceId == MiyuGUI.placeId
            then
                pcall(EP.pass)
            end
        end
    end)
end


-- ===================================================================
-- MiyuGUI patch: xong chest -> về Drill -> rồi mới sang Church (SaveGear)
-- Hook vào S.mineRunBeginStore (Mine Run chest lap xong + Core run chest xong).
-- ===================================================================
do
    local EP = S.EPick
    if EP.deliverToDrill == nil then EP.deliverToDrill = true end
    EP.drillWait = EP.drillWait or 2
    EP._delivering = false

    function EP.goToDrill()
        local cf = S.getDrillReturnCFrame and S.getDrillReturnCFrame()
        local root = S.getRoot()
        if not cf or not root then
            return false
        end
        local prevPin, prevY = Autofarm._mineHoldPos, Autofarm._gatePinY
        Autofarm._mineHoldPos = cf.Position
        Autofarm._gatePinY = cf.Position.Y
        root.Anchored = false
        root.CFrame = cf
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        task.wait(EP.drillWait)
        Autofarm._mineHoldPos, Autofarm._gatePinY = prevPin, prevY
        return true
    end

    local origBeginStore = S.mineRunBeginStore
    function S.mineRunBeginStore()
        local MR = S.MineRun
        if EP._delivering then
            return
        end
        if not (EP.deliverToDrill and EP.enabled and MR and MR.active) then
            return origBeginStore()
        end
        EP._delivering = true
        Autofarm.openChests = false
        MR._lapLock = os.clock()
        task.spawn(function()
            S.shardPauseBegin()
            local ok, at = pcall(EP.goToDrill)
            pcall(S.shardPauseEnd)
            if ok and at then
                S.notify("Gear", "Back at the drill - heading to the church", 4)
            end
            EP._delivering = false
            if MR.active and not S._unloading then
                MR._phaseSince = os.clock()
                origBeginStore()
            end
        end)
    end
end


-- ===================================================================
-- MiyuGUI patch: Save Gear CHỈ ở nhà thờ (Workspace.Church), không vào
-- "SaveGear" / rương gear ở đầu game. Nhà thờ chưa load -> bay về vị trí đã nhớ.
-- ===================================================================
function S.mineRunFindSaveGear()
    local MR = S.MineRun
    local now = os.clock()
    if now - (MR._saveScanAt or 0) < 2.5 then
        return nil
    end
    MR._saveScanAt = now
    pcall(S.mineRunCacheChurch)
    local church = workspace:FindFirstChild("Church")
    if church then
        for _, d in ipairs(church:GetDescendants()) do
            if d.Name == "SaveGear" and d:IsA("BasePart") and not MR._saved[S.mineRunWellKey(d.Position)] then
                return d
            end
        end
    end
    local pos = MR._churchPos
    if pos and not MR._saved[S.mineRunWellKey(pos)] then
        return S.mineRunGoToChurch(pos)
    end
    return nil
end




-- ===================================================================
-- MiyuGUI patch: God Mode (hitbox follows the body at a fixed depth)
-- Your real body does all the physics on the real floor (walking, jumping, no invisible ceiling).
-- Only the position that gets SENT to the server is moved: right after each physics step the whole
-- character is shifted GM.depth studs under the floor, and just before the next frame is rendered /
-- simulated it is moved back. So the hitbox always stays the same distance below your body,
-- also while you jump. Works the same on R6 and R15.
-- Settings: S.GodMode.depth (5 - 25 studs under the floor), S.GodMode.noclip (default on)
-- ===================================================================
do
    local GM = S.GodMode or {}
    S.GodMode = GM
    GM.enabled = false
    GM.depth = math.clamp(tonumber(GM.depth) or 10, 5, 25)
    if GM.noclip == nil then
        GM.noclip = true
    end
    GM._lowered, GM._loweredRoot, GM._lowerAmount = false, nil, 0
    GM._stand, GM._standAt = 3, 0
    GM._conns = {}
    GM._parts, GM._orig, GM._charRef = {}, {}, nil
    local BIND_NAME = "MiyuGUI_GodRestore"

    local function groundY(origin)
        local ignore = {}
        if LocalPlayer.Character then
            ignore[#ignore + 1] = LocalPlayer.Character
        end
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LocalPlayer and plr.Character then
                ignore[#ignore + 1] = plr.Character
            end
        end
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = ignore
        pcall(function()
            params.RespectCanCollide = true
        end)
        local res = Workspace:Raycast(origin, Vector3.new(0, -50, 0), params)
        return res and res.Position.Y or nil
    end

    -- Bring the character back to its real position (what physics and the camera must see).
    local function restore()
        if GM._lowered then
            GM._lowered = false
            local r = GM._loweredRoot
            if r and r.Parent then
                r.CFrame = r.CFrame + Vector3.new(0, GM._lowerAmount, 0)
            end
        end
    end

    -- Move the character under the floor right before it is replicated to the server.
    local function lower()
        if S._unloading then
            GM.set(false)
            return
        end
        restore() -- safety: never stack two shifts
        if not GM.enabled then
            return
        end
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not (hum and root) or hum.Health <= 0 then
            return
        end
        -- Seated (drill / vehicle): the seat weld would drag the whole vehicle down, so skip.
        if hum.SeatPart ~= nil or hum.Sit then
            return
        end
        -- Height of the root part above the floor (R6 ~3, R15 ~3): measured while standing.
        if hum.FloorMaterial ~= Enum.Material.Air and os.clock() - GM._standAt > 0.3 then
            GM._standAt = os.clock()
            local g = groundY(root.Position)
            if g then
                GM._stand = math.clamp(root.Position.Y - g, 1, 6)
            end
        end
        local amount = GM.depth + GM._stand -- hitbox rests `depth` studs under the floor
        GM._lowered = true
        GM._loweredRoot = root
        GM._lowerAmount = amount
        root.CFrame = root.CFrame - Vector3.new(0, amount, 0)
    end

    local function refreshParts()
        local char = LocalPlayer.Character
        if GM._charRef == char then
            return
        end
        GM._charRef = char
        GM._parts, GM._orig = {}, {}
        if char then
            for _, d in ipairs(char:GetDescendants()) do
                if d:IsA("BasePart") then
                    GM._parts[d] = true
                end
            end
            table.insert(GM._conns, char.DescendantAdded:Connect(function(d)
                if d:IsA("BasePart") then
                    GM._parts[d] = true
                end
            end))
        end
    end

    local function noclipStep()
        refreshParts()
        for part in pairs(GM._parts) do
            if part.Parent then
                if part.CanCollide then
                    if GM._orig[part] == nil then
                        GM._orig[part] = true
                    end
                    part.CanCollide = false
                end
            else
                GM._parts[part] = nil
            end
        end
    end

    local function restoreCollision()
        for part, was in pairs(GM._orig) do
            if part.Parent then
                pcall(function()
                    part.CanCollide = was
                end)
            end
        end
        GM._orig = {}
    end

    -- Forces the server to take the new hitbox position right now (no need to jump):
    -- a tiny hop wakes the physics assembly, then a few frames of micro movement keep it replicating.
    function GM.refresh()
        task.spawn(function()
            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if not (hum and root) or hum.Health <= 0 then
                return
            end
            if hum.SeatPart ~= nil or hum.Sit then
                return
            end
            local v = root.AssemblyLinearVelocity
            root.AssemblyLinearVelocity = Vector3.new(v.X, math.max(v.Y, 0) + 16, v.Z)
            for i = 1, 8 do
                RunService.Heartbeat:Wait()
                local r = char:FindFirstChild("HumanoidRootPart")
                if not r then
                    break
                end
                r.CFrame = r.CFrame + Vector3.new(0, (i % 2 == 0) and 0.02 or -0.02, 0)
            end
        end)
    end

    function GM.set(value)
        value = value == true
        if value == GM.enabled then
            return
        end
        if value then
            GM.enabled = true
            GM._charRef = nil
            pcall(function()
                RunService:BindToRenderStep(BIND_NAME, Enum.RenderPriority.First.Value, restore)
            end)
            table.insert(GM._conns, RunService.Stepped:Connect(function()
                restore() -- physics always runs at the real position
                if GM.noclip then
                    noclipStep()
                end
            end))
            table.insert(GM._conns, RunService.Heartbeat:Connect(lower))
            GM.refresh()
            pcall(S.notify, "God Mode", "ON - hitbox " .. GM.depth .. " studs under the floor", 4)
        else
            GM.enabled = false
            pcall(function()
                RunService:UnbindFromRenderStep(BIND_NAME)
            end)
            for _, c in ipairs(GM._conns) do
                pcall(function()
                    c:Disconnect()
                end)
            end
            GM._conns = {}
            restore()
            restoreCollision()
            GM._parts, GM._charRef = {}, nil
            GM.refresh()
            pcall(S.notify, "God Mode", "OFF", 3)
        end
    end

    function GM.setDepth(value)
        GM.depth = math.clamp(math.floor((tonumber(value) or 10) + 0.5), 5, 25)
    end

    function GM.setNoclip(value)
        GM.noclip = value == true
        if not GM.noclip then
            restoreCollision()
        end
    end
end


-- ===================================================================
-- MiyuGUI patch: Auto Mine aura collect + God Mode keybind + Infinite Jump
-- ===================================================================

-- ===== Aura Collect for Auto Mine Ores =====
-- While Auto Mine Ores runs, picks up the ore / gem / smelted-bar drops around YOU from where
-- you stand (no teleporting). Works on its own range, separate from the general Aura Collect.
S.AutoOres = S.AutoOres or {}
if S.AutoOres.auraCollect == nil then
    S.AutoOres.auraCollect = false
end
S.AutoOres.auraRange = math.clamp(tonumber(S.AutoOres.auraRange) or 15, 1, 15)
S.AO_AURA = S.AO_AURA or { busy = false, fails = setmetatable({}, { __mode = "k" }), lastWipe = 0 }

function S.auraMinePass()
    local AO, B = S.AutoOres, S.AO_AURA
    if not (AO and AO.owned and AO.auraCollect) then
        return 0
    end
    local root = S.getRoot()
    local itemsFolder = Workspace:FindFirstChild("Items")
    if not root or not itemsFolder or S.isBagFull() then
        return 0
    end
    local origin = root.Position
    local range = math.clamp(tonumber(AO.auraRange) or 15, 1, 15)
    local now = os.clock()
    local list = {}
    S.forEachWorldLootItem(function(item)
        if not item or not item.Parent or CollectionService:HasTag(item, "ShopItem") then
            return
        end
        if not (S.isSelectedOreDropItem(item) or S.isMinedBarDrop(item)) then
            return
        end
        local pos = S.getItemPosition(item)
        if not pos then
            return
        end
        local dist = (pos - origin).Magnitude
        if dist <= range then
            list[#list + 1] = { item = item, dist = dist }
        end
    end)
    if #list == 0 then
        return 0
    end
    if now - B.lastWipe > 6 then
        B.lastWipe = now
        B.fails = setmetatable({}, { __mode = "k" })
    end
    for _, e in ipairs(list) do
        e.f = B.fails[e.item] or 0
    end
    table.sort(list, function(a, b)
        if a.f ~= b.f then
            return a.f < b.f
        end
        return a.dist < b.dist
    end)
    local batch = math.min(#list, 12)
    for i = 1, batch do
        local it = list[i].item
        if it and it.Parent then S.inGameInteract(it, (B.fails[it] or 0) + 1) end
    end
    task.wait(0.16)
    for i = 1, batch do
        local it = list[i].item
        if it and it.Parent and it:IsDescendantOf(itemsFolder) then
            S.inGameInteract(it, (B.fails[it] or 0) + 2)
        end
    end
    task.wait(0.16)
    local got = 0
    for i = 1, batch do
        local it = list[i].item
        if not it.Parent or not it:IsDescendantOf(itemsFolder) then
            got += 1
            B.fails[it] = nil
        else
            B.fails[it] = (B.fails[it] or 0) + 1
        end
    end
    return got
end

task.spawn(function()
    while not S._unloading do
        task.wait(0.12)
        local AO, B = S.AutoOres, S.AO_AURA
        if AO and AO.owned and AO.auraCollect and not B.busy and game.PlaceId == MiyuGUI.placeId then
            B.busy = true
            local ok, err = pcall(S.auraMinePass)
            B.busy = false
            if not ok then
                warn("[MiyuGUI] Auto Mine aura pass:", err)
            end
        end
    end
end)

-- ===== Infinite Jump =====
S.InfJump = S.InfJump or { enabled = false, conn = nil, last = 0 }
function S.setInfiniteJump(enabled)
    local J = S.InfJump
    J.enabled = enabled == true
    if J.conn then
        J.conn:Disconnect()
        J.conn = nil
    end
    if J.enabled then
        J.conn = UserInputService.JumpRequest:Connect(function()
            if S._unloading or os.clock() - J.last < 0.08 then
                return
            end
            J.last = os.clock()
            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum and hum.Health > 0 then
                hum:ChangeState(Enum.HumanoidStateType.Jumping)
            end
        end)
    end
end


-- ===================================================================
-- MiyuGUI patch: Auto Mine - nearest ore first, clear Mineshafts, drop only when full,
-- Save Gear Anywhere
-- ===================================================================
S.AutoOres = S.AutoOres or {}
if S.AutoOres.nearestFirst == nil then
    S.AutoOres.nearestFirst = true
end
if S.AutoOres.clearMines == nil then
    S.AutoOres.clearMines = true
end
if S.AutoOres.dropWhenFull == nil then
    S.AutoOres.dropWhenFull = true
end

-- Nearest selected ore to the PLAYER (flat distance), wherever it is. After each ore is mined the
-- player stands under it, so the next target is simply the closest one to that spot.
do
    local origFind = S.findOreForAutofarm
    function S.findOreForAutofarm()
        local AO = S.AutoOres
        if not (AO and AO.owned and AO.nearestFirst ~= false) or Autofarm.oreUnderEnabled ~= true then
            return origFind()
        end
        local types = S.getAutofarmActiveOreTypes()
        if type(types) ~= "table" or #types == 0 then
            return nil
        end
        if Autofarm._scrapProcessing or Autofarm._scrapFlushing or Autofarm.miningBusy then
            return nil
        end
        if tick() < (Autofarm.suppressChestOreStopUntil or 0) then
            return nil
        end
        local root = S.getRoot()
        if not root then
            return nil
        end
        local origin = root.Position
        local best, bestScore, bestPos = nil, math.huge, nil
        S.forEachWorldOreNode(function(ore)
            if not ore or not ore.Parent or S.isOreSkipped(ore) then
                return
            end
            if not S.oreMatchesAutofarmSelection(ore) or not S.isOreStillMineable(ore) then
                return
            end
            local pos = S.getOreWorldPosition(ore)
            if not pos or not S.isSaneOrePos(pos) then
                return
            end
            local flat = Vector3.new(pos.X - origin.X, 0, pos.Z - origin.Z).Magnitude
            local score = flat + math.abs(pos.Y - origin.Y) * 0.05 -- flat distance first, height as a tie-break
            if score < bestScore then
                best, bestScore, bestPos = ore, score, pos
            end
        end)
        if best then
            return best, bestPos
        end
        return origFind() -- nothing loaded: keep flying the route until some ore shows up
    end
end

-- Is this position inside the Mineshaft (its bounding box + margin, or near its entrance)?
function S.autofarmInMine(mine, entrance, pos)
    local inside = false
    pcall(function()
        local cf, size = mine:GetBoundingBox()
        local rel = cf:PointToObjectSpace(pos)
        inside = math.abs(rel.X) <= size.X / 2 + 80
            and math.abs(rel.Y) <= size.Y / 2 + 120
            and math.abs(rel.Z) <= size.Z / 2 + 80
    end)
    if inside then
        return true
    end
    if entrance then
        local flat = Vector3.new(pos.X - entrance.X, 0, pos.Z - entrance.Z).Magnitude
        return flat <= 160
    end
    return false
end

-- Stay in the Mineshaft until every selected ore inside it is mined out.
function S.autofarmClearMineOres(mine, entrance)
    local AO = S.AutoOres
    local range = S.getAutofarmOreHuntRange()
    local function filter(pos)
        return S.autofarmInMine(mine, entrance, pos)
    end
    local function remaining()
        local n = 0
        for _, e in ipairs(S.collectAutofarmSelectedOres(range)) do
            if filter(e.pos) then
                n += 1
            end
        end
        return n
    end
    local left = remaining()
    local guard, stalls = 0, 0
    local deadline = os.clock() + 900
    while left > 0 and Autofarm.enabled and guard < 80 and os.clock() < deadline do
        if S.autofarmVisitStale() then
            break
        end
        Autofarm._busySince = tick() -- a long clear must not trip the cycle watchdog
        S.autofarmUnderMinePass({ range = range, seconds = 40, uncapped = true, filter = filter })
        guard += 1
        if AO.dropWhenFull ~= false and S.isBagFull() and S.isDropInDrillMode() then
            Autofarm._busySince = tick()
            pcall(S.autofarmDumpBagToDrill)
            task.wait(0.25)
        end
        local now = remaining()
        if now >= left then
            stalls += 1
            if stalls >= 3 then
                break -- nothing is getting mined (bag full / unreachable): do not loop forever
            end
        else
            stalls = 0
        end
        left = now
    end
    S.farmLog("mine clear", string.format("left=%d", left))
end

-- ===== Save Gear Anywhere (World tab): fires the church Save Gear prompt from where you stand =====
function S.saveGearAnywhere()
    S.notify("Manual Save Gear", "Use Load Available Gear, select items, then Save Selected Gear Anywhere.", 5)
end

-- God Mode keybind (Player tab > Keybinds): flip God Mode directly (the generic toggle path only
-- changes what the switch shows).
do
    local origToggle = S.toggleRayfieldFlag
    function S.toggleRayfieldFlag(flagName)
        if flagName == "miyugui_godmode" and S.GodMode then
            S.GodMode.set(not S.GodMode.enabled)
            pcall(S.trySetRayfieldFlag, "miyugui_godmode", S.GodMode.enabled, true)
            return
        end
        return origToggle(flagName)
    end
end
